window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_028"]={"n":"边贡","dyn":"明","poems":[{"t":"题美人","f":"七言绝句","c":["月宫秋冷桂团团，岁岁花开只自攀。","共在人间说天上，不知天上忆人间。"]},{"t":"赠尚子","f":"七言古诗","c":["意气凭凌一当百，关西儒生五陵客。","少年学书复学剑，老大蹉跎双鬓白。","门下诸生半赐麻，闺中小妇犹炊麦。","布衣东来谒天子，春日醉卧长安陌。","陌头花絮夕纷纷，琼阁如天隔紫云。","浩歌翩然却归去，眼底谁是平原君。"]},{"t":"望陵二首 其一","f":"五言律诗","c":["徙倚东峰下，西陵望郁然。","玄宫深閟日，玉座迥浮烟。","风雨清明候，乾坤正德年。","攀龙无处所，空有泪潺湲。"]},{"t":"望陵二首 其二","f":"五言律诗","c":["忆在先朝日，曾沾侍从恩。","鸾舆归寂寞，凤质俨生存。","夕日昏阡树，春风长涧蘩。","祠官如可乞，长奉泰陵园。"]},{"t":"过寿陵故址","f":"五言律诗","c":["玉体今何所，遗墟夕霭凝。","宝衣销野燐，碧瓦蔓沟藤。","成戾崩年谥，恭仁葬后称。","千秋同一毁，不独汉唐陵。"]},{"t":"沙河","f":"五言律诗","c":["放马野田草，路回登古原。","鸡鸣桑下屋，牛卧雨中村。","薄日浮山影，长桥下水痕。","煌煌中使出，束帛向陵园。"]},{"t":"承闻诏迎圣母太妃还宫 其一","f":"五言律诗","c":["兆启封邦日，图开继统春。","汉南王化远，天下母仪新。","侍寝随宫眷，留行聚国人。","嗣皇敦孝理，瞻望黼衣频。"]},{"t":"承闻诏迎圣母太妃还宫 其二","f":"五言律诗","c":["济水朝京甸，燕关镇海流。","九重迎圣母，千里会诸侯。","日月开黄道，河山列素秋。","礼文同扈跸，元不为宸游。"]},{"t":"送都玄敬二首 其一","f":"五言律诗","c":["才高怜晚达，十载尚为郎。","书买黄金尽，愁生白发长。","夏曹分武库，秋殿别文昌。","木脱霜皋冷，何人共采芳。"]},{"t":"送都玄敬二首 其二","f":"五言律诗","c":["驱马别君处，秋阴当暮生。","林柯无静叶，江雁有归声。","绿水阊门道，青山建业城。","未能同理楫，延伫独含情。"]},{"t":"留别张西盘大参二首 其二","f":"五言律诗","c":["满酌岂辞醉，未行先忆君。","山城稀见菊，关树不开云。","地入河源渺，天连塞日曛。","那堪北来雁，偏向别时闻。"]},{"t":"泛湖","f":"五言律诗","c":["此日秋风起，移舟向浦烟。","客心随地远，人语隔花传。","古寺疏林外，孤亭落照前。","十年尘土梦，回首一茫然。"]},{"t":"赵丽卿豸史座留别限韵","f":"五言律诗","c":["听雨罢弹棋，苍茫生远思。","遥应白门柳，飘荡绿烟丝。","旅迹江花笑，归心海燕知。","倚酣方恋别，休诵渭城诗。"]},{"t":"寇中丞北抚宣府奉同南渠韵 其二","f":"七言律诗","c":["守边犹得近邦畿，亚相权兼大将威。","乌府夜閒关月皎，戟门秋静虏尘稀。","探兵入塞无传箭，敕使临戎有赐衣。","闻道六龙巡幸所，至今常见五云飞。"]},{"t":"谒文山祠","f":"七言律诗","c":["丞相英灵犹未消，绛帷灯火䬃寒飙。","乾坤浩荡身难寄，道路间关梦且遥。","花外子规燕市月，水边精卫浙江潮。","祠堂亦有西湖树，不遣南枝向北朝。"]},{"t":"郊斋有作呈北寺旧僚长 其一","f":"七言律诗","c":["石城钟鼓散鸣鸦，坐对松云放早衙。","瑶草色通西苑路，玉箫声度上清家。","江涵碧殿春同丽，雪霁钟山日转华。","此景北都应未有，品题遥向故人誇。"]},{"t":"次献吉留别韵","f":"七言律诗","c":["初春郊甸积雪满，客子出门岐路长。","征车杳杳去不息，关柳青青愁未央。","却望泰山怀故道，即归梁苑亦他乡。","十年京洛交游地，日夕风烟思渺茫。"]},{"t":"奉次毕司空与客对弈谢荅张侍御惠酒之作是日司空招予出城不及赴","f":"七言律诗","c":["灌木阴阴曲绕塘，水风如雨细生凉。","绣衣家酝携兼至，太傅围棋兴转长。","檐日晚移文石静，荷樽秋泛露华香。","烂柯欲步王樵武，惆怅仙踪隔苑墙。"]},{"t":"冬至上陵途中杂咏八首 其二","f":"五言绝句","c":["苍苍土门口，日出逢樵叟。","问尔何事来，山中苦无酒。"]},{"t":"无题二首 其二","f":"五言绝句","c":["庭际何所有，有萱复有芋。","自闻秋雨声，不种芭蕉树。"]},{"t":"送刘约中之金陵","f":"五言古诗","c":["自君之出矣，途长梦亦遥。","南风何日起，吹转木兰桡。","自君之出矣，长望石头山。","山高望不极，目送碧云还。","君到石城边，应看石城树。","树杪百尺台，是侬行乐处。"]},{"t":"山行即事二首 其二","f":"七言绝句","c":["陵署青青生午烟，山渠㶁㶁响春泉。","白头宫监松林下，閒说英皇北狩年。"]},{"t":"中元见月","f":"五言绝句","c":["坐爱清光好，更深不下楼。","不因逢闰月，今夜是中秋。"]},{"t":"题子立扇头","f":"五言绝句","c":["江静无飞鸟，亭空有落花。","主人何所在，沽酒向渔家。"]},{"t":"迎銮曲二十首和刘希尹之作 其二","f":"七言绝句","c":["金陵自古帝王都，碧石清江俨画图。","五圣百年虚想像，鸾舆曾到此间无。"]},{"t":"迎銮曲二十首和刘希尹之作 其三","f":"七言绝句","c":["滚滚飞尘千里馀，驿途来往日无虚。","皇心旦夕怀慈圣，数遣中官问起居。"]},{"t":"迎銮曲二十首和刘希尹之作 其五","f":"七言绝句","c":["绿柳阴中显赭黄，路人争说见君王。","只为荐新供寝庙，水边终日打鱼忙。"]},{"t":"迎銮曲二十首和刘希尹之作 其六","f":"七言绝句","c":["孝陵重树紫金山，王气葱葱碧汉间。","灵殿本无荒草入，扫除霜露始应还。"]},{"t":"迎銮曲二十首和刘希尹之作 其七","f":"七言绝句","c":["自采民风问老农，微行不遣近官从。","那知天子关天象，到处云成五色龙。"]},{"t":"迎銮曲二十首和刘希尹之作 其九","f":"七言绝句","c":["青龙山下虎蹄新，玄武湖中跃锦鳞。","错意吾皇好渔猎，不知端访后车人。"]},{"t":"迎銮曲二十首和刘希尹之作 其十一","f":"七言绝句","c":["弓如满月向江开，箭插寒潮捲浪回。","水上鼋鼍莫深避，我皇元为射蛟来。"]},{"t":"迎銮曲二十首和刘希尹之作 其十六","f":"七言绝句","c":["九月南征九月回，清源黄菊趁时开。","何人得似行宫蕊，两度亲承万寿杯。"]},{"t":"迎銮曲二十首和刘希尹之作 其十七","f":"七言绝句","c":["瑟瑟金风鸣玉銮，路车何日到长安。","官河不似江涛险，只恐秋深白露寒。"]},{"t":"迎銮曲二十首和刘希尹之作 其二十","f":"七言绝句","c":["郊祀元居百礼先，史文虚拟阙今年。","小臣曾读三王纪，冬至由来始祭天。"]},{"t":"题扇寄寿春希尹","f":"七言绝句","c":["淮南花雨送春还，丛桂阴阴郡阁閒。","自是刘安有仙骨，谪居犹近八公山。"]},{"t":"夜宿太常官舍怀元佐二首 其一","f":"七言绝句","c":["咫尺东曹信渺然，别离何似路三千。","松窗月色槐阴雨，一夜愁心似隔年。"]},{"t":"赠长垣宗室","f":"七言绝句","c":["瑶室青编万卷余，宫中谁道日闲居。","家臣昨夜长安去，犹向君王乞秘书。"]},{"t":"辛巳书事七首 其一","f":"七言律诗","c":["居庸碣石控胡门，玉几由来北极尊。","阁道逶迤经海岱，天河隐见出昆崙。","斗间遥识三阶列，日下从知九轨存。","奠鼎卜郊非浪事，万年圭鬯保文孙。"]},{"t":"辛巳书事七首 其二","f":"七言律诗","c":["泰陵松柏五云高，再见周康握赤刀。","南斗龙文占王气，中原驰道拥旌旄。","要荒不乱贻谋远，磐石相维缔搆牢。","弘治名臣天慭在，元功应数旧萧曹。"]},{"t":"辛巳书事七首 其三","f":"七言律诗","c":["龟食庚庚发启光，龙颜日角映扶桑。","九朝琬琰陈东序，万国山河履职方。","总道祥麟传宝箓，更看天派渡银潢。","轩虞落落鸿钧转，矫首沧溟望八荒。"]},{"t":"辛巳书事七首 其六","f":"七言律诗","c":["内使传宣总插貂，虎贲联络递乘轺。","尔曹肉食浑无赖，天下军输半已凋。","朔雪炎风归紫极，铜驼金马郁青霄。","万年历服超三五，努力夔龙佐帝尧。"]},{"t":"踏莎行","f":"古风","c":["露湿春莎，草生芳甸，渔舟迤逦依山转。","斜阳明灭照村墟，绿槐深护幽人院。","小栅鸣鸡，古梁巢燕，柴门不锁蓬蒿遍。","问渠莫是武陵源，一溪流水桃花乱。"]},{"t":"蝶恋花 留别吴白楼","f":"古风","c":["亭外潮生人欲去，为怕秋声，不近芭蕉树。","芳草碧云凝望处，何时重话巴山雨。","三板轻船频唤渡，秋水疏杨，欲折丝千缕。","白雁横天江馆暮，醉中愁见吴山路。"]},{"t":"登岳次刘希尹韵四首 其一","f":"七言律诗","c":["岱宗山秀百灵屯，壁立烟霄万古存。","幽府化机盘地轴，上清真气接天门。","霞标日观青松丽，春透龙池碧水温。","薄暮振衣峰顶石，蓬莱东眺海云昏。"]},{"t":"五杂组戏三平董兄","f":"古风","c":["五杂组，袖中绡。","往复还，金翠翘。","不得已，且逍遥。","五杂组，佩琼玖。","往复还，捧觞妇。","不得已，且开酒。","五杂组，锦绣帷。","往复还，城外岐。","不得已，换行媒。","五杂组，床上裯。","往复还，使者愁。","不得已，正绸缪。","五杂组，富家筵。","往复还，河上船。","不得已，买花钱。"]},{"t":"将归篇闻希尹有东归之念作此招之","f":"五言古诗","c":["对面有乖绝，千里长相思。","登高望来车，入门赋将归。","惊风何飘飘，兽兔莽间啼。","群鸟各有趋，他乡难独依。","独依令人感，悠悠浮云驰。","悠悠尚可道，霜露陨百草。"]},{"t":"客至","f":"七言律诗","c":["坐听寒鼓二更馀，一榻全胜两地书。","愁到几时凭我解，病从今日为君除。","雪泥满地淹行李，云岛如天阻卜居。","莫怪明朝欲投辖，江湖回首雁应疏。"]},{"t":"哭天瑞 其四","f":"七言律诗","c":["百年豪气未消磨，北骑南航苦更多。","恋阙有怀随口出，乞祠无计奈身何。","山连巴蜀云层瘴，春入潇湘水漫波。","最是游魂招不得，隔江愁听楚人歌。"]},{"t":"春日杂兴集杜句 其一","f":"七言绝句","c":["二月已破三月来，百年多病独登台。","支离东北风尘际，怀抱何时得好开。"]},{"t":"春日杂兴集杜句 其四","f":"七言绝句","c":["自从官马送还官，信有人间行路难。","独在阴厓结茅屋，强移栖息一枝安。"]},{"t":"寿歌三章为松鹤翁作 其一","f":"七言绝句","c":["松袅山堂红日开，天风吹鹤下瑶台。","传书为问西王母，别后蟠桃熟几回。"]},{"t":"显陵五章送严介溪宗伯","f":"古风","c":["于穆献考，睿哲维则。","宅兹郢方，以莅王国。","笃生我后，膺符受历。","奕世丕承，下土是式。","滔滔江汉，翼轸之墟。","我后龙翔，奄正中区。","诞基骏命，聿绍鸿图。","赫赫明明，肇阐徽谟。","帝念孝思，继序不忘。","位号既崇，复我天常。","有严新庙，祠礿烝尝。","是典是彝，诞告多方。","乃命司空，伐石京师。","郁郁我陵，大建厥规。","载经载营，竹花卜釐。","立极考度，备物多仪。","帝属其文，经纬七曜。","贞观崇封，勒我纯孝。","亿万斯年，汤孙是诏。","天人肃肃，卫兹隧道。"]},{"t":"隰柳三章寿林母也三首","f":"古风","c":["隰则有柳，原则有杻。","显允林侯，母德且寿。","母寿维何，七秩是望。","母德维何，媲古敬姜。","殷殷其雷，在山之阳。","侯政有声，闻于东方。","匪维东方，四国是扬。","母心则閒，母体则康。","体之康矣，剃之黄矣。","我侯燕喜，家之庆矣。","于百斯年，钖福之无疆矣。"]},{"t":"朝涉篇六章","f":"古风","c":["朝涉洪流，夕步江皋。","凯风吹衣，游子心劳。","岸则有藻，江则有鱼。","我钓我采，荐之中厨。","昔曳里布，以献以舞。","今也则亡，敢曜斯组。","繄祭五鼎，厥养乃三。","禄不逮存，哀哀孰堪。","上冢爇黄，下冢回首。","嗟嗟游子，行役已久。","暧暧暮光，萧萧白杨。","永怀二人，曷也可忘。"]},{"t":"圃田诗三章","f":"楚辞体","c":["圃有田，田田兮，宜我硕实连连兮。","圃之中兮，有田可宫。","我构斯崇，维柏维桐，曷以弗永终。","圃之周兮，翼翼盈我畴兮。","畴有秋兮，曷其求兮。"]},{"t":"泉之滨哀隐士也 其一","f":"楚辞体","c":["泉之滨兮，白石磷兮。","以饮以濯，育吾真兮。"]},{"t":"泉之滨哀隐士也 其二","f":"楚辞体","c":["泉之浒兮，锡之土兮。","载浚载渠，溉之溥兮。"]},{"t":"泉之滨哀隐士也 其三","f":"楚辞体","c":["人之坠矣，泉之匮矣。","瞻言跂兮，众之喟兮。"]},{"t":"山之阳送朱子宜归省","f":"楚辞体","c":["山之阳兮，有春者晖。","草之华矣，将子言归。","山有泉兮，㶁㶁其流。","子之归矣，谁与我晤游。","子之归矣，登堂寿母。","何以赠子，曰有春酒。"]},{"t":"次韵题豫斋扇","f":"五言古诗","c":["适意无多言，一笑成莞尔。","我心寒沙月，君心古潭水。","莫作江上波，随风夜中起。"]},{"t":"送别台峰","f":"五言古诗","c":["皎皎中庭月，照此离客颜。","月沈会有升，客去何当还。","采采园中瓜，袅袅不可攀。","草木本无知，枝蔓相钩环。","如何宦游子，岐路长间关。","散如蓬逐风，聚如云在山。","聚散本莫期，毋嗟涕潺潺。"]},{"t":"茗屿","f":"五言古诗","c":["湑湑海气白，楚楚衣冠聚。","谁开高奥灵，太尉体光贮。","缅仰世则公，乐兹清茗屿。"]},{"t":"盘谷","f":"五言古诗","c":["佳气何盘盘，松柏丛林壑。","上有大宗祠，棠棣华繁鄂。","始自一人身，分此千万络。"]},{"t":"宗会庙","f":"五言古诗","c":["庙貌俨生存，妥灵绥后禄。","水木有本源，十辐同一毂。","四百馀年来，因之序昭穆。"]},{"t":"时思堂","f":"五言古诗","c":["苍凉海日曙，堂下森兰玉。","愿言永孝思，俎豆差繁缛。","岁岁荐烝尝，采蘋清涧曲。"]},{"t":"环翠楼","f":"五言古诗","c":["楼前冢累累，陇上麦青青。","岛雾开远岫，海霞明空庭。","夜半松声作，凄其不忍听。"]},{"t":"延月轩","f":"五言古诗","c":["松上有海鹤，松下有泉石。","轩中几格明，轩外狐兔迹。","延览兴遐情，半窗山月白。"]},{"t":"望云亭","f":"五言古诗","c":["觱沸此槛泉，脉自龙湫来。","飞出两白龙，划然丹壁开。","倚亭望长云，从天喷风雷。"]},{"t":"世祀田","f":"五言古诗","c":["朝耕高奥田，莫耕高奥田。","粢盛戒清酤，伏腊击肥鲜。","良哉古人意，以此奉周旋。"]},{"t":"观苏门山图","f":"五言古诗","c":["昔予祇皇役，弭节苏门山。","展眺孙登祠，薄暮松扉关。","凄风振林木，䬃䬃流区寰。","如聆长啸音，来彼白云间。","又如见青蓑，囊琴弄潺湲。","缅怀沈冥志，上与沮溺班。","一别期再游，欲往途路艰。","临图起遐想，延伫久忘还。"]},{"t":"再游石门洞","f":"五言古诗","c":["苍然郭东山，百丈萦青碧。","石门忽中断，窈窕开仙宅。","遥窥日月深，却转烟雾隔。","中天屹楼居，星斗挂几席。","芳岩眩绮绣，丛巘围苍壁。","山鬼不避人，惊猿啸窥客。","披榛上孤亭，奇观壮心魄。","穷崖倚天悬，瀑水半空射。","高流横杂佩，直下垂疋帛。","分作四山喧，散为千顷泽。","初冬天未寒，晨曦映岚赫。","重来意弥眷，独往任所适。","信美惬心期，胡为老行役。","终然脱尘网，高举凌风翮。"]},{"t":"送王内使敬夫归省","f":"五言古诗","c":["归骖慕乡土，欲止不可能。","朝发华阴祠，日夕过灞陵。","风林散轻雨，山店明春灯。","忽忆旧时路，别来如更增。","蟏蛸缀檐牙，游子行到家。","邻里登墙头，顾望纷且哗。","堂前列车马，堂上生光华。","何以为亲寿，宫衣明绣花。","草堂近终南，采兰日往来。","兄弟各相勉，行歌咏南陔。","亲心日以悦，亲颜日以开。","閒时语家庆，笑指庭中槐。","春潭水烟青，春岸杏花赤。","宛转沙上径，依依记行迹。","濯缨清浅流，还坐旧苔石。","鸥鹭了不惊，遥应识归客。","春分酒初熟，香满青门店。","匹马随双童，穿林复经堑。","夜窗清梦里，花笔生彩焰。","好是南山灵，相寻索诗欠。","我思何所在，乃在樊川沚。","斜月照虚梁，微风动芳芷。","悠悠抱沈念，脉脉感前喜。","尺练难重持，春冰限双鲤。","君陂水多鱼，我湖山有鹊。","一飞与一潜，各自相娱乐。","同游京辇下，十载镇如昨。","昨夜问君行，朝来宦情薄。","君才比天马，高躅不可蹈。","我心寔亡羊，多岐赖君导。","关山一为别，轮轸何时到。","感激木瓜篇，琼琚愧相报。","枕书卧南窗，月黑灯不明。","遥夜无近梦，深交有遐情。","鸣琴写幽怀，调苦弦亦清。","曲罢不成寝，高林啼曙莺。","秣马西送君，行行古城阴。","长亭短亭路，千里万里心。","春绿变山草，连连冈与岑。","归林渺烟光，彷佛闻车音。"]},{"t":"送陈文鸣 其一","f":"五言古诗","c":["郁郁深涧松，冬夏不改青。","濯濯江柳花，随波化流萍。","羡彼五陵客，终朝宴芳腥。","三楚多秀士，皓首穷六经。","谁为尺一书，荐之升王廷。"]},{"t":"送陈文鸣 其二","f":"五言古诗","c":["达人㣘高义，立志不苟同。","长啸六合表，傲睨一世中。","君看今日颜，不及昨日红。","乘运各努力，扬休树德风。","颓年傥相值，跨鹤蓬莱东。"]},{"t":"次何逊落日泛江赠鱼司马之作奉送刘美之","f":"五言古诗","c":["相投已盍簪，相赠还留带。","昨暮长安西，今朝苑城外。","谁言车马地，复得须臾会。","会君心暂悦，去君心转切。","秋岐蔓寒草，隐隐烟不绝。","归雁影联翩，坠叶声骚屑。","端居尚兴感，况乃万里别。","桂舸溯江湘，何时到蛮汭。","蛮水夜悠悠，月明登郡楼。","幽兰翠萦渚，紫蘅香绕洲。","应歌楚人词，坐惜勋名浮。"]},{"t":"美之席上限韵送别二首 其一","f":"五言古诗","c":["恻恻重恻恻，当歌忽成默。","客车驾双轮，欲挽不可得。","华灯粲宵焰，殷勤照行色。","月转庭榭光，风起檐树黑。","谁能理朱丝，为鼓长相忆。"]},{"t":"美之席上限韵送别二首 其二","f":"五言古诗","c":["悠悠清川波，矫矫风林翼。","翼飞邈难止，波去何时息。","怜君万里行，莽莽天南北。","罹纷有孤操，涉远无近力。","不见寒松枝，岁晚青更直。"]},{"t":"赋得将有事于西畴送王中丞致仕","f":"五言古诗","c":["发春惊蛰始，土脉动渊泉。","时雨宵既零，浮阳蔼平阡。","夙兴饰耒耜，驱牛登广原。","竭兹畎亩力，感彼农父言。","穑事依东作，天时易流愆。","南邻有逸夫，日晏高枕眠。","四体苟不勤，何以穷岁年。"]},{"t":"送王叔武使河南便道省觐二首 其一","f":"五言古诗","c":["黄河三尺雪，冰厚不可解。","使君白马来，青云见风采。","萧萧梁园竹，秀色遥相待。","邹生与枚叟，借问今安在。","日暮登吹台，含情向千载。"]},{"t":"送王叔武使河南便道省觐二首 其二","f":"古风","c":["奕奕明农堂，脩楣耀晴彩。","堂前春草绿，堂上春云叆。","游子日下还，宫衣试新綵。","夕膳饪鲜鳞，晨羞荐芳?。","何以祝亲寿，如山复如海。"]},{"t":"章氏园饯别升之分得木字","f":"五言古诗","c":["中园飞雨过，逍遥散遐瞩。","青云荫华榱，回飙撤炎燠。","百卉何葳蕤，芳菲鲜如沐。","驾言赠远人，采采沟中绿。","迟回未终极，阳景沉西陆。","归骥嘶长林，翔禽鸣高木。","感物多所思，褰裳以踯躅。","踯躅不可留，何以慰衷曲。"]},{"t":"送王盛","f":"五言律诗","c":["朝辞双阙下，暮抵三河宿。","古戍早鸿稀，荒城寒草绿。","上官山吏拜，行县村童逐。","冉冉松间亭，何人伴幽独。"]},{"t":"秋郊别意为汝南孟翁补作二首 其一","f":"五言古诗","c":["驱车循广术，言返故乡县。","晨光一何绮，熹微散秋甸。","宛宛墟曲中，盈盈露华泫。","因之感游寓，物候倏已变。","岂薄骨肉情，遥重桑梓恋。"]},{"t":"秋郊别意为汝南孟翁补作二首 其二","f":"五言古诗","c":["桑梓在何许，蔼蔼汝南村。","绿丛带长薄，清川映柴门。","言别上春时，当秋始来还。","禾黍一已穫，膴膴见高原。","落日樵牧归，凉风散鸡豚。","登堂见邻叟，呼儿具盘飧。","依依丘中情，款款醉后言。","即尔足为乐，安用乘华轩。"]},{"t":"别刘子二章 其一","f":"五言古诗","c":["文车驾四牡，迤逦度层阿。","伊人秉朝宪，结绶辞承华。","飞龙御宸极，期运亨以嘉。","甘霖雨九天，皇泽被幽遐。","顾念囹圄子，累累诚可嗟。","宪章苟不渝，歼戮岂在多。","行哉布天惠，庶以和邦家。"]},{"t":"别刘子二章 其二","f":"五言古诗","c":["昔我二三子，弱冠登皇朝。","并迹协兰芳，联翩振华镳。","朝出长杨苑，日夕憩平皋。","逝矣终遐月，绸缪以逍遥。","顾子迈南江，刘侯踰上郊。","嘉好一乖别，驰光倏飘飖。","临川睇浮云，结思如回潮。"]},{"t":"次韵赠李子行之如陈","f":"五言古诗","c":["迢迢阻欢宴，戚戚伤离居。","离居结中怀，郁郁惨不舒。","若人美无度，贞抱冲以虚。","朝为同朝客，夕暮隔林墟。","林墟积秋霖，流潦不可除。","四野晦苍苍，行行安所如。","驱马临大道，瞻顾空踟躇。"]},{"t":"奉送大司马华容刘公致仕二首 其一","f":"五言古诗","c":["蔼蔼东山云，覆彼山下堂。","乘时播皇泽，从龙弥八荒。","八荒辽且邈，下上以翱翔。","龙逝鼎湖阴，云归故山阳。","何以慰蒸庶，私衷郁彷徨。"]},{"t":"奉送大司马华容刘公致仕二首 其二","f":"五言古诗","c":["草堂何所有，有兰复有芝。","采采山之侧，飞仙相与期。","寄傲云霞问，可望不可追。","抗手谢城市，去去从此辞。","徒遗高世风，永系来哲思。"]},{"t":"为杨子赋别母诗","f":"五言古诗","c":["青骊载华毂，宛转度秋坂。","母氏远别离，客子心缱绻。","行行采芳蕙，缘陔复循畹。","山风夕飘飖，吹我车上幰。","车行不可返，母去日以远。","何以保黄发，对子加餐饭。"]},{"t":"追送宗之宪副不及","f":"五言古诗","c":["卧疴起恒晏，出户客已行。","征车扬素尘，窈窕踰层城。","行行遵故辙，阡术纵以横。","望望不见君，悠悠伤我情。","清川回白日，可以鉴中诚。"]},{"t":"送沈仁甫归省二章 其一","f":"五言古诗","c":["瞻夕临广郊，欢宴良须臾。","之子驾言返，高登郁踟躇。","不惜形影阔，所悲岁月踰。","三江旷绵邈，悠悠限东隅。","征途慎所须，愿保千金躯。"]},{"t":"送沈仁甫归省二章 其二","f":"五言古诗","c":["品服耀有辉，班裳以裼之。","桑梓诚可恋，道路安足辞。","馨羞洁甘旨，爰以隆孝思。","徘徊膝下欢，婉娈及良时。","修龄欲有祝，永与南山期。"]},{"t":"元夕致仁宅咏灯送别","f":"五言古诗","c":["佳辰逼元夕，宴语春雪馀。","梁灯一何艳，流光照离袪。","灯烬可复燃，袪解难重挐。","盈盈江上心，感念成欷歔。","相看已不极，相忆当何如。"]},{"t":"赠王文熙五首 其一","f":"五言律诗","c":["阳鸟流归音，空堂春风早。","居人结远梦，行子就长道。","鸡鸣东方白，整驾何草草。","叹息素冠诗，繁忧满中抱。"]},{"t":"赠王文熙五首 其二","f":"五言古诗","c":["总辔城东门，绻绻行子辀。","郊原茂时卉，林薄鸣春鸠。","登高眺连冈，川途邈且脩。","俯睇川上波，泛泛凫与鸥。","一为离群感，泪下不能收。"]},{"t":"赠王文熙五首 其三","f":"五言古诗","c":["昔子往恒山，仓卒不我辞。","朅从恒山至，鞶绖何累累。","素室曜朱火，哀哀读丧仪。","一读一长号，再读声转悲。","咄嗟荼苦心，逝者宁见知。"]},{"t":"赠王文熙五首 其四","f":"五言古诗","c":["逝者为何人，寔惟子先公。","往昔涖吾土，蔼蔼多仁风。","土人至今思，譬若考与宗。","梁木一朝毁，伤哉吾道穷。","对子揽长涕，谁谓出无从。"]},{"t":"赠王文熙五首 其五","f":"五言古诗","c":["平居恨迢远，卜舍依我庐。","如何别我去，三载天一隅。","留之叹无因，欲往路崎岖。","形影隔参商，托彼云中书。","不如斯须立，暂得话踟蹰。"]},{"t":"再送文熙二首 其一","f":"五言古诗","c":["夜久河汉横，春堂别灯黯。","风凄鸟初动，露重花犹敛。","明发不在兹，重关为谁掩。"]},{"t":"再送文熙二首 其二","f":"五言古诗","c":["离言不可听，离怨不可书。","一日比三秋，兹言良非虚。","江深云木远，去去将焉如。"]},{"t":"送县令代刘永宁作","f":"五言古诗","c":["南邦有佳士，淳朴君子风。","登朝十年馀，墨绶犹在躬。","维昔治莆日，化与由也同。","监司匪宣尼，谁哉赏其功。","再命涖恒山，冰心晚弥笃。","予惭旧令尹，有政不可告。","驱车蓟门外，把酒燕台曲。","大道坦且直，一试千里足。"]},{"t":"赠何邦彦二首 其一","f":"五言古诗","c":["花林霁宵雨，柔碧光离离。","美人驾行车，迤逦双轮迟。","轮迟无终极，亲爱从此辞。","何以结绸缪，玉瓶金屈卮。","浮云暗长路，奄忽天一涯。","穷谷多狼豺，水蛰虺与螭。","客子戒远道，行行欲安之。"]},{"t":"赠何邦彦二首 其二","f":"五言古诗","c":["行行欲安之，肃肃持邦刑。","藉藉于公誉，峨峨高汉廷。","君心如列宿，照野何晶荧。","又如日在空，皎皎悬丹扃。","岂令囹圄子，恻恻归沈冥。"]},{"t":"别熊子三章 其一","f":"五言古诗","c":["驱马陟前阪，惆怅送子归。","良晤未及终，车徒忽已违。","阴风蔽天地，砂砾惨阳晖。","葵霍不自谋，众禽相与飞。","五里一反顾，十里一徘徊。","徘徊不可见，泪下沾我衣。"]},{"t":"别熊子三章 其二","f":"五言古诗","c":["车徒去弥远，言驻澧水阳。","婉娈谐二亲，春晖丽高堂。","堂下班马鸣，意气何扬扬。","暮甘复朝旨，为乐良未央。","嗟彼时役牵，关途迟翱翔。"]},{"t":"别熊子三章 其三","f":"五言古诗","c":["翱翔适岭海，路衢悠以长。","车前建隼旟，车后拥干将。","击兽须击虎，刈萧无及芳。","丈夫志万里，遐远安足伤。","颙颙霄汉姿，皎皎冰蘖肠。","勖哉保终誉，慰我亲故望。"]},{"t":"别汤子五章 其一","f":"五言律诗","c":["关途郁迢远，卉草青已发。","骢马何駉駉，向风呜不歇。","广隰流春霏，层岑翳圆月。","迟回去不忍，引领望京阙。"]},{"t":"别汤子五章 其二","f":"五言律诗","c":["京阙邈难睹，萋萋苍树林。","沈沈天宇夕，霭霭浮云阴。","丈夫万里志，烈士千古心。","凤鸟久不鸣，谁哉继其音。"]},{"t":"别汤子五章 其三","f":"五言律诗","c":["弹子匣中琴，写我心曲悲。","我悲良自谙，子琴知者谁。","不惜去日早，但恨来日迟。","何当假羽翼，送子川之湄。"]},{"t":"别汤子五章 其四","f":"五言律诗","c":["驱车井陉谷，扬旆汾水流。","翱翔览四极，迢遰陟崇丘。","遐陬历岩巘，幽访浃原畴。","勖哉利尔涉，风湍寡行舟。"]},{"t":"别汤子五章 其五","f":"五言律诗","c":["乔木多劲柯，直流无反波。","哲人秉孤操，孰云光可和。","嗟彼黄雀吟，感此卿云歌。","悠悠向原隰，惋惋将如何。"]},{"t":"吴将军巡关图","f":"五言古诗","c":["戎马岁南牧，汉军劳北防。","军情异主将，冷煖须共尝。","朝出潮河川，暮过古北口。","边烽传羽箭，朔气严刁斗。","月下黑山晴，分明见列营。","霜欺征袖薄，石报猎蹄鸣。","三军晏然睡，我亦倚吾枕。","天子不可惊，长怀亚夫寝。"]},{"t":"清白传家卷为刘安之题","f":"五言古诗","c":["清如渭川水，白如太白山。","邈尔清白人，遥在山水间。","至清不可淆，至白不可涅。","传子复传孙，一心如一辙。","山同今古色，水同今古流。","清白苟不变，山水同悠悠。"]},{"t":"题白岩画松图","f":"五言律诗","c":["古松何童童，独立难可群。","岁暮倚冰壑，偃蹇凌苍云。","脩标有远荫，直干无曲文。","匠氏苟不遗，宁避斧与斤。"]},{"t":"题杨氏所藏画","f":"五言律诗","c":["翩翩水禽飞，灼灼水花乱。","柔艳杂幽声，纷纷满芳甸。","悠悠画中意，泼泼天机新。","彷佛曾游处，江南二月春。"]},{"t":"题画","f":"五言律诗","c":["空江夕烟敛，日色沙上明。","轻涟漾兰楫，袅袅秋风生。","白云满层阿，林光带高城。","姬文去已远，讵辨垂纶情。"]},{"t":"题放鹤图集陶句","f":"五言古诗","c":["野外罕人事，灵府长独閒。","登陟千里馀，晨夕看山川。","山川一何旷，亭亭月将圆。","云鹤有奇翼，一盼周九天。","但使愿无违，甘以辞华轩。","念之动中怀，放意乐馀年。","吁嗟身后名，百世谁当传。"]},{"t":"答顾华玉见怀之作","f":"五言古诗","c":["离肠如车轮，万转不计程。","咫尺阻言宴，何殊在山城。","閒曹事稽纂，文墨纷相萦。","不见马上人，空闻马蹄声。","揽衣步幽闼，脉脉牵遥情。","屋上春鸠啼，树杪浮云行。","坐惜韶景暮，江皋芳杜生。"]},{"t":"赠徐子","f":"五言古诗","c":["丹枣何累累，朝日耀其光。","上有同林鸟，飞飞鸣且翔。","行子远于役，携手登河梁。","旧京渺安之，江永衢路长。","戚戚里中语，依依川上情。","驾言往相逐，无舟何以航。","乖离去则已，但使心无忘。"]},{"t":"赠友","f":"五言古诗","c":["春阳初献岁，芳树日以青。","送远及近郊，何由申我情。","我情方郁纡，君驾不可停。","瞻彼飞鸿翼，联翩共遐征。","奕奕云中河，烂烂川上星。","中愿渺难遂，伫立以屏营。"]},{"t":"醉中呈时大亲丈","f":"五言古诗","c":["忆昔别丈人，倏忽八九春。","往年虽暂逢，契阔无由伸。","寒冬阴气固，微阳照广津。","送送不及远，千里空劳神。","今来芳草时，言作上国宾。","青袍耀垂杨，移家住京尘。","吾亲适试吏，相过无昏晨。","见母复见姑，此乐难具陈。","佳辰展良宴，味寡情则真。","相顾各踌躇，何以序情亲。","醉别勿草草，挥手天涯人。"]},{"t":"逆旅中会同年杜子廷献因怀其弟廷陈省元凄然增感","f":"五言古诗","c":["月缺还复盈，木枯还复荣。","如何泉下客，一死无重生。","芳筵列时彦，栖栖见遗兄。","昔同宾荐来，双璧价连城。","今为失侣雁，徘徊哀且鸣。","存亡一兴感，四座尽沾缨。","孤坟背山郭，宿草萋以萦。","死者亦何知，绻兹骨肉情。","长歌欲相慰，弥使心怦怦。"]},{"t":"维洛美刘子也刘子仕洛为大夫作室以奉母君子名之曰荣养风人美之故作是诗焉 其一","f":"五言古诗","c":["维洛有崇堂，宛与伊阙京。","层构何崔峨，仰观浮太清。","青云结悬牗，丹霞丽飞甍。","鸡鸣事甘旨，爰以隆孝情。","定省日在兹，致美良匪盈。","嗟嗟宦游子，百世以为荣。"]},{"t":"维洛美刘子也刘子仕洛为大夫作室以奉母君子名之曰荣养风人美之故作是诗焉 其二","f":"五言古诗","c":["荣名本天爵，匪直耀圭组。","之子仕京洛，膏泽被遐土。","膏泽被遐土，皇鉴亦孔昭。","烜烜循吏称，洋洋流汉朝。","寔维慰母心，居处良逍遥。"]},{"t":"维洛美刘子也刘子仕洛为大夫作室以奉母君子名之曰荣养风人美之故作是诗焉 其三","f":"五言古诗","c":["逍遥复容与，降陟在斯堂。","萱草杂杜衡，罗生前后厢。","循基抚婴孺，登俎挹华觞。","俯睇洛川流，顾瞻嵩与邙。","优哉乐相乐，千春寿未央。"]},{"t":"奉赠少司徒华容王公致仕","f":"五言古诗","c":["大谷霁长霖，回云媚山泽。","流潦岂不广，孰云泥吾轭。","朝谢司农卿，夕为岳阳客。","皇眷良在兹，行止各有适。","有适非盘敖，眷言反初役。","解彼府中绶，归我湖上宅。","葺宇依清涟，跻山憩玄石。","幽栖谢生虑，静便终日夕。","矫矫云际鸿，谁能制其翮。"]},{"t":"赠阎允中","f":"五言古诗","c":["郊月隐寒树，喔喔霜鸡鸣。","翩翩随阳鸟，悠悠惮遐征。","客车履晨发，迤逦踰层城。","清川带长薄，绿芜萋以荣。","江路东南驰，行子慕脩程。","金陵帝王宅，佳丽夙遗名。","吴观霭岧峣，晋丘亦峥嵘。","凭轩一回眺，千载有馀情。"]},{"t":"伯川子仕为地官大夫能其官且有显陟矣一旦思其母夫人解印绶去予知其必有以也取六义之比赋有兔诗二章以美之 其一","f":"五言律诗","c":["有兔何爰爰，宅我中谷阿。","中谷一何邃，山石郁嵯峨。","脩篁荫清风，秋鞠扬其华。","于偃复于息，为乐将如何。"]},{"t":"伯川子仕为地官大夫能其官且有显陟矣一旦思其母夫人解印绶去予知其必有以也取六义之比赋有兔诗二章以美之 其二","f":"五言律诗","c":["月明流夕光，零露白湛湛。","饥食野田草，困息山石阴。","物性有固然，卫生良已深。","不见虞人罝，肃肃施中林。"]},{"t":"答石峰见怀之作二首 其一","f":"五言古诗","c":["斗柄当西南，河汉东北倾。","零零露华白，晶晶天宇晴。","微风度广阴，熠耀时复明。","卉木日已黄，秋气日已清。","念子理素瑟，苦调多离声。","嗷嗷失侣雁，汎汎随波萍。","会合固有期，此际难为情。"]},{"t":"答石峰见怀之作二首 其二","f":"五言古诗","c":["露井梧桐凋，杳杳秋夜凉。","眷言怀美人，展转何能当。","纤月挂西牗，微明照我床。","皎皎琼树姿，寤寐如在傍。","近离已不堪，况乃途路长。","谁其絷子马，慰我心彷徨。"]},{"t":"寄弟赋 其一","f":"五言律诗","c":["忆尔别我时，日照河边柳。","痛哭别我去，上马犹回首。","知尔爱我心，不殊足与手。","徘徊望行尘，伫立沙上久。"]},{"t":"寄弟赋 其二","f":"五言律诗","c":["弱弟复多病，相思伤我神。","尔须为孝子，吾已愧忠臣。","膝下三春梦，湖南万里身。","晨昏甘旨暇，休对说烽尘。"]},{"t":"戏简王临安同年","f":"五言古诗","c":["候子虎溪渡，送子龙陂桥。","出城不相见，征盖倏已遥。","百金买江鱼，千金买春酒。","期子会宜城，飘忽过潼口。","追子汉江曲，望子岘山头。","子有室家好，岂知途路愁。","暮投城外寺，急雨响高屋。","安得与子同，长歌对银烛。","子程勿早发，吾驾亦早留。","风尘莽南北，一别动经秋。"]},{"t":"右揆邹公由齐入闽齐人有华泉子者与公友抱病不获出饯作诗以遗之三首 其一","f":"五言律诗","c":["懊恼复懊恼，鸡鸣一何早。","病夫掩关卧，游子就长道。","娟娟窗中月，照见窗下草。","室迩人遂遐，离忧坐堪老。"]},{"t":"右揆邹公由齐入闽齐人有华泉子者与公友抱病不获出饯作诗以遗之三首 其二","f":"五言古诗","c":["黄鹂鸣树颠，嘤嘤求友声。","佳人远言迈，牵我幽思情。","思情何绵绵，绵绵复萦萦。","出门望轩盖，道阻不可征。","霭霭山气浮，晶晶川云平。","鸿雁方北飞，谁哉达中诚。"]},{"t":"右揆邹公由齐入闽齐人有华泉子者与公友抱病不获出饯作诗以遗之三首 其三","f":"五言古诗","c":["华辀耀朱旆，宛转凌春山。","朝辞邹鲁乡，暮过梁宋间。","美哉南邦化，梦寐开心颜。","丈夫四方志，车马胡暂閒。","绻绻东人怀，何时复来还。"]},{"t":"荣恩介寿诗为陈矩庵中丞乃翁作四首 其一","f":"五言古诗","c":["中年谢簪组，将以遗世荣。","晚岁沐崇恩，封诰来承明。","金章既煇霍，廌冠亦峥嵘。","升拜天子光，闾里咸震惊。","悠哉显扬志，爰毕游子情。"]},{"t":"荣恩介寿诗为陈矩庵中丞乃翁作四首 其二","f":"五言古诗","c":["白云何飘飘，覆彼白下门。","游子限江郭，登望穷朝昏。","孰云三品崇，能报罔极恩。","休光烛遐土，膏泽被元元。","庶以立脩誉，永播乾与坤。"]},{"t":"荣恩介寿诗为陈矩庵中丞乃翁作四首 其三","f":"五言古诗","c":["乾坤荡无极，客子日行迈。","永怀将父吟，陟岵发潜嘅。","閒登楚丘望，长川皓如带。","高榭鸣凉蝉，秋风起江介。","烟中树如荠，隐隐见吴会。"]},{"t":"荣恩介寿诗为陈矩庵中丞乃翁作四首 其四","f":"五言古诗","c":["吴会有高楼，上切星与斗。","北牗临玄湖，南窗对钟阜。","楼上一老翁，皤皤垂白首。","服食皆烟霞，图书是宾友。","虽为中丞父，何异商山叟。","谁歌难老篇，愿以祝眉寿。"]},{"t":"贞寿诗","f":"五言古诗","c":["水上双鸳鸯，一失无再偶。","良人弃妾去，白发闺中守。","竹老有古节，松老无柔枝。","峨峨青山石，万古色不移。","谁为贞寿歌，请君歌此词。"]},{"t":"赋鹤翎扇寿江翁","f":"五言古诗","c":["白羽白且鲜，制如秋月圆。","青云相与媚，皓雪避其妍。","出入仙翁手，逍遥以蹁跹。","招彼蓬山侣，乘风下芝田。","万寿同所归，飞飞凌紫烟。"]},{"t":"刘克柔迎养二亲乞诗为寿以人生七十古来稀七字为韵","f":"五言古诗","c":["人生有良愿，莫如翁姥健。","生儿无令名，虽寿安足荣。","七岁燕山道，重来见秋草。","十月到官衙，蟹肥霜菊华。","古称远游苦，今知远游乐。","来去何翩翩，云中度双鹤。","稀年具庆稀，勿轻莱子衣。"]},{"t":"西台遗恨为吴克学御史作","f":"五言古诗","c":["晏眺当沈晖，南山正巍巍。","孤子天涯心，邈与哀雁飞。","雁飞各有止，孤子心无依。","念彼堂上亲，乔年邻古稀。","经时客梁宋，苦恨温凊违。","何知变故来，绣服更麻衣。","整驾返初辙，洒泪临江圻。","人去秋堂空，凄风吹穗帏。","嗟嗟宦游苦，不似前时归。"]},{"t":"稽勋冯子佩归治祖墓","f":"五言古诗","c":["油油上谷路，飒飒秋风起。","落日客子归，寒烟满墟里。","墟里夕灯明，临堂哀泪横。","无复报刘日，空陈李密情。","携儿负畚锸，自辟山中土。","坎坎彻下泉，双棺闭幽户。","幽户不重开，向山高筑台。","他时华表上，应见鹤飞来。"]},{"t":"城东尼寺哭妹三首 其一","f":"五言律诗","c":["佛居峻且玄，中有嘉树林。","惊飙陨其芳，柔叶垂广阴。","青阳讵能几，朱夏奄相临。","一为生死哀，感我涕盈襟。"]},{"t":"城东尼寺哭妹三首 其二","f":"五言古诗","c":["生为同胞亲，死为异域魂。","魂升不知返，亲断有馀恩。","列几陈羞饭，芳醪湛空尊。","阴风吹薄帷，惨惨白日昏。","徘徊复何见，恻怆难具论。"]},{"t":"城东尼寺哭妹三首 其三","f":"五言古诗","c":["平生处闺闼，不识门与逵。","孤魂荡幽邈，广野将畴依。","旧国踰山河，反葬路逶迟。","寥寥禅宇空，亹亹芳序移。","死去长已矣，徒令生者悲。"]},{"t":"次东卿韵挽北村秋官五首 其一","f":"五言律诗","c":["昔我师事公，公以我为友。","长安车马地，相从十年久。","如何永潜翳，冥卧西山亩。","敢谓涕无从，离离满衣袖。"]},{"t":"次东卿韵挽北村秋官五首 其二","f":"五言古诗","c":["喔喔鸡乱啼，皎皎月在墙。","立马古城下，长歌尽馀觞。","咄嗟霄汉姿，今返冥漠乡。"]},{"t":"次东卿韵挽北村秋官五首 其三","f":"五言律诗","c":["公昔较我艺，弱冠举于乡。","公子复青年，探花冠群芳。","浩荡云中衢，接羽相翱翔。","思公不可见，断绝我中肠。"]},{"t":"次东卿韵挽北村秋官五首 其四","f":"五言律诗","c":["我才疏以拙，应答多后时。","长怀陇头吟，负公十景诗。","公今卧泉壤，陇树生新枝。","何意述德篇，翻为断肠词。"]},{"t":"次东卿韵挽北村秋官五首 其五","f":"五言律诗","c":["昔公谢病居，坐卧释子床。","药物虽见亲，书帙犹在傍。","中宵激昂志，江汉相与长。","哀哀七尺坟，漠漠春芜荒。"]},{"t":"经西湖","f":"五言古诗","c":["皇围寂脩夜，驰路直且长。","玄湖贯其北，流水何汤汤。","孟冬寒气交，原野下微霜。","众芳各以萎，鸿雁哀南翔。","俯视清川波，仰看明月光。","凉风吹我衣，俛首思故乡。","故乡不可返，揽辔止彷徨。"]},{"t":"天寿山行","f":"五言古诗","c":["石门凌旦启，驰路直且长。","青山白云合，四顾郁茫茫。","蘋藻秀空涧，黍稷亦登场。","哲王敦孝理，陵邑事秋尝。","予本草野士，谬职参奉常。","敢云俎豆娴，亦已阅星霜。","萦回度墟曲，宛转历岩冈。","蒸岚侵我肌，零露沾衣裳。","沾裳讵足惜，鸿私难可忘。"]},{"t":"入罐石口四首 其一","f":"五言古诗","c":["濯足秋涧水，水寒清见沙。","凌兢不可渡，碎石如狼牙。","童子欣暮晴，笑指东峰霞。"]},{"t":"入罐石口四首 其二","f":"五言古诗","c":["穿林复渡河，佳兴未能尽。","每当路穷处，更著祠官引。","山女何处来，石上洗秋菌。"]},{"t":"入罐石口四首 其三","f":"五言古诗","c":["西登罐石口，鸟道不盈尺。","连山树如绣，云中日将夕。","不闻樵采音，但见虎行迹。"]},{"t":"入罐石口四首 其四","f":"五言古诗","c":["睥睨接崇岭，白处生浮岚。","上有百尺厓，下有千尺潭。","尔非豢龙子，那敢穷幽探。"]},{"t":"庭皋","f":"五言律诗","c":["清露下庭皋，兰缸照虚牗。","幽人已复醉，更酌尊中酒。","登登高城柝，深巷鸣鸡狗。","夜久不成眠，倚阑看北斗。"]},{"t":"西轩诗为襄垣府将军作","f":"五言古诗","c":["朝光丽朱邸，夕雨明绿芳。","阳休一何嘉，顾眺临西堂。","西堂郁以邃，杳杳尘务绝。","右图复左史，回翔尽髦哲。","宛转膝上琴，窈窕邺中吟。","吟以咏我怀，琴以宣我心。","淮南建黄屋，梁王辟东苑。","侈纵匪不娱，终以冒皇宪。","皇宪不可冒，侈纵不可延。","美矣王孙德，永兹黄发年。"]},{"t":"分韵得岳字送邢侍御出按秦中","f":"七言古诗","c":["函谷关头鸡喔喔，骢马凌秋向西岳。","岳前石子何荦确，绣衣侍者斧在握。","冠上神羊峨一角，西抵龙荒北幽朔。","百二河山眼中邈，渭水清清泾水浊，须君激扬无惮数。"]},{"t":"赠陆文质归云间","f":"七言古诗","c":["桥西落日桥东虹，碧烟黯黯秋正中。","九峰仙客泛槎去，鹤氅虬髯吹晚风。","槎头乞药人如市，共说神方能起死。","海上传来语不虚，青蛇本是龙宫子。","月光星影动银湾，河鼓天孙指顾间。","长安亦有君平肆，莫避云涛隔岁还。"]},{"t":"题程时昭所藏画鹤图","f":"古风","c":["程侯手持双鹤图，索我为作双鹤篇。","高堂展玩羽翮动，碧落青丘如眼前。","丹青尔何人，天机入幽渺。","断霞殷殷江日晓，双鹤如人立松杪。","跂者自跂鸣者鸣，华亭辽邈缑山杳。","宛转如思珠树林，苍茫谁识九皋心。","吴王郭里秋尘满，汉帝坛前春草深。","西山玉台不可见，东溟金灶已难寻。","吾想丹青人，前身恐兹物。","华表归来气纡郁，五里徘徊月中宿，不然形神安彷佛。","程侯程侯霄汉姿，三春作郡楚江湄。","休令怨唳分行去，化履升云会有时。"]},{"t":"赠张氏汝吉汝诚兄弟","f":"古风","c":["鲁川何迢迢，太行亦苍苍。","行人跃马出门去，何异飞鹤东西翔。","爱君此行饮君酒，君家弟兄古未有。","夕郎清迥雕鹗姿，秋曹盘礴雷霆手。","朝论同归揽辔年，家声况是埋轮后。","青春衣绣下中台，山东山西花欲开。","休嗟羽翼经年别，早喜阳和及草莱。"]},{"t":"送欹湖赴湖南提学","f":"古风","c":["征旗带落日，出门君已遥。","层城不隔梦，夜度卢沟桥。","卢沟桥边山簇簇，故人却在城南宿。","谁令相见转多情，翻恨迟行不如速。","江汉风烟迟早春，关山雨雪暗边尘。","临岐莫动殊方感，予亦东西南北人。"]},{"t":"游三岩洞","f":"七言古诗","c":["括苍山丛纷阻脩，我来处处归冥搜。","南明双屐始著地，探奇又作三岩游。","三岩三洞神仙府，重门窈窕烟霞古。","山鬼终天护秘文，巨灵何代烦神斧。","鸾骖鹤驾不可寻，飞萝悬茑自阴阴。","挥杯独酌岩中水，一片清冰澄我心。","丹丘碧海寻常是，叹息终年在城市。","便拟稽生著绝交，长向山中访松子。"]},{"t":"送董生归四明","f":"七言古诗","c":["昔年见子黄浦上，叉手向人持礼让。","石麟天马惊殊相，今年见子披云楼。","珠树凌空剑倚秋，乘槎归作广寒游。","杏花香里樱桃宴，草色罗袍碧于淀，明年此地重相见。"]},{"t":"送秦用中文学","f":"七言古诗","c":["玉真台下三间屋，屋后有松前有竹。","广文先生双鬓秃，长对青藜夜深读。","有时不巾亦不服，独跨瘦驴携短仆。","五老峰前看秋瀑，有时芒鞋步江澳。","月落诗成江鬼哭，石底流泉手亲掬。","归来煮茗窗下宿，清梦蘧蘧谢粱肉。","鸟声堕枕猿挂木，红日三竿睡初熟。","食罢晓盘歌苜蓿，为剪溪云封尺牍，长安故人劳远目。"]},{"t":"送钱士宏监税杭州","f":"七言古诗","c":["城头旭光翻早鸦，水部使者驱行车。","行车悠悠向何处，未到行曹先到家。","行曹去家馀百里，槜李西来岸如砥。","吴岫云连越岫云，西湖水接东湖水。","鄂王庙前春草青，苏公堤上花冥冥。","炎州逐客应相别，想见鸰原万里情。"]},{"t":"孺子宅送程南昌","f":"古风","c":["豫章城南高士眠，豫章太守榻常悬。","汉廷使者召不起，土室蓬门江水边。","江水悠悠朝市改，故国荒凉宅安在。","墟里遥看变夕烟，墓田谁为羞春?。","使君五马双朱轮，露冕乘春意气新。","下车先问南州客，恐有当时下榻人。"]},{"t":"醉中赠王少尹","f":"七言古诗","c":["阳城少尹才且贤，佐邑三载名流传。","相逢尽道是青天，恶少豪徒不敢前。","松庭人静春草芊，邑中老幼高枕眠。","政成奏绩来日边，声光赫赫谁能先。","冢宰见之呼少连，大书上考朝廷宣。","长安雪梅开早年，手捧尺檄别我还。","城馆寒灯开夕筵，银河挂窗山月偏。","欲醉不醉心茫然，天明一笑上马去，他日重逢赤黻悬。"]},{"t":"寿许太宰","f":"七言古诗","c":["明公昔乘御史骢，问俗直过东山东。","海底鲸鲵失巢窟，草间狐兔无留踪。","明公今曳尚书履，手握星枢正天纪。","诏草亲劳主上裁，蒲轮特为苍生起。","白首兼持将相权，中朝五福几人全。","威加朔漠三千里，身系安危四十年。","明明衮职谁能补，籍籍人称仲山甫。","不独芝兰满径庭，尽看桃李填门户。","桃李阴阴寿域开，帝垣西畔接蓬莱。","朝回欲致长生祝，笑对南山歌有台。"]},{"t":"挽听竹山人","f":"七言古诗","c":["江雨夜合凉云秋，江翁骑龙上天游。","玉棺沈沈土门闭，江翁只葬江头地。","江头苦篁风叶老，下有巾车往来道。","相逢啼杀感恩人，泪湿斑花愁不扫。","斑花自湿人自哀，江翁一去何时来。","烟波冥冥渺千里，空托招魂赋湘水。"]},{"t":"吴将军辕门夜宴图","f":"七言律诗","c":["营门花发春酒香，浓点驼酥炙黄羊。","美人娇歌健儿舞，蜡凤啼风月当午。","高帘飞幕丝吹腾，觞波栉栉梁云凝。","主人醉眠客不醒，探兵枕戈戍烟静。"]},{"t":"山有云赠閒翁也閒翁家于婺水之上既寿且康其子佥宪君宦游山东以不得恒侍左右为恨客有为之作望云图者野史氏闻而感焉乃援琴而歌曰","f":"楚辞体","c":["山有云，皓其光兮。","以飞以扬兮。","覆我翁之堂兮。","我堂兮日关。","我翁兮在山。","云朝出游兮暮来还。","视我翁兮寔居其间。","嗟嗟山之巍兮云则永栖。","我翁之乐兮千祀其无涯。"]},{"t":"薛封君挽歌三章 其一","f":"楚辞体","c":["泬寥兮江门，公之逝兮鹿豕群奔。","公今何居兮泉扃郁幽，谁与公兮遨游。"]},{"t":"薛封君挽歌三章 其二","f":"楚辞体","c":["泉扃何有兮厚土绵绵，上跱松柏兮下奠泗渊。","公宵处兮昼尔瞑，洞神理兮暧千年。"]},{"t":"薛封君挽歌三章 其三","f":"楚辞体","c":["弦诵兮初尝，公渐兮四乡。","绿桂兮青峤，有严兮公庙。","盍来兮，慰我人怀兮。"]},{"t":"贾太史母太安人挽辞","f":"楚辞体","c":["中寝阒寂兮夕风以雨，灵薄阴沈兮莓生于庑。","棘人返兮恋恋，杳慈颜兮莫予睹。","历庭宇以周望，循园庐而抚膺。","揽堂背之故谖，缤杂遝兮落英。","撷芳荃以为旨，奠桂椒以为浆。","灵偃蹇其至止，怛进拜兮彷徨。","杉舆兮柏輀，文骊兮素旂。","启殡宫兮山之阿，送母氏兮永归。","重曰：茫茫厚土，閟虞渊兮。","白曜回光，烛幽玄兮。","陟彼峻屺，睇流云兮。","神理超遥，眇氤氲兮。","嗟予寡翼，安彼溯兮。","穷祀剪剪，悄终慕兮。"]},{"t":"野泉词为郡守高子洲作","f":"楚辞体","c":["野之水兮悠悠，子不乐兮远游。","子远游兮要津，怅予独兮水之滨。","水滨兮踯躅，泉瀰瀰兮波绿。","愿从子兮九重，化霖雨兮随飞龙。","龙飞兮在天，膏下土兮吾泉。","与子归兮泉之野，以逍遥兮冬夏。"]},{"t":"君马黄赠祝仁甫","f":"古风","c":["君马黄，我马苍，两马相逐君马良。","君马来自函关道，我马空山食秋草。","忆昔两马初学行，长安见者神色惊。","鲁坰骊黄未足论，卫丘騋牝虚驰名。","岂料长成人少顾，十年不踏天闲路。","逸群翻惹太仆嫌，腾枥正中奚官怒。","以兹流落在风尘，南走荆梁西入秦。","自伤万里汗流血，谁道五花云满身。","弃置不须怜我马，君马亦在盐车下。","疾足由来控者难，骄嘶自合知音寡。","吁嗟君马天下无，且向沙场暂秣刍。","北来司马今伯乐，肯使君王空按图。"]},{"t":"杜蒉","f":"古风","c":["旷饮调饮，臣蒉亦饮。","酒生微波，天风凛凛。","子卯不乐，君臣始终。","爵亡言存，千古无穷。"]},{"t":"纪叔姬","f":"古风","c":["国亡君亡，吾将何归。","父母邦鲁，先君垄酅。","归不于鲁，而酅是依。","乌乎贤哉，其纪叔姬乎。"]},{"t":"石祁子","f":"古风","c":["冠佩则兆，吾弗敢知。","吾所知者，吉凶异仪。","或兆或否，偶邪非偶。","大哉礼云，臣子常守。"]},{"t":"四友亭诗有序 其一","f":"楚辞体","c":["伯氏曰：我所友兮在徂徕。","直干矫矫排风雷，千秋万岁倚崔嵬。","美人赠我云锦青，何以报之松下苓。","朝餐暮饵通仙灵，驾青牛兮凌紫庭。"]},{"t":"四友亭诗有序 其二","f":"楚辞体","c":["仲氏曰：我所友兮在淇澳。","苦节娟娟乐幽独，千秋万岁无剪扑。","美人赠我绿锦裾，何以报之竹上茹。","朝餐暮饵劲且癯，驾青鸾兮凌紫虚。"]},{"t":"四友亭诗有序 其三","f":"楚辞体","c":["叔氏曰：我所友兮在孤山。","繁英灿灿开冰颜，千秋万岁倚清寒。","美人赠我素锦緺，何以报之梅白华。","朝餐暮饵神精和，驾青禽兮凌紫霞。"]},{"t":"四友亭诗有序 其四","f":"楚辞体","c":["季氏曰：我所友兮在新甫。","铜柯蹇蹇霜皮古，千秋万岁辞斤斧。","美人赠我翠锦裙，何以报之柏子仁。","朝餐暮饵容色新，驾青虬兮凌紫云。"]},{"t":"迎神","f":"楚辞体","c":["陟巉岩兮望九嶷，玄云□兮灵御驰。","裸二女兮骖文螭，飞蕙盖兮搴翠旂。","沅湘兮无波，涔阳兮际霞。","风伯兮前导，欃枪兮后罗。","山有木兮木有松，怀重华兮心忡忡。","椒酒兮鼍鼓，逢神之降兮风沨沨，将愉享兮君山之宫。"]},{"t":"送神","f":"楚辞体","c":["重华兮降歆，湘君兮并临。","来联翩兮共御，归容与兮同心。","假灵保兮陈辞，鼓南风兮瑶音。","苍梧眺兮极浦，洞庭波兮风雨。","蛟龙蜿兮昼吟，鸾鹄下兮群舞。","睇灵光兮不见，切予心兮愁苦。","垂巍巍兮馀泽，为霖雨兮下土。","瞻有严兮遗像，愿嗣续兮终古。"]},{"t":"唐夫人操为都玄敬祖母作","f":"楚辞体","c":["白杨翻翻兮翳于墓门，誓良人之不从兮孤曷与存。","瞻彼中林兮豺虎纵横，我室我安兮我孤我将。","嗟嗟孤有成兮，我目则瞑兮。"]},{"t":"门有车马客为顾侍御乃翁赋","f":"五言古诗","c":["门有车马客，云来自吴下。","相逢问丈人，草服在中野。","中野何所有，有园亦有畴。","青槐荫君堂，文杏为君楼。","楼上置书史，下系双桂舟。","园中古松树，甘露降油油。","居人被其惠，行者藉其庥。","阿儿冠豸冠，阿弟登龙头。","出入乡党间，光尘满道周。","昆山岌嵯峨，湖水绕下流。","丈人乐相乐，延年方未休。"]},{"t":"都义士","f":"古风","c":["母存儿亦存，敢以身许人。","母死儿可死，儿志良以伸。","我宇舅葺，我桑舅植，我室我家维舅力。","我生有儿舅无子，舅有急难我当死。","吁嗟乎，国士之义义与秋云高，聂政荆轲俱尔曹。"]},{"t":"李将军","f":"古风","c":["李将军，七尺身，丈八矛，生来骨相当封侯。","锦袍白马如流电，一岁长安一相见。","不扫边尘向朔庭，空随汉月归乡县。","李将军，雄且英，山东塞北咸知名。","嗣忠堂前世泽远，且读父书调母羹。","君不见长杨羽骑如云集，天子勤边方好兵。"]},{"t":"周司徒","f":"古风","c":["周司徒，真丈夫，直气棱棱霄汉俱。","致君不作尧舜主，拂衣归卧山中庐。","山中卧，今几载，鹤貌童童履声在。","十书五疏招不回，九重虚席空相待。","北来颉利西羌胡，争问司徒今有无。","乃知系国轻重者，不独庙堂公与孤。","周司徒，真丈夫。"]},{"t":"芝山操","f":"楚辞体","c":["山之芝兮紫英，遐不见兮我怦怦。","逝将归兮以撷以烹，曰以芼予亲之羹。","遹脩眉兮四翁，日游戏兮山之中。","朝予望之兮夕梦其下，盍反辔兮吾马。","子之辔兮言反，顾周道兮云远。","氓之靡家兮皇不有储，嗟嗟子兮曷宁其居。"]},{"t":"双清操","f":"楚辞体","c":["台有柏，阴阴兮，皇鉴在上昭临兮。","柏之阳，维我之堂。","我激我扬，曷我人弗臧。","雪斯川矣，月斯渊矣。","匪渊匪川，维我游之天矣。"]},{"t":"次杜工部秋雨叹韵柬希尹 其一","f":"七言律诗","c":["睡起山厨湿烟白，堆盘忽见红蟹鲜。","狂夫对此兴不浅，恰值床头无酒钱。","檐雨霏霏暮声急，蓬头独倚阑干立。","美人可望不可攀，閒诵枯鱼过河泣。"]},{"t":"次杜工部秋雨叹韵柬希尹 其二","f":"七言律诗","c":["径荃篱菊寒缤纷，半紫半黄花似云。","若令此物混桃李，虽有贞固何由分。","华阳老人头半黑，坐对幽芳三叹息。","屈平元亮今不逢，莫向西风论价值。"]},{"t":"次杜工部秋雨叹韵柬希尹 其三","f":"七言律诗","c":["吁嗟屋漏不可数，四壁颓墙少完堵。","自缘物候近重阳，怪底满城终日雨。","城南山寺风且寒，欲往只愁行路难。","伏枕高歌夜不寐，床头酒壶旬日乾。"]},{"t":"桐江水为王推官赠别","f":"古风","c":["桐江水，深几许。","司刑来，使旌举。","夹岸垂青杨，豺狼化田鼠。","洞江水不可泳以游。","司刑击兰楫，骇浪成安流。","司刑匣中三尺铁，隐隐星光淬鸡血。","鼠移巢窟，龙失其波，桐江桐江奈乐何。"]},{"t":"车遥遥送钱伯川监税河西","f":"五言古诗","c":["一车两雕轮，宛转行不已。","悠悠河西路，去去百馀里。","孟冬北风冽，河水寒不流。","朝发城东门，暮至河水头。","谁言近别易，近别心更苦。","咫尺不相看，天涯在庭户。","君行西河上，几日河柳春。","攀条采柔芳，愿寄同心人。"]},{"t":"洛阳道送刘少府","f":"五言古诗","c":["沃野萋柔桑，翩翩春鸟翔。","使车天上来，白屋回青阳。","青阳为雨露，不为冰与霜。","冰霜易流铄，雨露恩乃长。","谁能泥朱幰，永庇嵩洛堂。"]},{"t":"车遥遥为前人赋","f":"古风","c":["车遥遥，风起沙蓬卷。","离肠逐双轮，轮转肠亦转。","双轮转转临大河，雪花如席冰嵯峨。","孟津渡头灯火乱，洛阳城边冠盖多。","车遥遥，载君行，载君返。","赤凤衔书下紫云，回期莫待春华晚。"]},{"t":"赋得万里桥送客","f":"七言古诗","c":["万里桥边树如荠，蜀使入吴真万里。","临岐记取丞相语，万里之行此其始。","英雄一往人代易，锦水汤汤镇如昔。","遗阵空思云鸟形，脩梁已荒车马迹。","旬宣使者家在吴，入蜀今为蜀大夫。","登桥揽辔一回首，慷慨能轻万里途。"]},{"t":"运夫谣送方文玉督运","f":"古风","c":["运船户，来何暮。","江上旱风多，春涛不可渡。","运船户，来何暮。","里河有闸外有滩，断篙折缆愁转船。","夜防虫鼠日防漏，粮册分明算升斗。","官家但恨仓廪贫，不知淮南人食人。","官家但知征戍苦，力尽谁怜运船户。","运船户，尔勿哀，司农使者天边来。"]},{"t":"济宁刘使君提刑晋阳过新乡之墟其友人华泉子者适游苏门伤其别而不得见也于是赋车遥遥以招之","f":"古风","c":["车遥遥，向何许。","去君咫尺地，不得一相语。","忆昨与君游大梁，暑云拂盖流尘黄。","回头转睐复几日，草木零落飞严霜。","山中独行岁华晚，烟留月绻谁能返。","逸客长怀阮嗣宗，仙翁却吊罗公远。","闻君五月登啸台，何郎许子相徘徊。","酒酣清歌眺白日，万里䬃䬃长风来。","人生得此亦自乐，何用苦教缨冕缚。","不见昔时贤达人，强半遗迹在丘壑。","车遥遥，将奈何，太行积雪寒嵯峨。","赠君七尺紫藤杖，并履閒寻安乐窝。"]},{"t":"临高台为谢内史题观日图时内史将省母归馀姚","f":"楚辞体","c":["临高台，望三山，曜灵出海光以斓。","浴咸池，登扶桑。","羲和总绥，六龙服箱。","回精白云舍，流采黄金堂。","金堂客子及秋返，云舍萱花凌雪芳。","临高台，心不及。","朝怀亲兮夕怀国，却到江南望江北。"]},{"t":"题画","f":"楚辞体","c":["散发兮江阿，曳青筇兮裳薜萝。","风飗飗兮鸣琴，倚文石兮藉莎。","石畔兮何有，有蒲兮与荷。","悦芳兮流目，矢心兮靡佗。","匪人群兮言绝，慨新声兮孔多。"]},{"t":"题王庭简像","f":"古风","c":["玄其衣，纁其裳，琼琚玉玖鸣锵锵。","端而容，肃而止，仪冠峨峨若山峙。","主群祀，礼百神，精明之德通天人。","上郡城边无吠狗，骏马旃裘望风走。","李广汾阳是其偶，吁嗟若人古良守。"]},{"t":"题金谷园图赋得绿珠怨","f":"古风","c":["谁言妾命薄，结发承主恩。","谁谓妾身轻，宠冠金谷园。","园中桃李千万树，对妾妍华避无处。","徘徊歌舞曲未终，门外战鼓声逢逢。","当时只倚红颜贵，岂料红颜为主累。","主家高楼天与齐，妾身不惜委黄泥。","他生愿作衔泥燕，长傍楼中梁栋栖。"]},{"t":"筑桥怨","f":"古风","c":["桥之筑，人痛哭。","桥之崩，人不行。","不行犹自可，痛哭悲杀我。","虬须环卫蟒服尊，谁其坐者鱼朝恩。","砖厂供砖石窝石，役夫一丁钱七百。","五州十县走登登，前后两年方告毕。","沙河桥，千岁牢。","渴杀道上人，旱杀田中苗。","愿天不雨水勿高，马蹄踏踏桥土裂，中有役夫膏与血。"]},{"t":"断弦引","f":"五言古诗","c":["离琴挂幽壁，玉轸朱丝弦。","美人不复来，华月生秋圆。","临除拭金徽，弦绝轸难续。","昨日白头吟，今朝断肠曲。","轸是美人系，弦是美人调。","人亡琴亦亡，独坐悲长宵。"]},{"t":"题丰内翰爱凫楼","f":"古风","c":["春凫呼其侣，拍拍戏芳渚。","一凫忽惊人，群凫共高举。","回翔集城下，点点散如雨。","爱凫古人今几秋，夕阳江上空高楼。","冯阑独送千里目，平沙莽莽寒烟绿。"]},{"t":"两节妇为毛给事用成作","f":"古风","c":["姑曰妇，嗟尔芳龄始二九，绿发红颜何可守。","妇曰姑，上有姑，下有雏。","姑不舅负，吾宁忍负夫。","妇姑相向中庭立，抱雏爇芗吁天泣。","天乎不剪毛氏宗，臼甘自舂井自汲。","雏生三雏宗日彊，更有小雏如凤凰。","苞羽翩翩被五采，远簪白笔登岩廊。","登岩廊，心独苦，回望滇南两丘土。","君不见贞女墓，上木青青高入云，路人竞指毛家坟。"]},{"t":"庐墓哀为杨名父作","f":"古风","c":["庐墓哀，庐墓哀，墓上有花亲手栽。","春风一番花一开，亲魂去矣何时来。","魂不来，儿不返，空林月落猿声断。","泪花著树花已空，伤心何处吹羌管。"]},{"t":"银台墓为韩通政赋","f":"古风","c":["银台墓，萧关路。","落日春草青，苍山起寒雾。","萧关路，银台墓。","墓前嵯峨石碑古，下有双棺闭泉户。","夫为正议妻淑人，四封三品俱皇恩。","先银青，后金紫，生儿愿得银台子。","银台功业何可知，请向墓前看制辞。"]},{"t":"病妇行为恽功甫悼亡","f":"古风","c":["妾嫁郎，才十五，辛苦为郎立门户。","舅丧未了复姑丧，十载牛衣一环堵。","荐书初下郎有名，寒冬携妾来京城。","可怜弱质犯霜雪，春花一夜成秋零。","左揽儿，右牵女。","泪湿枕花红，凄凄背灯语。","招魂须故衣，埋骨须故乡。","郎恩岂云薄，妾命自不长。","解钱系儿褓，留市梨和枣。","拔钗穿女裳，留作嫁时妆。","儿女勿啼郎勿哭，丧车不反泉台毂。"]},{"t":"嗟克明为段佥事惟勤乃翁作","f":"古风","c":["孰谓弟无子，兄子为后与子同。","孰谓天有知，三子夭以殇，无后翻在躬。","嗟而克明，为子克子兄克兄。","吴人至今传，为吏公且平。","嗟而克明，葬以一命服，祭以五鼎烹。","有子官度支，出典邦国刑，铁冠白笔纡银青。","过家上冢泣，所生以三尺。","孙嗣宗祊，谓天无知，天竟有知，嗟克明。"]},{"t":"归人哀为南海张进士作","f":"古风","c":["归人哀，哀不极，双墓累累五羊侧。","亲颜欲见不可得，梦里相看画中忆。","养儿谓言得儿力，昼锦归来扫荆棘。","百金置酒千金庖，散作空山老鸦食。","归人哀，哀不极。"]},{"t":"接树叹为方举人乃翁作","f":"古风","c":["朝汲水，暮伐土，山人接栗山中圃。","白头翁妪感且伤，那能更待渠实尝。","春风花开秋结果，玉盘跪进黄金颗。","冰鱼冻笋古有之，谁道苍苍不关我。","我圃之树今十围，双亲何在冢累累，山人见之双泪垂。"]},{"t":"傅本学二亲挽歌","f":"古风","c":["夫荷戈，妻辟纑，渡江北来戍京都。","京都主将多锦腴，夕幕朝衙驰复驱。","恨不为君西击胡，四十二载空良图。","大儿官至执金吾，小儿廷评冤狱无。","诸孙亭亭俱丈夫，兴来一饮酒百觚。","长歌激烈声呜呜，源溪冬寒水不枯。","笑将白发归黄垆，翁生有闻翁不孤。"]},{"t":"席上赠子立内兄","f":"古风","c":["碧柳毵毵黄鸟过，城隅早芳媚云波。","登高宛恋乡思多，玉壶倒尽难成酡。","欲留不留将奈何，韶华荏苒空蹉跎。","携手东陌上，烟光忽已夕。","眼前相对不尽欢，别后封书复何益。","君不见凤雏短翮栖高桐，骥子草伏山岳空。","看君不合在岩穴，上苑年年春杏红。","春杏红，点春衣。","明年此日应相见，千里家园亦暂归。"]},{"t":"白岩公坠马次杜韵奉呈","f":"古风","c":["我本使君幕中客，惯趋广庭侍双戟。","雨晴拂晓时一过，齿齿屐痕开藓石。","使君何所作，白羽摇摇藤七尺。","使君何所好，湘缥在床琴在壁。","迩来使君偶坠马，十日不踏长安陌。","芳英落尽春已晚，影倒青林日光射。","君不见少陵老翁亦伤足，犹对骅骝歌喷玉。","又不见汉庭司农不受辱，自比辕驹悲局促。","人生须作壮士豪，安能蚩蚩等胥仆。","城西有山如少室，城南有村如杜曲。","映水岩云锁翠微，隔花山鸟啼苍竹。","君须乘舆我须马，磁罂满载春缸绿。","酒酣拔剑共起舞，诗祟病魔齐就戮。"]},{"t":"赠东山谢万户","f":"古风","c":["万户侯，丈八矛，临川四境俱休休。","万人督，千钟粟，临川四境俱鼓腹。","壮有立，老有归，英巨峰前春草肥。","白头高眠草堂下，前植青松后梧槚。","临安路与临川通，共道将军多祖风。","有侄如玄子如琰，不独东山别号同。"]},{"t":"守郭老先生进阶三品寄贺长句","f":"古风","c":["朝赏冶城花，晚折长干柳。","邂逅相逢太史君，逍遥却忆程番守。","程番老翁垂八龄，头颅半白双瞳青。","看山远步时忘返，中酒高眠日少醒。","昔在先朝岁庚午，投荆自愧分铜虎。","翁寿才交六旬一，我齿恰当三十五。","忘年结好心绸缪，峡月巴猿两见秋。","吊古同寻庾亮宅，怀乡并倚仲宣楼。","那知世事多迁变，倏忽还如零雨散。","金紫翁方拜国恩，衰麻我适遭家难。","家难迍邅涕泪馀，传经重驾法台车。","兰阳夜火黄精饭，汴水春风锦字书。","问翁北归今几载，可念江陵旧僚采。","太史遥从故里过，里中争贺新衔改。","新衔故里树新坊，白日门庭綵绣光。","岳峰苍翠河流曲，暮景优游共短长。"]},{"t":"赋得江上草赠燕泉何子南归","f":"古风","c":["江上草，何青青，使君归来朝戴星。","问君君不言，挽君君不停。","十丈风帆疾于矢，苍梧风深竹花紫。","云中之君呼不来，空馀泪满潇湘水。","潇湘水，清且涟。","江头瞻望不可及，惟见草色呈芊绵。","请君细鼓南薰调，日对虞皇发长啸。"]},{"t":"赋得泰伯祠送龙致仁佥事","f":"古风","c":["万乘尊，如浮云，发乎可断身可文。","弟有雍，孙有札，百代清风见家法。","牲牢腯，黍稷香，帛烟袅，箫吹扬。","使君祭扫庙门掩，阴风飒飒灵旗飐。"]},{"t":"送钱伯川归锡山","f":"古风","c":["晓上黄金台，夕登潭柘山。","白云何油油，下覆雁门关。","爱君此行为君羡，白头阿母今相见。","我身欲飞无两翼，杳杳风尘隔畿甸。","君家堂前二古松，枝柯偃蹇如虬龙。","南窗恰对梅花坞，西牗全当天井峰。","伯川之水旧姓吴，川上山形列画图。","昔称让国今称孝，乃有地曹钱大夫。","大夫今为返哺乌，登堂寿亲亲不孤。","弃官就养人所无，谁言大夫已矣乎，古来廊庙须江湖。"]},{"t":"送周公度下第","f":"古风","c":["征驾严晓装，行行及春阳。","离心旷幽邈，如彼江路长。","江路长，云漠漠。","东楼欢笑一回首，十载高情镇如昨。","先生负奇气，胸次何磊落。","平生自许梁栋材，国门未筑黄金台。","敝裘长剑惨无色，可怜五上空归来。","空归来，勿凄楚。","君不见齐无盐，今日椒房贵，昨日采桑女。","又不见，商傅说，朝辞版筑暮霖雨。","人生穷达会有时，世间俗子安得知。"]},{"t":"送陈嘉言经略赴陜","f":"古风","c":["前年使，长江南，今年使，长城下。","使君自有开济谋，不在舟航即鞍马。","马行万里道，君抱万里心。","二月春草短，云愁沙碛阴。","长城路，通咸秦，古来转饷多名臣。","后有李唐前有汉，君不见萧何与刘晏。"]},{"t":"送沈仁甫归省","f":"古风","c":["瓜洲渡，三江路。","客子将母心，汤汤水东赴。","水东赴，送客江上还。","前年奉觞衣白鹭，今年奉觞衣白鹇。","子阶日以崇，母心日以乐。","乐在平反多，岂论官与爵。","君不见汉家京兆隽不疑，母子声名天下知。"]},{"t":"送少傅刘先生祭扫归钧阳","f":"古风","c":["夕霖清上郊，朝日丽层汉。","倾都车马出，载路行人看。","元宰辞掖庭，翱翔下东观。","东观逶迤复道长，凉风飘转赐衣香。","天曹旧识尚书履，秘阁新加学士章。","秘阁天曹俱要路，一代人才真有数。","御史中丞次第迁，总戎司马从容步。","谔谔危言震百僚，岩岩师表重三朝。","启心不负天王托，破胆犹闻北敌谣。","昼锦归来故乡县，宋台梁馆经行遍。","帑锡从教父老分，上珍独向丘园荐。","三秋霜露石麟寒，四世封章帝泽宽。","休对青山赋招隐，早看黄诏促回鞍。"]},{"t":"送高大参升方伯入闽","f":"古风","c":["昔我分符作荆守，我公坐镇黄河口。","系马殷王庙左槐，开筵卫女堤边柳。","公今参佐临我邦，我亦抱疴眠芸窗。","溪树阴阴白日静，干旌时到木兰艭。","回思十二年相见，岁华倏忽惊流电。","路岐回复馀万程，宇宙阴晴经几变。","忆公安得常见公，古貌依稀魂梦中。","但看邸报知迁转，那记官阶卑与崇。","饯宾杂遝喧徒御，斜月苍凉郭门曙。","独鹤孤琴一盖飘，我公远向闽山去。","人生垂翼岂有恒，大舟浅水固难胜。","扶摇直上自此始，公不见天池六月南飞鹏。"]},{"t":"送杨邃庵督马关西","f":"七言古诗","c":["狼星扫天西戎来，飞勒叩关关夜开。","当关空列貔虎士，伏枥不见麒麟材。","朝战关头暮关下，疮痍大半徒行者。","箭书入报宵旰忧，拊髀翻思大宛马。","中丞主马朝命新，威霆动地惊故人。","长城迢迢亘西北，万里可当公一身。","秦苑草青秦水旨，鲁坰卫丘那足比。","我公息马兼息民，民保田庐马生子。","天燠在野寒在槽，马子日肥民不劳。","三军校阅锦云乱，万蹄蹴踏沙场高。","将军骑出诸羌遁，玉门烽静班超觐。","我愿公归登上台，他日用贤如用骏。"]},{"t":"送赵华镇之东安","f":"七言律诗","c":["赵侯别我何所适，华发远为淮甸客。","镇日相逢只独醒，主人笑君太拘迫。","簿书集案山嵯峨，一入官曹事即多。","驹隙韶光最堪惜，眼看春树叶婆娑。"]},{"t":"赵南渚席上送秦凤山分体得柏梁","f":"七言古诗","c":["我家东海君东吴，一日相逢游上都。","官居并结城南衢，会面不问晨与晡。","登山临水时一呼，白马青衫光照途。","见者谓是游侠徒，岂知义气卑王卢。","中宵坐感头白乌，朝辞阙庭暮江湖。","云泥忽如鸿与凫，夕阳下树秋巘孤。","回风策策鸣脩芦，于嗟离心不可图，何时归来江上舻。"]},{"t":"分题得鹊山湖送维正李宪副之山东","f":"古风","c":["齐门东，沙径平。","云羃羃，湖冥冥。","使君来，麦秋晚。","柳阴阴，画舟远。","瘦蒲疏荇逗遛香，南浦烟光接西堰。","堰北山，灵鸟聚，对面潺湲华不注。","山前绿稼隐茅茨，旧是齐侬钓游处。","横桡越水浒，飞踏青芙蓉。","华阳洞口跨白鹿，醉吹玉笛呼眠龙。","长镵野老逐李邕，锦袍仙人随赤松。","石壁土花秋靡靡，古踪悠悠镇如此。","要留洒翰洗蛙蝉，雨林夜黑啼山鬼。"]},{"t":"送盛医官归吴中","f":"古风","c":["昔我游东吴，访君阊门郭，石井泉边晚开酌。","兴来同上春雨亭，醉里不知江月落。","扁舟一为别，几见薜萝春。","我绾曲台绶，君垂钓台纶。","震泽霜波愁外渺，虎丘云树梦中亲。","四年不得一书札，只问江头来往人。","昨朝觌面凤池曲，鹤骨棱棱犹在目。","料君应恐惊世人，角带乌巾强随俗。","世人久知吴下名，喧传卢扁今再生。","药丸到处衽席起，大门小户争扳迎。","东楼一夜乡心发，忽著荷衣向人别。","憎君归计何太忙，水上风烟触炎热。","玉芝瑶草满山家，住日应多来日赊。","愿留丹诀与知己，晚岁相寻凌紫霞。"]},{"t":"送陈邦瑞侍御巡按山东兼过山西省亲","f":"七言古诗","c":["缺蟾堕崦关树苍，长河白浅波云光。","殿中使者踏晓去，骄马远饯金绣香。","齐山青青晋山紫，两地彩躔看柱史。","王程下放昼游閒，准背刚风蓦千里。","山郊候人如羽立，狞色邮郎报函急。","屈轶枝明海岳寒，神羊影射狐狸泣。","曲台宦子离怨新，四岁簪袍羞后尘。","拜君东行勿草草，张桓已谢滂公老。"]},{"t":"送侯良弼之汤阴","f":"七言古诗","c":["虬须使君乘铁骢，邺南古道行秋风。","居人不解明府号，争看印章垂赭铜。","使君登座衙鼓发，簿吏趋蹡来走谒。","止是阳春一片心，谁教化作琴堂月。","月明照见冰丝影，流水声高闻四境。","却记中条罢讲时，山云夜覆檐花冷。","黄口小儿把刀笔，抹黑批丹誇法律。","岂知汉吏推明经，不在区区三尺刑。"]},{"t":"送同年少宰汪閒斋考绩北上","f":"古风","c":["凤阙开晴霞，龙楼啼曙鸦。","春风上春月，吹满上林花。","上林花色明如绣，亚相考功新入奏。","遥从花外驻公车，更向花间听禁漏。","禁漏丁丁杂佩环，朱衣玉貌动宸颜。","铨司藻鉴悬秋水，宪府威名重泰山。","廊庙雍容需衮职，徵迎不用皇华敕。","元知北斗近三台，早见东人歌九罭。","都下旧游怀丙辰，回头二十九回春。","看花借问当时侣，白发重逢今几人。"]},{"t":"送都宪梅田颜公赴召北上","f":"古风","c":["元精钟海岳，勋业树乾坤。","位极南曹长，阶迁北院尊。","晴云开水寺，旭日映江门。","江门水寺张高宴，旭日晴云丽京甸。","天府争誇藻鉴名，乌台共识冰霜面。","凉风八月桂始花，碧叶飘霜疑散霞。","轼前白鹭能窥隐，冠上神羊惯触邪。","神羊白鹭威千里，川后澄波净如几。","百度风行草野间，群僚色动班行里。","却忆武皇临御初，公居光禄礼台予。","含香近切奎三象，秉笏亲陪第七车。","二十年华速流电，迟暮金陵重相见。","蹇劣甘投林下栖，差池岂分江皋饯。","中兴天子新旧邦，须公开济启明堂。","大臣忧乐先天下，记取希文记岳阳。"]},{"t":"寿屠左丞","f":"古风","c":["异才生间世，声业播乾坤。","权总西台长，官登少傅尊。","青云连甲第，白日映高门。","高门甲第开华宴，白日青云丽芳甸。","缥缈鸾书海上来，蹁跹鹤驭图中见。","凉秋九月天宇空，紫衢合沓飘香风。","黄封锡命来中使，玉带称觞列上公。","上公中使分先后，共指南山祝眉寿。","七十遐龄古已稀，三千贺客今谁有。","南山何物比嶙峋，雪鬓霜髯七尺身。","他日麒麟须画像，此时龙马是精神。","予本东州牧羊子，姓名曾入山公启。","执豆叨瞻末坐光，升歌敢并群仙齿。","明公持法法不私，春阳多在冱阴时。","汉廷赫赫名臣传，异代同伦张释之。"]},{"t":"贞母行为杨晋叔母夫人寿","f":"古风","c":["同牢不踰年，中道相弃捐。","阿母当日心，兰室如黄泉。","儿生不见父，但见山头土。","向母索父啼，母心良独苦。","脱珥易书，剪发为羹。","㷀㷀三十霜，儿也成令名。","成令名，事元后，封章来，贲林薮。","凤冠峨峨翔白首，右佩瑶瑜左琼玖。","天与乔龄报贞母，不然安识少师门今有后。"]},{"t":"光禄丞为赵天挺乃翁寿","f":"古风","c":["光禄丞，白发何毵毵。","壮游江北，老去归江南。","江南水乡地，可住复可常。","钓鱼以为羹，汲泉为酒浆。","晓日张琼筵，有客白其马。","诸孙绕膝傍，游子拜庭下。","光禄丞，福如冈，寿如陵。","墅西十月梅花白，不用登舟唱采菱。"]},{"t":"席上次韵刘镇远希召南雍剑客歌为八十翁阮毅夫赋","f":"楚辞体","c":["虎头突兀鸢肩高，将军将军真古豪。","已有精忠贯白日，更看逸气凌青霄。","少年带剑方城里，朝猎登山夕临水。","结交意气无南北，侠侣游朋来远迩。","出门白马骄如龙，飞黄不受徒御砻。","心轻项羽匹夫勇，身许萧何万世功。","平生好诗有诗癖，时向江边寻古迹。","谁论北海孔文举，未数东山谢安石。","帐底高眠强敌愁，共说将军无与俦。","淮阴壮士富才略，会稽老子多阴谋。","中年华发忽成素，叹息流光近迟暮。","辟谷真成陆地仙，学易上究先天数。","子歌孙舞终日欢，城有堞兮江有澜。","他时汉水襄山道，应见青牛西出关。"]},{"t":"画松歌寿白岩太宰","f":"古风","c":["今辰何辰到岩谷，太宰堂中见乔木。","飒飒重檐风雨来，冥冥四座烟云逐。","初筵宾客俱改容，细辨始知为画松。","霜柯雪干槎牙起，碧茑青萝宛转封。","星除夜静飞霹雳，彷佛蛟龙在东壁。","培植深疑造化偏，推移颇讶神功疾。","天生钜材非偶然，上摩霄云下重渊。","已阅南山到平陆，更看东海变桑田。","桑田平陆真俄顷，古貌苍髯岁华永。","天上休誇种白榆，日边谩说栽红杏。","中兴天子建明堂，宰也执圭登庙廊。","松乎松乎合与宰为伍，万载千秋充栋梁。"]},{"t":"张夏道中遇雨短歌示同行诸子","f":"古风","c":["南山北山雨如注，寒风飒飒吹山树。","中河水发行子愁，褰裳欲渡且复休。","黑雾苍云蔽村舍，咫尺谁能辨牛马。","嗟哉出门百里行路难，我今胡为在中野。"]},{"t":"三月行","f":"古风","c":["往年三月春多旱，农夫望雨空愁叹。","今年三月雨太多，农夫转愁伤早禾。","却忆先皇御宸极，阴阳和调人足食。","万方只解歌太平，百姓何曾知帝力。","鸣呼鼎湖飞龙去不返，五风十雨何由得。"]},{"t":"题王二采莲图次壁上沈石田韵","f":"七言古诗","c":["秋塘露下菰蒲冷，野鹜沙凫夜相并。","东山月出一丈高，岸柳垂垂见疏影。","鸡鸣浦口渔伴稀，自采红莲溪上归。"]},{"t":"题石田画二首为杨仲深作 其一","f":"古风","c":["夕阳半落群峰高，古林萋迷猿正号。","欲招同人眺野色，安得扬州何水曹。","近烟苍苍远烟白，此时独作村西客。","君不见石子冈头萝薜深，麋鹿成群讵相识。"]},{"t":"题石田画二首为杨仲深作 其二","f":"古风","c":["平生不识石田子，往往相逢画图里。","世传百本无一真，抹青涂紫俱门人。","秋高对此双眼豁，倏然置我溪与壑。","君不闻画家贵意不贵工，只在冥冥漠漠中。"]},{"t":"为王工部大用题菜图","f":"古风","c":["采采雨间叶，青青陌上春。","欲知疏溉力，试问园中人。","纷纷钟鼎徒，醉卧饱肴胾。","不谓丹青手，能传使君意。","使君有园十亩强，时因采摘露沾裳。","短篱不许邻鸡入，嘉味还同过客尝。","后来勿斸园中土，留取清风千叶长。"]},{"t":"题贞洁卷","f":"五言古诗","c":["贞比高陵柏，洁比阴壑冰。","缅彼考槃客，相思劳寝兴。","至洁不可污，至贞不可变。","两世同一心，百年能几见。","柏有后秋叶，冰有中夏寒。","贞洁苟弗渝，炎雪何能干。"]},{"t":"题孔水部廷瑞双鹊图","f":"古风","c":["峨峨中庭石，傍此寒岁花。","离离错锦绣，五色明朝霞。","双鹊何处来，相对声喳喳。","似为主人报，水曹恩宠加。","水曹住近荆门闸，千里洪流归弹压。","疏排不数贾让功，决瀹尽遵神禹法。","玄圭早晚当告成，天王近日已知名。","崇阶峻级悬相待，岂用区区灵鸟声。"]},{"t":"题白岩竹","f":"七言古诗","c":["竹枝袅袅根卓卓，质坚不受苔藓剥。","是谁向壁扫缣素，古色苍颜秋濯濯。","彷佛犹自烟水区，万里湘潭土新斸。","又疑身坐风雨窟，老蛟盘挐突头角。","醉呼虞帝歌南风，苍梧云深翠华邈。"]},{"t":"题章郡守琼林醉归图","f":"古风","c":["宫杨媚朝旭，沟水鸣春湍。","别殿黄金瓦，横桥白玉阑。","借问此何地，无乃东长安。","长安陌头二三月，杏萼离离缀绯雪。","伊谁种此千万株，长待儒生与攀折。","孝皇龙飞十五春，亲策进士三百人。","是时嘉州有章子，名姓赫赫惊朝绅。","白马青袍速流电，日中醉下琼林宴。","吁嗟此日画里看，犹似当年陌头见。","陌头画里两模糊，可道今吾非故吾。","南台罢起郎官草，东郡聊分刺史符。","皎月寒冰清誉在，云霄随处是亨途。"]},{"t":"椿庭荣寿图诗","f":"七言古诗","c":["白头注书懒出门，足迹不到东西村。","倏忽移家向千里，远游却谢君王恩。","钱唐夜舸冲潮发，柏署啼乌晓方歇。","升堂见子复见孙，綵服如云映秋月。","江鱼竹笋称觞暇，时坐肩舆过城下。","苏公堤上闻采莲，岳王祠前看走马。","问君北归今几春，予欲乘槎西问津。","渡河先访封君宅，携酒来攀庭际椿。"]},{"t":"题杨四山卷","f":"古风","c":["苍峰崔嵬，翠巘巀嶪，阿祖当年手亲叠。","有得必失毁必成，天道往复天心明。","我开我堂酌我酒，蔼蔼岚光映虚牗。","朝对图书夕宾友，杨家子孙千世守。"]},{"t":"题刘道行祖母拾禾教子册","f":"古风","c":["朝拾田中禾，暮爇釜下薪。","止愿儿力学，不愁家业贫。","儿生有儿先入官，可随万里居长安。","帝予封章不肯受，却待成名报吾母。","江风吹船南入巴，阿孙奉使儿还家。","拜坟呼母母不语，泪湿秋山空黍花。"]},{"t":"题周道士采苓卷","f":"古风","c":["夫椒山中多老松，白云隐隐盘苍龙。","山人荷钁采苓去，往往仙人松下逢。","仙人本是山人作，山人向来满功课。","句丽勾吴几万里，杏花阴里春风大。","君不见蒲江古井凝绿华，乳婴绠上声唑唑。","长秋道士不入口，放鱼女儿升綵霞。"]},{"t":"题工部李侍郎给饷还朝卷","f":"七言古诗","c":["旄头焰射榆塞红，穹庐夜徙狼山东。","边头十堡九堡空，虎衔髑髅狐啸风。","箭书入奏龙改色，天兵啴啴下西北。","旌纛卷空空宇黑，冬官老臣奉丹敕。","百万刍粮纷崱屴，插羽鸣金捣河碛。","朔方血云蛇火赤，勃勒残兵走无迹。","归来谒帝甘泉宫，手执筹边书一通。","当廷不数搴旗功，呜呼老臣开济忠。","晓日沙堤散朝宴，黄金厩马辉相炫。","道傍观者谁不羡，韩公范老今重见。"]},{"t":"题李客部册为其母受敕焚黄作","f":"古风","c":["峨峨陇门碑，萧萧墓田草。","春卿哭母处，泪尽秋山道。","秋山云黄日脚斜，玄堂寂寂扃土花。","祀筵俎豆杂五鼎，玉文鸾纸明江霞。","月弦张宇登岁矢，二十星霜一弹指。","欲问春卿哭母心，潺湲日夜龙溪水。","水流不复返，母去何时回。","金沙閤珠翠，碧火扬青灰。","断机壁空蛛网窣，捣衣石冷啼蛄歇。","还家何物最堪伤，白发中庭坐明月。"]},{"t":"萱花图送刘汝忠归省","f":"古风","c":["萱草花，何袅袅。","春风入堂背，游子在远道。","白头慈亲相对看，日暮还成被花恼。","花未落，子登堂，白头一笑千忧忘。"]},{"t":"海樵吟","f":"七言古诗","c":["海樵老翁居海岛，自言不及山樵好。","山樵伐木归作薪，隆冬满室回阳春。","海樵网得珊瑚树，灶底欲燃燃不去。","日将空腹对家人，敢向山樵论饱饫。","中兴天子元会辰，大开阊阖罗九宾。","敕使四方求宝货，海樵尚食山樵饿。"]},{"t":"牵夫谣","f":"七言律诗","c":["上水逆风牵百丈，官舸真同上天上。","后笞前咤舆皂狞，努力揽牵谁敢放。","人喜牵夫歌牵歌，不知此中哀怨多。","何日黄流变黄土，牵夫得免奔波苦。"]},{"t":"竹坡子辞为徐侍御作","f":"楚辞体","c":["坡之竹兮茏葱，子揽辔兮在公。","子在公兮居靡遑，蹇予独兮坡之阳。","阳坡兮延伫，竹袅袅兮含雨。","愿秩质兮为箫，和翔凤兮仪鸣韶。","帝关兮峻深，与子归来兮坡阴。","守虚静兮抱贞素，听容与兮迟暮。"]},{"t":"爱日楼为钱水部作","f":"古风","c":["锡山之楼，水曹所构。","下瞰百川，上临斗宿。","层楣切霄，飞栱丽昼。","龙鳞差差碧瓦齐，峻梯蜒蜿垂丹霓。","俯视穷四极，仰观凌太虚。","雕楹列琪树，天窗秘灵书。","三光无冬春，和气通华胥。","不睹奇谲迹，谁明此楼是仙居。","楼中之母健且康，脩眉如发双瞳方。","云冠峨倒影，烟袂飘空香。","真澄瑩含元，穆坐楼中央。","兰孙玉息，献斝称觞。","擘斑麟，炮紫凰。","进文枣，倾瑶浆。","淋漓飒沓，罗列趋蹡。","舞拓拔，歌陵冈，一日愿作千岁长。","千岁长，万岁久，楼长新母长寿。"]},{"t":"弘治辛酉夏五月省元杜廷陈氏卧病旅邸予往问焉至则死矣逾四年其兄廷献会予京师言及泣数行下且谓不可无诗以哭其弟也追忆往事为补此篇","f":"楚辞体","c":["切切重切切，秋风桂枝折。","哀哀复哀哀，人归长夜台。","桐为棺兮席为舍，寒巷萧条日光下。","孤儿五岁初学行，向人啼父不成声。","访君来，哭君去。","乡路迢迢隔暝烟，潍水莱山渺何处。"]},{"t":"挽秦国声乃翁","f":"古风","c":["天井峰头暮烟紫，少微星落山翁死。","山前新墓土累累，石门题著封君字。","封君在时山水光，鸡群寒鹤何昂藏。","一身独作乡社表，见者呼为王彦方。","自从仙游去不返，江波寂寂江花晚。","钓竿三尺挂垂杨，野径无人竹门掩。","有生会有死，全归诚独难。","名归隐逸传，衔称大夫官。","佳儿擅时誉，采采云中鸾。","恩华烛幽邃，紫诰双龙盘，封君九原心亦安。","呜呼，封君九原心亦安。"]},{"t":"节义歌为方少参大器作","f":"古风","c":["囊金失，行子号，还子以金不受丝与毫。","良人殂，舅姑老，环堵麻衣不识门前道。","吁嗟乎墓中人，虽死死不孤。","诸郎致身文且武，恩光下照幽泉土。","妻也贞姬夫义夫，列传有名光烈祖，谁道今人不如古。"]},{"t":"朱子皋挽词","f":"古风","c":["约食墩前起新庙，乡人共说朱郎孝。","朱郎能孝复能仁，眼看盗贼皆良民。","直拟贞心化强暴，岂料势穷翻杀身。","君不见钱塘潮，汨罗水，同是乾坤忠义鬼。","春草碧色江绿波，魂招不来将奈何。"]},{"t":"钱国子水南挽歌","f":"古风","c":["君不见李世绩，姊病亲煮粥，粥火燎须须为秃。","又不见闵子骞，大雪被芦裘，一言悟父母复留。","水南茂才具二美，白首穷经辟雍里。","冻雾空嗟岭豹藏，春雷不见江龙起。","孝思之楼江水傍，四时礿祀烝且尝。","岂惟急难等原涉，还誇逊产同王商。","白鸡梦醒丹旌湿，精舍玄猿终夜泣。","凭将都士挽歌辞，裒作它年聘君集。"]},{"t":"陈司寇挽诗","f":"古风","c":["野白秋草黄，颓阳下枯岭。","谁歌蒿里曲，悽绪纷难整。","矗矗起新坟，素旗飘断云。","陇下笳箫哀响咽，尚书不归履声绝。","履声绝，那可招。","山空石麟死，松柏寒萧萧。"]},{"t":"王封君挽诗","f":"古风","c":["儿在客，父在床。","平生颜色不得一相见，虽有汤药何由将。","父在殡，儿在野。","生前不受豸史封，空见龙光贲泉下。","雪林山头高筑坟，花烟漠漠愁青春。","请看阡畔行啼者，半是当年怀惠人。"]},{"t":"吴节妇","f":"五言律诗","c":["风雨屋萧然，孤灯四十年。","家声越国后，心事纪姬前。","行入先皇录，名垂太史篇。","溪清石不转，寒影照娟娟。"]},{"t":"送周判官","f":"五言律诗","c":["一官成晚岁，共惜子云才。","驱马国门路，北风声正哀。","山形横塞起，边色映空来。","感慨登临处，残阳照古台。"]},{"t":"送张进士孔昭赴南刑部","f":"五言律诗","c":["春风扬子渡，江上雪初消。","草色连三月，山名记六朝。","白云官舍近，红日帝乡遥。","欲寄西来信，秦淮有落潮。"]},{"t":"送郑徵之还济南","f":"五言律诗","c":["昼锦人争羡，居官不离乡。","地亲王子贵，衙对佛山长。","珂马春情远，称觞午梦香。","相思有南雁，瑶草寄新芳。"]},{"t":"送康状元乃叔上舍生还武功","f":"五言律诗","c":["武功山路渺，西去雪巉巉。","里布儒生服，邮车使者衔。","上堂修典册，登陇拜松杉。","记取龙头事，乡人问阿咸。"]},{"t":"阙题 其一","f":"五言律诗","c":["久客便醒卧，逢君一举杯。","后山元苦节，同父旧多才。","雨映三更烛，春飘二月梅。","重来话相访，好记凤凰台。"]},{"t":"阙题 其二","f":"五言律诗","c":["往往风雩下，行歌大雅篇。","青春逢此地，白发感流年。","岸柳村村合，江花处处妍。","到官多暇日，一访谢公泉。"]},{"t":"和张内翰见寄韵","f":"五言律诗","c":["尔向家山去，休歌蜀道难。","乘车真得意，戏綵足承欢。","剑阁留诗草，亭溪把钓竿。","玉堂回首处，梦绕五云端。"]},{"t":"冯吕梁惠诗率尔酬赠兼谢药草之惠","f":"五言律诗","c":["高情冯水部，相见示新篇。","钟磬悬清庙，琼瑰落九天。","色流湖岸荇，香袭楚皋烟。","更谢金光草，扶予衰病年。"]},{"t":"临清舟中寄苏三泉","f":"五言律诗","c":["水国逢君寿，秋花荡客船。","河流动颜色，乡土接风烟。","天地青尊外，光阴素发前。","吾愁随日长，叨禄漫多年。"]},{"t":"送曾世亨兵备赴蜀","f":"五言律诗","c":["九秋三峡道，万里一舟孤。","夜渡剑门月，波光摇湛卢。","诗论青冢恨，恩返绿林逋。","岁晚东来使，梅花肯寄无。"]},{"t":"夜中不寐登楼有怀","f":"五言律诗","c":["远漏连疏柝，山空夜寂寥。","地看乡土隔，书寄美人遥。","海气含春色，江云入斗杓。","泺源桥上柳，应有拂阑条。"]},{"t":"送黄北川赴京","f":"五言律诗","c":["黄子黄门客，青春上国行。","风尘遥入望，边塞独关情。","捧日双龙阙，看云五凤城。","怀中有短疏，知欲请长缨。"]},{"t":"夜访朱应辰","f":"五言律诗","c":["启閤悬灯坐，霜天夜转幽。","居然剡溪兴，何异竹林游。","水落江鸿去，城孤海月流。","重逢好相忆，红蓼白门秋。"]},{"t":"寄吊松江周翁","f":"五言律诗","c":["不见南溪老，苍茫二十秋。","浦云空北望，江水自东流。","已化辽阳鹤，犹疑海畔鸥。","存亡一掬泪，何日洒林丘。"]},{"t":"解印后病中书怀二首留别南都诸同游 其一","f":"五言律诗","c":["敕放青山去，恩同碧海深。","静居谐始愿，孤往恝冥心。","已破槐南梦，何须泽畔吟。","我乡多水竹，苍翠想森森。"]},{"t":"解印后病中书怀二首留别南都诸同游 其二","f":"五言律诗","c":["一别齐川路，两年今始归。","久知麋鹿侣，遥待薜萝衣。","洞古龙还在，林深鸟不飞。","入山城市隔，从此迹应稀。"]},{"t":"过吕梁 其一","f":"五言律诗","c":["解缆洪流树，侵星过吕梁。","风云犹帝里，山水即吾乡。","砚拂秋岚湿，衣沾晓露凉。","长年欣暑退，伊轧棹歌长。"]},{"t":"过吕梁 其二","f":"五言律诗","c":["泽国新秋爽，玄云起北溟。","衣冠逢水部，风雨谢山灵。","雅意堪留滞，清词足典刑。","夕舟兼晓榻，谈坐忆蒲汀。"]},{"t":"送王分司因过白塔寺饮","f":"五言律诗","c":["九日登高兴，三秋怅别情。","重携一尊酒，此地共君倾。","塔涌浮云暗，山衔落日明。","还将红树色，遥送海东行。"]},{"t":"登南明山 其一","f":"五言律诗","c":["石磴抱云回，高高积翠开。","苍藤昏古殿，碧树隐仙台。","钟鼓三天下，风烟万壑来。","不知千载后，谁忆此衔杯。"]},{"t":"登南明山 其二","f":"五言律诗","c":["地僻无人赏，灵山迥独看。","石梁横险绝，岩洞倚高寒。","静已忘尘世，狂犹系冗官。","长歌送西日，野色上虚阑。"]},{"t":"南都送道士","f":"五言律诗","c":["自君辞白下，灵悟入玄冥。","始信虚无外，元来别有经。","乾坤寄水火，离坎走雷霆。","兀兀眼前事，真如江上萍。"]},{"t":"春雪","f":"五言律诗","c":["怪尔阳春日，凄凄昼雪寒。","情知飞絮假，还当落梅看。","向日偏萦户，随风故绕阑。","同云幕千里，吟坐忆长安。"]},{"t":"分赋春雨得时字","f":"五言律诗","c":["为爱西堂雨，黄昏坐不辞。","础痕移榻处，池涨捲帘时。","瑞纪农官颂，题分水部诗。","客车何日返，真长故山芝。"]},{"t":"九日","f":"五言律诗","c":["白日寒城暮，清秋画角哀。","地偏妨采菊，乡远怕登台。","鸿雁天边去，风云塞上来。","故交零落尽，卮酒向谁开。"]},{"t":"次陈静斋九日二首 其一","f":"五言律诗","c":["山水留佳赏，登临夙有期。","却怜重九日，空读汴台诗。","卧雨情无那，停云思欲痴。","夜深还秉烛，閒对菊花枝。"]},{"t":"次陈静斋九日二首 其二","f":"五言律诗","c":["九日逢连雨，宾朋屡费邀。","实孤黄菊盏，虚想绿云箫。","蟋蟀声逾近，梧桐叶尽飘。","喜闻归不远，旌节候来朝。"]},{"t":"九日登吹台次毛侍御韵","f":"五言律诗","c":["对酒重阳雨，登楼万里心。","异花开晚节，群木秀寒林。","鼓角连天暮，风云接塞阴。","王师捷何日，倾耳北来音。"]},{"t":"春暮","f":"五言律诗","c":["骨肉俱零落，还家不似归。","自伤真块处，谁更遣花飞。","雨揠春苗病，风摧旅雁稀。","飘飘木兰楫，吾欲泛东沂。"]},{"t":"颐痾清源中秋罹雨宵分言霁短音寓怀","f":"五言律诗","c":["隔岁乡关月，中秋想一看。","真愁白发显，翻隐碧云端。","桂影流烟湿，金波映浦寒。","鸡鸣兴不浅，吟酌细凭阑。"]},{"t":"正月七日饮敖水部分司归即事","f":"五言律诗","c":["结舍临江岸，传觞感岁华。","偶同人日酒，翻滞使星槎。","水冻仍馀雪，林寒且未花。","醉归烧短烛，高枕听昏鸦。"]},{"t":"宝应元夕饮朱升之舍","f":"五言律诗","c":["望望平安驿，春行路不遥。","故人还此地，芳序且元宵。","水近潮通閤，灯寒月过桥。","计程拚取醉，佳赏更须招。"]},{"t":"供事长陵","f":"五言律诗","c":["俎豆荐春芳，东陵昼漏长。","偃松盘古榭，灵草秀虚堂。","日月皇舆远，江河圣历昌。","因山昭俭德，千载颂文皇。"]},{"t":"西陵访王给事汝温不遇","f":"五言律诗","c":["狂夫多野性，春到每思家。","却访山中客，还逢水际花。","薄云阴古殿，鸣鸟聚连沙。","迤逦回溪晚，西陵月正斜。"]},{"t":"游玄福宫","f":"五言律诗","c":["福地盘青甸，香台倚绀云。","材分龙藏宝，功就羽林军。","洞客脩丹箓，山灵护敕文。","愿资玄教力，千载翊明君。"]},{"t":"泰陵供事述感五章 其一","f":"五言律诗","c":["陵墓三年道，重来七月期。","山河不改色，霜露只增悲。","世想钦明德，人传顾命辞。","九龄如帝与，端可致雍熙。"]},{"t":"泰陵供事述感五章 其二","f":"五言律诗","c":["㳟已班虞舜，求贤越武丁。","心犹在边徼，梦已隔泉扃。","永作千秋别，虚传七日醒。","夕庐斋沐所，彷佛见遗形。"]},{"t":"泰陵供事述感五章 其三","f":"五言律诗","c":["象设徒虚傋，龙游竟不还。","勋华留率土，精爽寄空山。","石锢金泉黝，云栖碧殿閒。","寝园如种竹，应有泪成斑。"]},{"t":"泰陵供事述感五章 其四","f":"五言律诗","c":["皇寝居庸近，山深地转饶。","雄关三镇锁，幽府百灵朝。","堡堠烽全息，屯兵甲半销。","帝心遥可识，终古绝天骄。"]},{"t":"泰陵供事述感五章 其五","f":"五言律诗","c":["午夜祠钟发，千官集广墟。","遂看除禫服，那复见宸裾。","长隧通玄壤，明楼瞰紫虚。","松阡回望里，风雨泣涟如。"]},{"t":"下陵二首 其一","f":"五言律诗","c":["露行踰十里，夜黑四岩阴。","不辨云霞色，惟闻钟磬音。","堑鸦翻列火，山鬼啸空林。","欲下西陵路，前沟水正深。"]},{"t":"下陵二首 其二","f":"五言律诗","c":["窈窈山径僻，喧喧徒御归。","马逢危石住，灯入古林稀。","树密全妨盖，云寒半湿衣。","红门知不远，秋角听依微。"]},{"t":"望孝宗陵","f":"五言律诗","c":["泰陵今在目，突起茂阡西。","宫殿青霄迥，松杉白日凄。","坤墟符帝宅，山寿与天齐。","黍稷明年祀，重来路不迷。"]},{"t":"郊坛夜步","f":"五言律诗","c":["晚步凌高榭，春空月正明。","星辰临汉畤，楼观俯秦京。","静夜松飙响，丰年谷日晴。","同心隔城市，相望转盈盈。"]},{"t":"候驾","f":"五言律诗","c":["遥闻葆吹声，仙仗下通明。","地转苍龙道，天临白玉京。","瑞光同远近，云物半阴晴。","隐隐行宫启，重关虎豹盈。"]},{"t":"上陵","f":"五言律诗","c":["卧病长夏晚，出门秋草生。","聊因上陵日，一寄看山情。","野水侵平道，寒云覆古城。","圣君方用武，群盗敢纵横。"]},{"t":"五月七日陪李刘二侍御游宴尹亭","f":"五言律诗","c":["不到北湖久，重来莲叶青。","水香还落照，山色自孤亭。","竹隐尚书榻，窗悬柱史星。","回舟忽已晚，波上月冥冥。"]},{"t":"九月望日同大阳有台二使君泛湖出郭二首 其一","f":"五言律诗","c":["野眺邻幽旷，移舟出水关。","上卿双盖迥，渔父一蓑閒。","坠叶纷飘座，回汀曲抱山。","芳尊对摇落，不醉可须还。"]},{"t":"九月望日同大阳有台二使君泛湖出郭二首 其二","f":"五言律诗","c":["候火射波光，中流见女墙。","观楼增突兀，云月递微茫。","岸接青山近，舟搴绿芷香。","兴酣忘夜久，歌吹绕林塘。"]},{"t":"村舍","f":"五言律诗","c":["村舍孤烟起，山中朝雨寒。","丁夫荷锄去，稚子出门看。","早稼登场圃，秋瓜蔓井阑。","居然羡閒逸，趋府欲辞官。"]},{"t":"山行","f":"五言律诗","c":["两山开一径，杳杳入云烟。","仄磴樵人下，危峰野衲禅。","断鸿愁返照，归马识斜川。","井邑干戈后，凋零异昔年。"]},{"t":"御帐坪次王伯安韵","f":"五言律诗","c":["白日天门近，青山御帐空。","亭虚从眺览，树古自登封。","过鸟层云上，鸣泉万壑中。","翠华春不返，惆怅昔人踪。"]},{"t":"题清乐亭","f":"五言律诗","c":["老木隐江亭，幽居对锦城。","榻悬西岭雪，墙度浣溪莺。","地僻人稀到，心閒梦亦清。","穷通身外事，何必问君平。"]},{"t":"重阳后三日登雨花台","f":"五言律诗","c":["一片金陵月，荒台对酒看。","水云霏冉冉，江日隐团团。","雁早那堪听，花迟未可餐。","凭轩望乡国，西北近长安。"]},{"t":"与平厓林豸史泛湖北抵华不注山夜从陆归二首 其一","f":"五言律诗","c":["浮舟出近郭，落日半溪阴。","水阔蒹葭净，山寒烟雾深。","壶觞不尽兴，丝竹有馀音。","独恨黄花少，犹烦隔浦寻。"]},{"t":"与平厓林豸史泛湖北抵华不注山夜从陆归二首 其二","f":"五言律诗","c":["黄昏过别业，却见旧山僧。","客驾聊云息，乡愁转更增。","水光浮夜月，林影散秋灯。","隔苑闻寒犬，高轩醉懒乘。"]},{"t":"后三日登龙洞山二首 其一","f":"五言律诗","c":["海峤烟霞满，登临爱积阴。","绿苔穿岭滑，黄叶缀岩深。","宛宛鹿麋径，泠泠泉涧音。","高人或住此，精舍杳难寻。"]},{"t":"后三日登龙洞山二首 其二","f":"五言律诗","c":["寺古犹存佛，山深少见僧。","迟徊意不极，去住感偏增。","树隐青林店，龛明白石灯。","峭峰吾欲上，未有鹤堪乘。"]},{"t":"宋驸马园亭访东石谈子遇雨","f":"五言律诗","c":["却访故人处，遥来公主园。","湿云蒸锦树，鸣雨过华轩。","槛近浮鸥接，庭深乳雀喧。","将求卜居意，相对已忘言。"]},{"t":"赠周文都","f":"五言律诗","c":["君乘别驾车，南征千里馀。","予为燕市客，岁杪意何如。","日隐川原暮，江涵云水虚。","新春见回雁，知有秣陵书。"]},{"t":"寄华山人","f":"五言律诗","c":["山人归薜萝，迢递两年过。","道远情无那，秋来兴若何。","隰霜收早稻，江日曝寒蓑。","不见云中鹄，空传招隐歌。"]},{"t":"赠何子元二首 其一","f":"五言律诗","c":["饮马长城窟，西风陇水鸣。","旌旗连朔气，笳吹咽边声。","鹿塞秋霜白，龙沙汉月明。","共嗟班定远，身是一书生。"]},{"t":"赠何子元二首 其二","f":"五言律诗","c":["万里穷边使，三秋出井陉。","金鞍装宝络，斑管代青萍。","吏识终军貌，人瞻博望星。","归来市骏马，持节报明廷。"]},{"t":"行子","f":"五言律诗","c":["行子到京舍，故人消息传。","钓鱼吹台下，筑室黄河边。","插架馀千帙，倾囊有一钱。","古来贤达者，往往在林泉。"]},{"t":"彦卿垂示省署述怀之作次韵奉荅 其一","f":"五言律诗","c":["寂寂荒园午，庭虚不下帘。","墨池经雨润，厨火隔宵熸。","壁溜侵湘簟，窗风动越缣。","灌花亲汲水，童子睡初甜。"]},{"t":"彦卿垂示省署述怀之作次韵奉荅 其二","f":"五言律诗","c":["官閒仍地僻，宾从少经过。","睡起看山立，诗成对竹哦。","小塘云影乱，深树鸟声多。","坐数秋期近，双星欲渡河。"]},{"t":"过双泉寺马文明别业怀寄","f":"五言律诗","c":["却过双泉寺，因怀马舍人。","托交空有日，为别动经旬。","古泽蓼花乱，高原禾黍新。","秋风吹独马，望尔一伤神。"]},{"t":"山中怀白岩二首 其一","f":"五言律诗","c":["珂马长安道，趋陪几见秋。","那知迁转地，翻动别离愁。","光禄诗名远，容台礼数优。","空山中夕梦，长绕凤凰楼。"]},{"t":"山中怀白岩二首 其二","f":"五言律诗","c":["昔奉山陵使，曾同虞殡吟。","鳌翻沧海变，龙去鼎湖深。","紫极瞻云地，清霄望月心。","苍苍松柏里，怀往益沾襟。"]},{"t":"怀昌谷大理二首 其一","f":"五言律诗","c":["孺子南州彦，词华早擅场。","共怜廷尉府，秪益簿书忙。","宝縼愁鹦鹉，盐车困骕骦。","何时一艇去，与尔泛沧浪。"]},{"t":"怀昌谷大理二首 其二","f":"五言律诗","c":["斋房隐薜萝，野外少人过。","向月复谁语，看山空自歌。","城孤戍火乱，地迥北风多。","惆怅离居夕，相思奈尔何。"]},{"t":"白岩将赴北山供祀奉呈","f":"五言律诗","c":["赋客贪岩壑，登临思渺然。","出城看落日，驱马入秋烟。","藓缀陵门棨，蘋香寝庙笾。","别来曾见说，重补华山篇。"]},{"t":"张侍御过访不值谢荅","f":"五言律诗","c":["有客骑骢马，徘徊恋友生。","虚烦过茅屋，实已隔山城。","野僻蓬蒿满，园荒蟋蟀鸣。","空村中夕梦，相忆倍含情。"]},{"t":"雪后尹亭小集有怀张侍御仲齐","f":"五言律诗","c":["樽酒故相约，燕游翻不同。","亭深寒雪在，桥断夕烟通。","白日行歌里，青山别恨中。","夜阑车马寂，愁听竹林风。"]},{"t":"尹亭夜集 其一","f":"五言律诗","c":["忆共尚书饮，兰舟漾渚风。","芙蓉开月下，箫管入云中。","鹤唳烟沙远，萤流水閤通。","重来值摇落，无复往时同。"]},{"t":"尹亭夜集 其二","f":"五言律诗","c":["晃晃水上月，棱棱沙际风。","寒星动木杪，远火露烟中。","城郭千峰对，园林一水通。","兴移还野酌，留赏夜深同。"]},{"t":"将赴灵岩午憩黄山店示同游诸子","f":"五言律诗","c":["感时愁不极，出野兴仍高。","墟野当红药，园林过碧桃。","水行沙路软，云卧石床牢。","更喜山翁朴，忘形对尔曹。"]},{"t":"出黄山村遇霍子闻郡守章柳庵将至灵岩喜而有作","f":"五言律诗","c":["路转黄山店，人逢霍茂才。","传呼寺僧出，五马欲东来。","野水村村响，岩芳树树开。","浪游双屐齿，沾湿破苍苔。"]},{"t":"由张夏村赴靳庄望同游诸子","f":"五言律诗","c":["落日过张夏，黄昏投靳庄。","岭牛将犊下，沙鹤避人翔。","石径盘青霭，柴门闭绿杨。","同游忽不见，孤眺转苍茫。"]},{"t":"靳庄山馆即事次张侍御仲齐韵","f":"五言律诗","c":["野馆千峰对，登临日载阳。","山川气纡郁，天地色凄凉。","未卜三秋稼，先传二月蝗。","古村兵燹后，摇落见空墙。"]},{"t":"出靳村望灵岩寺","f":"五言律诗","c":["福地灵山表，来游春已深。","情知百里道，虚抱十年心。","野树犹含色，鸣禽欲变音。","花宫瞻望处，烟雾绕青岑。"]},{"t":"迟贤亭有怀白泉王子诏盖与余同游泰山而余先王子归也","f":"五言律诗","c":["树杪游云白，风前落絮轻。","行蜗上壁篆，斗雀堕檐楹。","客驾聊言息，仙踪不可明。","怀人望东麓，逦逦曙烟横。"]},{"t":"春日卧病寄刘子希尹王子孟宣 其一","f":"五言律诗","c":["我济富山水，人称名士乡。","两生俱俊杰，吾道岂荒凉。","紫禁烟花地，青云翰墨场。","应须得高步，书札报沧浪。"]},{"t":"春日卧病寄刘子希尹王子孟宣 其二","f":"五言律诗","c":["老病东山客，青春意䬃然。","祗因愁不去，翻与醉相牵。","草檄怀公干，登楼忆仲宣。","几时莲叶里，重放北湖船。"]},{"t":"段村候成之佥宪","f":"五言律诗","c":["客子复迎客，黄昏行古林。","短墙登吠犬，列火动栖禽。","对雪三年梦，维舟半夜心。","他时重相见，佳话比山阴。"]},{"t":"柬河内使粹夫","f":"古风","c":["忆尔曾金马，予官亦?闱。","惊风一以振，落羽遂分飞。","东郡身仍屈，西河信每稀。","传经与抗疏，心事两相违。"]},{"t":"移榻","f":"五言律诗","c":["卧榻便幽赏，虚廊接瞑移。","树云低绕栋，阶雨下通池。","病间琴相得，心劳砚独知。","商歌激流楚，惆怅北山期。"]},{"t":"赠萧医士","f":"五言律诗","c":["览镜叹华发，出门乡路遥。","客装侵暮雨，归楫渡春潮。","草绿河阴细，莺啼苑外娇。","荷锄行采药，还似赤城樵。"]},{"t":"赠方山郑子二首 其一","f":"五言律诗","c":["江东有狂士，结屋本深山。","为客风尘外，驰声梁楚间。","才聆扪虱语，忽作钓鳌还。","予亦悠悠者，相逢愧尔閒。"]},{"t":"赠方山郑子二首 其二","f":"五言律诗","c":["好酒耻儒素，谈兵靖塞尘。","深怜宋中客，宛似晋时人。","到处不谐俗，一生长任真。","因君感交态，多少白头新。"]},{"t":"赠伍文定太守移吉安","f":"五言律诗","c":["巩洛移官日，荆襄过里年。","郡符分旧虎，江树听新蝉。","河内人虚借，关东政久传。","行经五柳宅，一为吊先贤。"]},{"t":"元旦","f":"五言律诗","c":["上日冥冥雨，中宵且未休。","薄游双剑在，羁宦一身留。","养鹤怜初志，屠龙悔壮谋。","著书聊假日，元不坐穷愁。"]},{"t":"寄无锡管尹","f":"五言律诗","c":["吾爱管明府，理民如昔贤。","静看申浦月，清饮慧山泉。","惠化表三异，和声流五弦。","春风阻携手，相忆思悠然。"]},{"t":"荅松月伍中丞见寄","f":"五言律诗","c":["开閤俯江城，怀人独系情。","碧云空旧色，黄鸟又新声。","剑在终相合，舟閒且自横。","凤凰台上月，孤负一春晴。"]},{"t":"舟泊清江有怀交游诸公二首 其一","f":"五言律诗","c":["未暖金陵席，还趋玉陛行。","汉仪欣再睹，虞秩愧惟清。","雨雪江南曲，关山岁暮程。","临分约归候，春服早须成。"]},{"t":"舟泊清江有怀交游诸公二首 其二","f":"五言律诗","c":["日射江流紫，烟沙冻欲开。","臈从梅蕊破，春傍雪涛回。","北斗瞻星入，东风应律催。","鹓鸾隔朝省，不共上元杯。"]},{"t":"柬朱柱史子宜","f":"五言律诗","c":["有美中台彦，闻名自国都。","岂知多难日，识面在江湖。","地入王畿远，星分客棹孤。","霜威倘可借，一为保前途。"]},{"t":"斋居同月岩夜坐","f":"五言律诗","c":["寂寂槐厅晚，端居感岁时。","雪消山色在，寒退井痕知。","白战怀苏老，清斋伴子期。","坐来情转逸，华月照方池。"]},{"t":"贺承庵侍史省亲还绩溪","f":"五言律诗","c":["上疏天门北，驱车海峤东。","去留真自得，心迹许谁同。","诗入杜陵室，官追桓典风。","寿筵家庆好，花对白头翁。"]},{"t":"汶上寄王工部舜夫二首 其一","f":"五言律诗","c":["真拟湖边会，言从汶上过。","岁时鸣鸟变，岐路转蓬多。","树色连东岳，川流汇北河。","相思阻欢觏，瞻望恨如何。"]},{"t":"汶上寄王工部舜夫二首 其二","f":"五言律诗","c":["幸不逢颜色，真愁吐肺肝。","祗因哭子瘦，岂是别家难。","雨麦虚看秀，风梅实抱酸。","病怀兼逆旅，谁与一盘桓。"]},{"t":"寄陈石峰中丞","f":"五言律诗","c":["一别梁园雨，五看秋草疏。","君为乌府客，我向白门居。","发短风尘里，心长老病馀。","江流日东下，何处觅双鱼。"]},{"t":"出郭将访希准郡伯惧暮而返却寄","f":"五言律诗","c":["驾言江口出，却至水西还。","远道空回首，重门欲上关。","断云低白雁，斜日近青山。","欲采瑶华赠，仙舟不可攀。"]},{"t":"和荅胡可泉郡伯","f":"五言律诗","c":["籍籍胡安庆，新声满旧都。","讵知金马客，翻领玉麟符。","退食还经史，登楼即画图。","昔贤忧乐地，元只在江湖。"]},{"t":"溪翁","f":"五言律诗","c":["未觌溪翁面，中宵梦已先。","关山非逆旅，舟楫是登仙。","雁语惊霜别，莺啼候谷迁。","烟波夕渺渺，留恨满江田。"]},{"t":"赠李都阃","f":"五言律诗","c":["好武将军独，能文更爱君。","异勋江左策，名阀陇西闻。","散帙临秋水，投壶过夕曛。","长怀醉别处，箫吹遏溪云。"]},{"t":"奉荅王载卿方伯","f":"五言律诗","c":["菊蕊南山屐，荷华北渚船。","胜逢无节序，佳句有云烟。","列郡讴歌里，沧溟览眺前。","故乡谁地主，回首忆当年。"]},{"t":"写怀","f":"五言律诗","c":["欲逃中夏暑，暂上上江船。","夜卧对松月，晓行披水烟。","佳期渺天末，良觏阻尊前。","相问各华发，遥悲青镜年。"]},{"t":"再赠载卿","f":"五言律诗","c":["宾堂瞰水浒，沙柳系行船。","袅袅绿萝月，冥冥芳浦烟。","乡关百里外，世事一尊前。","记取相逢地，清河旅食年。"]},{"t":"戏赠张守公荐","f":"五言律诗","c":["蜀郡留工部，任城卧谪仙。","古人多逆旅，地主几称贤。","岁月青尊里，乡关白雁前。","知章与严武，君不愧当年。"]},{"t":"近闻石翟子驻节河口喜而有赠二首 其一","f":"五言律诗","c":["近闻临驻处，陌上草萋萋。","碧水春风外，青山晚月西。","君车建高节，旅舸系平堤。","岂料漳河饮，同闻络纬啼。"]},{"t":"近闻石翟子驻节河口喜而有赠二首 其二","f":"五言律诗","c":["栖棘诚堪惜，崇迁且汴台。","不因盘错试，谁辨镆铘才。","赤日昭天鉴，黄河殷地雷。","凌秋泛槎去，知向斗边回。"]},{"t":"柬王美卿万户","f":"五言律诗","c":["见说君家圃，新开夜合花。","暝云含洞石，炎雨净溪沙。","想像王郎剑，迟徊汉使槎。","一尊虚旧约，惆怅坐昏鸦。"]},{"t":"旅寓清源有怀故乡亲友","f":"五言律诗","c":["雨过双松午，云阴覆閤长。","柳蜩迎日嘒，芹燕落泥香。","碧水通官舍，青山接故乡。","怀人不可见，归思转苍茫。"]},{"t":"赠宋医","f":"五言律诗","c":["施药漳河口，高龄鬓未华。","地疑京兆市，人即宋清家。","石壁垂金草，丹炉起玉花。","愿传玄牝诀，交臂入青霞。"]},{"t":"雨中卧病谷来许以诗来问荅之","f":"五言律诗","c":["尔本游扬侣，吾惭程氏门。","遥怜雪盈尺，何似雨翻盆。","久病抛书卷，长斋闭酒尊。","草堂霞色晚，好过一相论。"]},{"t":"重阳冷二守过访留酌","f":"五言律诗","c":["九日逢知己，开尊傍水涯。","壮怀馀白首，幽赏有黄花。","日隐郊台暮，云连浦树斜。","未须论去住，乘兴即为家。"]},{"t":"徐园夜坐有怀","f":"五言律诗","c":["避暑将军府，青青竹满园。","坐看台上月，吟忆水西轩。","萤火流烟度，蚊雷接暮喧。","美人漳浦卧，何日奉清言。"]},{"t":"赠环峰王总戎西征","f":"五言律诗","c":["开府驰声旧，辕门授钺频。","日华承盖转，江色映袍新。","去作郧山雨，来经蜀道春。","军中人尽说，筹策妙如神。"]},{"t":"荅罗兖州","f":"五言律诗","c":["我抱文园渴，君淹曲阜城。","中年俱抱屈，异地各悬情。","永夜孤蟾色，新秋旅雁声。","况闻吴楚变，汉帝且南征。"]},{"t":"寄胡文甫","f":"五言律诗","c":["不见胡文甫，七回明月圆。","家林且如此，宦海益堪怜。","碧柳秦台马，红蕖济水船。","往来馀百里，同醉是何年。"]},{"t":"午日卧病有怀张王二子","f":"五言律诗","c":["栖迟仍旧国，愁病且端阳。","白发能相妒，清尊漫自香。","壁虚悬艾好，溪迥入舟妨。","苦忆青骢客，盈盈水一方。"]},{"t":"赠郑少尹","f":"五言律诗","c":["我正雪中卧，君从天上还。","节高元自苦，才大可能閒。","淅沥听疏竹，苍茫对远山。","夜深拚一醉，休当剡溪湾。"]},{"t":"赠刘希容","f":"五言律诗","c":["籍籍刘京兆，还家尚黑头。","无心恋簪组，有子绍箕裘。","月夜楼中坐，花时郭外游。","不堪相访地，醒眼话离愁。"]},{"t":"怀王生","f":"五言律诗","c":["世弃君平久，狂疏老更添。","绝人吾岂好，嗜酒子应嫌。","荷叶翠出水，榴花红入帘。","晚当西牖坐，山日映书签。"]},{"t":"夜访德宣不值","f":"五言律诗","c":["坡陀古堤上，往来伤独游。","相违岂在远，一见已无由。","水宿厌栖泊，暮行多懔忧。","琼枝不可即，肠断卫川流。"]},{"t":"寄徐进甫","f":"五言律诗","c":["城东徐孺子，不见已三年。","鸿雁几时至，音书谁与传。","钓鱼寒涧曲，注易古林边。","遥想府中榻，常因高士悬。"]},{"t":"过汴呈献吉","f":"五言律诗","c":["两年京郭居，空望故人书。","五月梁园道，来乘长史车。","川流赴海急，隰日漾沙虚。","欲访渔樵径，蓬蒿不可除。"]},{"t":"夜泊汉阳却望武昌有怀矩庵","f":"五言律诗","c":["对岸武昌郭，清宵回望频。","离心系舟远，旅梦涉江新。","积水明疑昼，浮烟霭似春。","楼空黄鹤杳，延伫独劳神。"]},{"t":"白泉王子居山相近","f":"五言律诗","c":["尔能耽野趣，吾亦爱村居。","白屋情偏好，苍山画不如。","桑麻通雪径，鸡犬接烟墟。","岁晚青藜在，相过且校书。"]},{"t":"同王白泉步过北村访孙胡二子","f":"五言律诗","c":["少日同门客，山居晚共依。","孤村一相访，深树鸟声稀。","面水心逾静，班荆愿不违。","苍苍平野际，还望瞑烟归。"]},{"t":"谷子访予别业","f":"五言律诗","c":["谷生怜我独，相访到山家。","碧水孤村抱，垂杨一径斜。","野人共白酒，稚子饭胡麻。","坐爱残阳里，庭槐吐细花。"]},{"t":"怀三屏子","f":"五言律诗","c":["北郭雨冥冥，东山云雾青。","三屏不我对，九柳自吾亭。","短发嗟同病，长歌笑独醒。","临溪抚身世，百载一浮萍。"]},{"t":"送陆子引","f":"五言律诗","c":["世业机云后，声光慱望前。","使星连禹服，卿月渺吴天。","岸迥山回枕，泥香燕拂船。","壮游应不负，随处有诗篇。"]},{"t":"送唐仁夫","f":"五言律诗","c":["象阙指龙洲，天南海北头。","岛夷随使节，山鬼避行舟。","墓采秋蘋奠，乡看昼锦游。","归期定何日，瑶草思悠悠。"]},{"t":"送施克和","f":"五言律诗","c":["楼敞壁灯悬，归心夜不眠。","袖中怀楚玉，江口泛吴船。","兴寄风人外，名收国士前。","秋来消息好，知向鹿鸣传。"]},{"t":"送刘氏叔侄赴举","f":"五言律诗","c":["双马饮溪流，溪边雨乍收。","方趋棘围战，不比竹林游。","礼学传三世，家声动九州。","太行山上月，几日桂花秋。"]},{"t":"送徐德章兼寄杭世卿吏部","f":"五言律诗","c":["迢递延陵路，新乘使者车。","国风收外史，庙号布中书。","海色宵征里，薇花午梦馀。","相逢杭吏部，归楫问何如。"]},{"t":"送范掾尉仁和","f":"五言律诗","c":["入仕得亲欢，舟行且问安。","青山越州路，黄绶汉时官。","暑服裁江练，名花荐渚兰。","六桥三塔景，公暇几回看。"]},{"t":"送刘博之参政南阳二首 其一","f":"五言律诗","c":["蓟北才能会，声华早见收。","道高传吏部，诗好入随州。","别宴当梅雨，官程过麦秋。","江湖忧正切，休上望京楼。"]},{"t":"送刘博之参政南阳二首 其二","f":"五言律诗","c":["津桥南渡头，落日片帆收。","冠盖新方岳，河山古豫州。","树深燕市晚，云冷爵台秋。","两地分千里，怀人各倚楼。"]},{"t":"送黄端州","f":"五言律诗","c":["春水泛桃花，飘飘海上槎。","官崇先领郡，亲老一还家。","石抱溪云紫，烟含岭树斜。","夜深登望处，北斗是京华。"]},{"t":"送王秉衡归省","f":"五言律诗","c":["津树隐春艭，林花集暮江。","天涯归客远，堂上老亲双。","捧日心常切，看云梦未降。","閒来书谏草，谁与坐山窗。"]},{"t":"送曹元孝监河之徐州二首 其一","f":"五言律诗","c":["水部移舟楫，临津问所须。","离心汉宫柳，幽梦楚垓芜。","雁迥云重覆，花寒地一隅。","吟诗坐东阁，谁与鉴冰壶。"]},{"t":"送曹元孝监河之徐州二首 其二","f":"五言律诗","c":["石閤延春望，洪舠送酒须。","断蛇荒泽徙，戏马旧台芜。","碧树通江徼，苍烟接海隅。","三山不可见，休更问蓬壶。"]},{"t":"再寄其子毅之","f":"五言律诗","c":["相寻空缱绻，相别太斯须。","一去青门道，几回生绿芜。","文章传海内，消息阻天隅。","岁晚登高忆，劳歌缺唾壶。"]},{"t":"藏六轩夜别东卿","f":"五言律诗","c":["到寺钟初寂，高城夕漏迟。","閤云昏冉冉，庭雨冻丝丝。","留客灯前席，怀人海上诗。","树鸦啼不断，岁杪怨相离。"]},{"t":"赠周予庚使辽左","f":"五言律诗","c":["翩翩鸣玉珂，千里渡辽河。","尔本诗书客，宁闻铙吹歌。","立朝同汲黯，出使比萧何。","莫厌貂裘敝，霜风塞上多。"]},{"t":"简别华文光同年","f":"五言律诗","c":["朔野北风起，沙蓬飞不休。","端居念行客，明发动归舟。","古堞鸣禽暮，虚堂落木秋。","重来不相见，离梦转悠悠。"]},{"t":"送华文远","f":"五言律诗","c":["早蝉鸣树头，归棹渡江秋。","孝子祠重建，徵君传已修。","泪痕双苧袖，身世一弓裘。","不学龙门客，逢人说远游。"]},{"t":"送董汝淳太守之楚雄二首 其一","f":"五言律诗","c":["诗人重出守，万里一朱轓。","苦节留三郡，英声振五言。","山深夜郎道，花乱武陵源。","月下劳相忆，清秋几处猿。"]},{"t":"送董汝淳太守之楚雄二首 其二","f":"五言律诗","c":["井鬼占星地，滇云问路时。","岭暄秋瘴湿，江远暮帆迟。","竹弩迎津吏，毡裘拜岛夷。","课耕还吊古，应到孔明祠。"]},{"t":"别顾华玉同年四首 其一","f":"五言律诗","c":["问讯金陵客，南归近有期。","马行沾雨慢，蝉响入秋迟。","水稻供慈膳，江绡制寿帷。","閒居赋成后，曾见几人为。"]},{"t":"别顾华玉同年四首 其二","f":"五言律诗","c":["落日长干渡，西风短棹过。","故人归后少，秋草望中多。","谢墅荒碑碣，吴宫閟绮罗。","趋庭休浣外，临眺意如何。"]},{"t":"别顾华玉同年四首 其三","f":"五言律诗","c":["官署依乡土，幽求满素心。","窗临逸少帖，墙挂宓生琴。","种药开春径，看云坐晚林。","避名名转出，休爱碧山深。"]},{"t":"别顾华玉同年四首 其四","f":"五言律诗","c":["达人氛垢远，流品自应殊。","骏枥分天厩，鸾巢托省梧。","葛洪勾漏尹，阮籍步兵厨。","未识图南志，相逢说著书。"]},{"t":"送秦用中邑博得盐字","f":"五言律诗","c":["残溜滴崇檐，离杯雨夜添。","儒官归郑老，诗客去高蟾。","调发囊琴古，光涵匣剑铦。","昔贤身未达，多少在鱼盐。"]},{"t":"芮令尹之兴宁","f":"五言律诗","c":["万里惠州去，旅情应独伤。","暮云牛岭暗，秋草雁池荒。","古迹怀苏老，清吟和李纲。","遥怜蛮聚落，从此识甘棠。"]},{"t":"赠别三首 其一","f":"五言律诗","c":["相逢不忍别，相送思悠悠。","风雨一宵话，关山千里愁。","暮潮通极浦，寒燕逐行舟。","短发年年白，重看是几秋。"]},{"t":"赠别三首 其二","f":"五言律诗","c":["早叶半辞林，晚蟾初罢吟。","入秋乡国梦，垂老故人心。","道在宁须禄，官清尚有琴。","城隅分手处，惆怅水云深。"]},{"t":"赠别三首 其三","f":"五言律诗","c":["独持文字印，遥泛木兰舟。","古驿寻京口，寒城过石头。","诵声分馆夜，吟思捲帘秋。","欲问前朝迹，青山是蒋州。"]},{"t":"送孙志同经略居庸二首 其一","f":"五言律诗","c":["宝剑青骢马，秋高出塞行。","田公新受律，武子旧传兵。","鼓角边云惨，旌旗海日明。","穹庐莫南徙，中国有长城。"]},{"t":"送孙志同经略居庸二首 其二","f":"五言律诗","c":["马出燕关道，人如定远侯。","眼空沙漠气，心系庙堂忧。","绝塞苍烟暮，荒山白草秋。","军都城下过，怀古一登楼。"]},{"t":"送朱文表","f":"五言律诗","c":["关河积雨晴，千里一舟行。","庾廪司农计，山川故国情。","古碑寻盻子，芳草识聊城。","想见登临处，遥心览八瀛。"]},{"t":"送杨生","f":"五言律诗","c":["相见十年外，相寻千里馀。","青衿子老大，白发我何如。","涕泪丘园草，风尘故旧书。","别情那可忆，云月晓窗虚。"]},{"t":"送王载卿","f":"五言律诗","c":["万里云霄使，三秋泽国船。","冰霜消岭瘴，旌盖丽江烟。","国赋徵求里，民风奏记前。","独怜诗社冷，一别又经年。"]},{"t":"送李佥宪维之北上","f":"五言律诗","c":["桓典乘骢日，相如卧病春。","伤心一杯酒，回首十年人。","雪暗关山色，风飘驿路尘。","郭西慵出饯，愁见柳条新。"]},{"t":"送王君宠主潼津驿","f":"五言律诗","c":["潼津佳胜地，驿舍近潼关。","立马看河水，开窗对华山。","客怀登览际，官守送迎间。","倘见三秦友，传予鬓已斑。"]},{"t":"送刘文振宰驿华山兼寄汝公太守","f":"五言律诗","c":["我抱游秦志，君今先我行。","一杯同出廓，千里独含情。","雨入新丰晚，云移少华晴。","寄言桑郡守，天子近知名。"]},{"t":"送李司务思善二首 其一","f":"五言律诗","c":["可怪皇华使，相逢九日过。","地偏秋雁少，天迥莫云多。","北渚青帘舫，南山白玉珂。","未能同一醉，离别思如何。"]},{"t":"送李司务思善二首 其二","f":"五言律诗","c":["苏门形胜地，往岁忆经过。","书院青山近，仙潭赤鲤多。","月中攀古树，雪里并游珂。","六载重携手，清尊柰尔何。"]},{"t":"送殷近夫谢病归寿张二首 其一","f":"五言律诗","c":["论交方恨晚，为别更匆匆。","风雨深期阻，山川幽恨同。","杏田淄水北，草阁汶阳东。","乡路元相近，清宵有梦通。"]},{"t":"送殷近夫谢病归寿张二首 其二","f":"五言律诗","c":["并居城下陌，经岁往来疏。","薄宦惟多病，穷愁有著书。","春山怀紫蕨，夕浦怅红蕖。","去去仙踪渺，何人伴索居。"]},{"t":"送徐德章乃翁","f":"五言律诗","c":["春看燕市花，秋返晋陵槎。","水树侵沙阔，江云隐驿斜。","梦依南国近，书寄北关赊。","坐惜薇郎苦，遥心附海霞。"]},{"t":"送于时宜","f":"五言律诗","c":["行子对新月，临堂酣且歌。","客衣寒未减，乡梦日应多。","鲁甸封春草，淮川渺夕波。","芳音托回雁，迢递柰情何。"]},{"t":"留别王生","f":"五言律诗","c":["天际阴风起，浮云似马行。","飞扬亦何意，离别秪关情。","古岸垂杨合，长河暮色清。","何时画舸背，樽酒说平生。"]},{"t":"送王演之二首 其一","f":"五言律诗","c":["送远临河涘，苍苍夕景微。","云山望不极，书札到应稀。","碛暗风沙起，春长旅雁归。","秦关百二阻，何处换征衣。"]},{"t":"送王演之二首 其二","f":"五言律诗","c":["驱车度宛洛，归路及春深。","杳杳还家梦，悠悠去国心。","青山临古渡，白日下丰林。","憔悴逢渔父，应为泽畔吟。"]},{"t":"送矩庵中丞","f":"五言律诗","c":["荆楚连年旱，今冬雨雪频。","膏融厚土彻，绿迸早禾新。","烽火千山息，讴歌万室春。","中丞调燮手，争道捷如神。"]},{"t":"别伯玉","f":"五言律诗","c":["君行不相见，卧病对春风。","世事浮沉外，交亲感慨中。","古台燕郭暮，流水晋祠空。","他日歌招隐，青山有桂丛。"]},{"t":"送友","f":"五言律诗","c":["十里黄冈道，萋萋露草繁。","青骊将客子，白日过乡园。","水国春先到，云程凤独骞。","行看鲁儒化，流泽被元元。"]},{"t":"赠别宁子","f":"五言律诗","c":["风度与桓典，勋劳更伏波。","明珠腾谤巧，骢马避人多。","白日就长道，清秋凌大河。","非关燕赵别，相送一悲歌。"]},{"t":"送刘希尹入高邑省亲","f":"五言律诗","c":["朝夕梦亲颜，驱车西出关。","青云深魏阙，白日照恒山。","麦秀城池古，人居井邑閒。","秋风扇枕暇，璧水迟君还。"]},{"t":"送伯川子归吴二首 其一","f":"五言律诗","c":["东门嘶马去，幽志几人同。","问寝归吴苑，含香别汉宫。","关山双宝铗，江海一秋蓬。","欲觅南州信，时看西北风。"]},{"t":"送伯川子归吴二首 其二","f":"五言律诗","c":["旧国江村外，清川绕舍流。","空闻赋招隐，不得泛同舟。","雨暗胶山寺，花明爱日楼。","遥怜相忆处，落叶蓟门秋。"]},{"t":"送陶良伯使鲁府","f":"五言律诗","c":["天马玉花骢，骑来天厩中。","言经汶阳道，却过鲁王宫。","岱岳浮云外，蓬莱碧海东。","飘飘鸾鹤侣，仙驾与谁同。"]},{"t":"送杨纯夫","f":"五言律诗","c":["天府通新籍，毗陵返故居。","三春辞北阙，几日过南徐。","岸柳阴阴接，汀花冉冉疏。","江流日东下，何处觅双鱼。"]},{"t":"送赵体仁侍御改官","f":"五言律诗","c":["问子今何适，时危路且艰。","豺狼潜未及，骢马去难攀。","暝野云藏日，秋林水接湾。","病夫门不出，心度万重山。"]},{"t":"七夕夜雨送父回家感而有作","f":"五言律诗","c":["感怀逢七夕，况是别翁时。","天上夫妻会，人间父子离。","梦疑青鸟下，心逐白云驰。","几阵芭蕉雨，萧然鬓欲丝。"]},{"t":"送张仲齐侍御还京二首 其一","f":"五言律诗","c":["上国埋轮后，东山揽辔初。","世方惊豸角，吾已识龙颅。","古柏凌苍汉，清冰照玉壶。","千秋桓典驾，驱逐有人无。"]},{"t":"送张仲齐侍御还京二首 其二","f":"五言律诗","c":["绣斧明霜日，川原指顾中。","才真堪作雨，名不愧观风。","狡兔移山窟，玄狐隐棘丛。","城隅一片石，他日比羊公。"]},{"t":"送张广汉中丞观军留都二首 其一","f":"五言律诗","c":["闻说狼山下，江波带血流。","中原初息战，诸将各封侯。","草绿西兴渡，云生北固楼。","经过吊陈迹，春日暂停舟。"]},{"t":"送张广汉中丞观军留都二首 其二","f":"五言律诗","c":["二月金陵道，中丞拥节还。","日光摇组甲，春色映江关。","国壮军容整，时平武略閒。","坐看龙虎气，长绕凤凰山。"]},{"t":"送陈国充内弟赴京师卒业","f":"五言律诗","c":["千里携书剑，观光入上京。","外亲无我厚，宅相有君成。","细雨官河暗，垂杨客路平。","承家仲氏在，休恋倚门情。"]},{"t":"送韩石泉赴德州兑运","f":"五言律诗","c":["细雨空城暮，游云散薄阴。","落花春晚色，芳草病馀心。","梦接官曹近，秋生国计深。","林中与水次，谁伴独行吟。"]},{"t":"留别柴子","f":"五言律诗","c":["相忆恨长道，相逢惊白头。","又为千里别，还作几年愁。","故旧天涯少，勋名世上浮。","不堪风雨夜，虚馆对新秋。"]},{"t":"留别张西盘大参二首 其一","f":"五言律诗","c":["苦恋三秋别，还为十日留。","江湖宋玉感，风雨杜陵愁。","坠叶鸣沙岸，寒云抱驿楼。","河梁阻携手，谁与赋同舟。"]},{"t":"赠张生下第还金齿三章 其一","f":"五言律诗","c":["逆旅嗟同病，相逢罢举杯。","别期惊岁月，壮志感风雷。","路险三湘隔，心遥一雁催。","可怜苏季子，还着敝裘回。"]},{"t":"赠张生下第还金齿三章 其二","f":"五言律诗","c":["北风吹独骑，万里向西南。","沅水三秋雨，偏桥十月岚。","藓碑怀蜀相，花笔梦江淹。","好把山中屋，重题扪虱庵。"]},{"t":"赠张生下第还金齿三章 其三","f":"五言律诗","c":["闻道栖迟地，苔香涧户幽。","岭猿相旦暮，山月自春秋。","诗画称三绝，图书富九流。","秪应嵇阮辈，与尔得同游。"]},{"t":"送王子兵备江西二首 其一","f":"五言律诗","c":["旧隐辞函谷，新章出汉闱。","碧山留岂得，芳草怨相违。","简拔皇心注，升沉士论归。","传闻拜恩日，犹著赏功衣。"]},{"t":"送王子兵备江西二首 其二","f":"五言律诗","c":["盖拂匡庐过，帆飞蠡泽深。","三秋持斧日，万里渡江心。","虎豹潜移窟，牛羊广出林。","秪应台柏下，端坐听鸣禽。"]},{"t":"送翟给事廷献册封周世子还朝兼赴昌邑省觐三首 其一","f":"五言律诗","c":["册命临中土，恩华接上台。","雪明朱閤丽，风引翠帘开。","汉使鸣环入，王孙露冕来。","星槎曙袅袅，欣傍早春回。"]},{"t":"送翟给事廷献册封周世子还朝兼赴昌邑省觐三首 其二","f":"五言律诗","c":["登高逢岁晚，把酒怅多违。","塔日霜逾静，岩花雪且肥。","家从东海过，天向北辰归。","可道亲心悦，宫袍是舞衣。"]},{"t":"送翟给事廷献册封周世子还朝兼赴昌邑省觐三首 其三","f":"五言律诗","c":["谏客刘栖楚，词人陆务观。","舌存应不虑，盟在可须寒。","赋颂名天下，封章草夜阑。","稿成须寄我，归向鲁门看。"]},{"t":"送杨希颜省墓还闻喜兼柬秦长史","f":"五言律诗","c":["剑装喧鼓吹，春日过乡闾。","梦绕松楸远，心伤雨露馀。","里门妨跃马，宫锦焕飞鱼。","若见秦淮海，应传寄别书。"]},{"t":"送杨文绅司训玉田","f":"五言律诗","c":["东郭渔阳路，南风几日程。","客毡春草色，僧寺晚钟声。","山认盘龙状，州传种玉名。","关西旧衣钵，留取付诸生。"]},{"t":"送王景旸长史还周府","f":"五言律诗","c":["驷马薰风里，中州路不赊。","雨深梁苑竹，春老汴宫花。","亲榻分羹美，玉筵设醴嘉。","五云回首地，不似贾长沙。"]},{"t":"送杨伯玉子南归","f":"五言律诗","c":["孤舟风雨凉，江客下江乡。","岁月吟边晚，烟霞梦里长。","钓溪开藓石，书架拂芸香。","霜落南垓冷，何人共采芳。"]},{"t":"送周司业祭扫还临海二首 其一","f":"五言律诗","c":["客梦惊霜露，乡程入渺冥。","地连霞峤赤，天接海门青。","涧藻充新鼎，碑苔蚀旧铭。","秋墟满狐兔，何处筑思亭。"]},{"t":"送周司业祭扫还临海二首 其二","f":"五言律诗","c":["赤阑桥上路，千载一青衫。","家说编修里，人惊乐正衔。","听泉过万竹，看月步双岩。","寂寞成均地，春风早挂帆。"]},{"t":"送匡敬夫按贵州","f":"五言律诗","c":["岁晚神京别，何时到鬼方。","雪迷山驿冷，云接海关长。","去住新骢马，封题旧皂囊。","遥怀征战地，几处有耕桑。"]},{"t":"送赵叔鸣监税德州二首 其一","f":"五言律诗","c":["萧萧征马嘶，送客过前溪。","故里别来久，家书空复题。","青山鬲津道，平楚卫河堤。","它夜幽寻处，应知梦不迷。"]},{"t":"送赵叔鸣监税德州二首 其二","f":"五言律诗","c":["东赴海陵仓，移家别帝乡。","政繁输转地，官古度支郎。","问寝椿庭近，回舟蓼岸香。","秋来客愁少，风景似维扬。"]},{"t":"送董舅氏","f":"五言律诗","c":["暑雨晓初晴，山泉落涧清。","一杯燕市酒，千载渭阳情。","陇月牵遥梦，江花伴独行。","乱蝉无意绪，争向别时鸣。"]},{"t":"东阿留别无涯孟子","f":"五言律诗","c":["逆旅相逢地，春残花事稀。","同怜在远道，且复换征衣。","碧草连村暗，青山四郭围。","欲旋归去马，还逐使君归。"]},{"t":"送郑雪斋秋官归闽中","f":"五言律诗","c":["识面沉忧里，重逢旅病间。","应缘著书癖，且作泛舟还。","雨色含青柳，江流绕碧山。","东门一尊酒，咫尺杳难攀。"]},{"t":"送客","f":"五言律诗","c":["怪尔湖南使，风江晚系舟。","遥经十载别，刚得寸时留。","素月明寒浦，苍山隐暮流。","水鸥嗟未及，双泛寡离忧。"]},{"t":"别周子贤佥宪","f":"五言律诗","c":["身是外台佐，心蟠中秘书。","杜陵元自许，桓典或能如。","梦结三湘外，神交十载馀。","同舟忽判袂，愁绝广川墟。"]},{"t":"送吴学正之留都武学","f":"五言律诗","c":["振铎敷文教，迁阶得武庠。","讲筵环胄子，官舍接宫墙。","树隐台城古，江连石埭长。","相期共临眺，嘉候及重阳。"]},{"t":"送别菊泉胡子","f":"五言律诗","c":["寒声下木杪，送子一酸辛。","白日川原净，高秋鼓角振。","来看南苑雪，归忆上都春。","懒听阳乌发，嗷嗷青石闉。"]},{"t":"广川舟中与东桥酌别次韵三首 其一","f":"五言律诗","c":["汴上一为别，漂摇十二秋。","那期卫川涘，得并李膺舟。","月映青山出，波涵碧树流。","接宵欢达曙，不为酒尊留。"]},{"t":"广川舟中与东桥酌别次韵三首 其二","f":"五言律诗","c":["共脱风前帽，还披月下襟。","乾坤万里别，江海十年心。","越鸟枝难共，湘鱼帛易沉。","相逢畏相失，延滞绿溪阴。"]},{"t":"广川舟中与东桥酌别次韵三首 其三","f":"五言律诗","c":["愧我蒹葭质，倚君琼树姿。","遥怜共飘泊，且复笑栖迟。","秀句推先达，高言戒独危。","江蓠照雪月，秋谷有深期。"]},{"t":"卧疾柬别孙性甫二首 其一","f":"五言律诗","c":["杳杳关河客，盈盈一水间。","那因各抱病，遂阻共开颜。","雨入青帘细，云移碧树閒。","含情送遥瞩，时见瞑鸦还。"]},{"t":"卧疾柬别孙性甫二首 其二","f":"五言律诗","c":["旧典司番礼，新乘郡守车。","问名俱不沗，迁秩定何如。","父老看行盖，君王想谏书。","徵黄会有诏，早晚下宸居。"]},{"t":"张秋官元德席上留别","f":"五言律诗","c":["春日江陵去，烟花万里途。","山川留故郢，舟楫带三吴。","树影湘流转，猿声峡月孤。","郡楼登望夕，天北是皇都。"]},{"t":"送曾世亭兵备赴蜀","f":"五言律诗","c":["闻道霜台使，亲承岳牧恩。","山川增气色，草木藉生存。","拂暑辞东郡，先秋过楚门。","江皋有芳杜，作意待王孙。"]},{"t":"鹦鹉","f":"五言律诗","c":["珍鸟来清夏，芙蕖避绿衣。","苦遭鸦并嚇，羞与燕同飞。","整翮身仍阻，能言意且违。","何当即开锁，放尔陇山归。"]},{"t":"东坞为李户部贡卿赋","f":"五言律诗","c":["旧坞浓花发，新春旅梦悬。","醉吟朝雨后，醒坐夕阳前。","摩诘才堪比，随州句可怜。","山禽傍精舍，来往正翩翩。"]},{"t":"雪庵","f":"五言律诗","c":["大雪乾坤闭，开窗且静观。","偶然同卲子，不是学袁安。","数在梅花得，春从太极看。","凭将画前易，一问灞桥鞍。"]},{"t":"昌平馆","f":"五言律诗","c":["寒食烟花暮，伤归复旅游。","芳尊不相对，华馆坐悠悠。","月细光疑晦，山空响似秋。","老亲垂短发，计日向西州。"]},{"t":"公馆即事呈彦卿","f":"五言律诗","c":["赤日下庭角，白云生昼阴。","弥因吏喧屏，转觉道情深。","树荫依邻借，虫声隔水寻。","回骖淹薄瞑，相迟在同心。"]},{"t":"李月辉方丈二首 其一","f":"五言律诗","c":["鸡犬不闻音，仙家巷陌深。","洞箫吹赤玉，丹灶化黄金。","庭迥秋花寂，阶寒夕雨沉。","愿传方外秘，勿使岁华侵。"]},{"t":"李月辉方丈二首 其二","f":"五言律诗","c":["秋林积雨晦，晏坐失朝曛。","地似通勾漏，人疑是少君。","依依归洞鹤，冉冉度窗云。","预恐重来日，花源杳不分。"]},{"t":"雨中憩双泉寺","f":"五言律诗","c":["野寺临官路，山门俯近郊。","閤虚钟梵寂，院静薜萝交。","密雨沉蛛网，閒云拥鹤巢。","故人诗在壁，惆怅隔衡茅。"]},{"t":"十六日再至寺","f":"五言律诗","c":["十日重来此，登临兴转幽。","老僧烹石耳，留客坐山头。","阴洞生云雾，阳坡散马牛。","翻嗟出城晚，不值菊花秋。"]},{"t":"静海寺","f":"五言律诗","c":["窈窕城连寺，巉岩石抱亭。","洞虚云气白，厓断草痕青。","宝匣封宸翰，珠花络藏经。","回翔不觉晚，归马傍春星。"]},{"t":"伦上人院晚坐次白湖韵","f":"五言律诗","c":["过雨禅房寂，松筠一径遮。","梵筵青琐佩，香灶碧山茶。","鹤静欹寒水，僧閒数落花。","诗人类迂僻，乘兴即为家。"]},{"t":"九日登千佛山寺五首 其一","f":"五言律诗","c":["南山空崒嵂，野老倦登临。","城郭千年迹，云霄万里心。","夕阴涵积水，风叶下长林。","短发新来白，黄花不可簪。"]},{"t":"九日登千佛山寺五首 其二","f":"五言律诗","c":["亭午客先集，怜予迟出城。","吏当青塔候，僧下碧山迎。","弈谱传新势，骚坛讲旧盟。","洞泉秋不冷，好共濯尘缨。"]},{"t":"九日登千佛山寺五首 其三","f":"五言律诗","c":["石壁青含雨，松台迥入烟。","闷随天上客，閒访洞中仙。","菊采芬芳蕊，诗留酩酊篇。","重逢倘万一，携手话兹年。"]},{"t":"九日登千佛山寺五首 其四","f":"五言律诗","c":["窈窈寺门敞，苍苍山径微。","风轻不落帽，云近忽凝衣。","背领丹枫直，垂岩紫菊肥。","晚途喧葆吹，舆醉出林霏。"]},{"t":"九日登千佛山寺五首 其五","f":"五言律诗","c":["半岩风且急，冲雨下山难。","醉后还骑马，狂来不正冠。","阴阴南国暝，淰淰暮秋寒。","预想茅檐际，迎门稚子欢。"]},{"t":"十月六日游千佛山寺","f":"五言律诗","c":["亭午登山寺，淹留夕未归。","凉风起高树，落叶满僧衣。","城郭寒烟聚，楼台暮景微。","京华十年客，愁绝赏心违。"]},{"t":"入寺","f":"五言律诗","c":["共邀黄鹤侣，来问野狐禅。","日出山中寺，风鸣树里泉。","落花空色相，啼鸟伴幽玄。","莫叩轮回事，吾生自有缘。"]},{"t":"出寺","f":"五言律诗","c":["鸡鸣春日晓，钟落上方幽。","树湿云犹住，山空翠欲流。","酒床随客去，诗草付僧收。","虚羡岩栖子，尘镳不可留。"]},{"t":"寿孙万户母","f":"五言律诗","c":["岁岁称觞处，将军此旧庭。","玉函开宠诰，纱幔叩遗经。","径茁宜男草，檐垂婺女星。","白头真入画，长对晓山青。"]},{"t":"寿程良用父","f":"五言律诗","c":["雅尚陶洪景，风流顾辟疆。","名传天北极，家住水中央。","晚日明花宴，春云护草堂。","髯郎归节美，衣绣出明光。"]},{"t":"寿文孔旸","f":"五言律诗","c":["寿域开梁苑，韶华逼艳辰。","月临春馆静，花簇夜筵新。","鹤信传西母，鸾箫乐上宾。","转怜多病客，高枕独怀人。"]},{"t":"何圌樵寿五月十五日","f":"五言律诗","c":["胜地三茅北，嘉辰九夏中。","寿尊浮海月，樵唱落天风。","席近红榴艳，庭深绿桂丛。","遥怜烂柯者，仙籍会相通。"]},{"t":"题秦国声为乃翁卑牧寿卷二首 其一","f":"五言律诗","c":["江门閒起坐，白发照秋山。","花拥宜人佩，兰分稚子班。","天恩来锁闼，星信报银湾。","笑看东林鹤，传书海上还。"]},{"t":"题秦国声为乃翁卑牧寿卷二首 其二","f":"五言律诗","c":["池馆山中旧，风光画里新。","涧松同雨露，江草自冬春。","犬吠当林坞，花明隔水滨。","遥疑姓秦者，莫是武陵人。"]},{"t":"寿康对山母","f":"五言律诗","c":["垂柳荫香车，西园春雨馀。","寿多从入老，身健欲凌虚。","紫凤云中诰，青鸾海上书。","近臣兼色养，何必赋閒居。"]},{"t":"寿高给事乃翁","f":"五言律诗","c":["老境真熙洽，山中白日长。","鹤巢松树古，花近寿筵香。","几杖荣朝典，讴歌乐岁康。","郎君青琐贵，归路满恩光。"]},{"t":"挽无钖吴翁","f":"古风","c":["锡山春日墓，闻说?乡贤。","露叶迷蒿里，风笳惨木田。","名高悬榻后，事定盖棺前。","陇上清明月，年年哭杜鹃。"]},{"t":"王宪司挽章","f":"五言律诗","c":["桓典声名久，相如词赋稀。","世方骢马避，身已茂陵归。","白露凋原草，流尘集穗帏。","伤心庭下鹤，时向月中飞。"]},{"t":"杨介夫丧母","f":"五言律诗","c":["楚客抱沉哀，孤舟天际回。","恩馀五鼎食，人闭九泉台。","古壁机丝断，残灯穗帐开。","慈魂犹恋子，夜夜梦中来。"]},{"t":"挽董天粹母","f":"五言律诗","c":["板舆游乐地，经晋复经燕。","岂料言归日，翻成永别年。","堂虚春草合，机冷夜灯悬。","欲问三迁事，慈容隔九泉。"]},{"t":"挽谢都宪二首 其一","f":"五言律诗","c":["太守驱车日，中丞拥节年。","化行江郡美，名在蜀人传。","漆吏悲移壑，殷王惜济川。","陇门双石表，何处立秋烟。"]},{"t":"挽谢都宪二首 其二","f":"五言律诗","c":["人间七十载，地下几千秋。","无复青山到，真同逝水流。","乱云笼閤迥，啼鸟殡宫幽。","欲采蘋花奠，闽江远帝州。"]},{"t":"挽张思绍乃翁","f":"五言律诗","c":["归老身犹健，游仙梦已侵。","盐司官誉在，豸服主恩深。","迢递碧山路，凄凉嘉树阴。","秋风渡泸水，客子正愁心。"]},{"t":"刘惟馨二亲哀册二首 其一","f":"五言律诗","c":["徂谢感流光，悲凉十四霜。","箧中无谏草，身后有封章。","遗曲传巴里，清风满蜀乡。","凤凰原上木，愁色日苍苍。"]},{"t":"刘惟馨二亲哀册二首 其二","f":"五言律诗","c":["相如驷马荣，毛义悦亲情。","讵料终天别，惟争一日程。","机堂穗帷捲，隧户漆灯明。","欲识归人恨，江猿夜夜声。"]},{"t":"挽海钓翁","f":"五言律诗","c":["山海关头月，春来几度圆。","杖藜无起日，华表有归年。","寂历远游道，凄凉孤愤篇。","朱云不可见，留槛汉庭前。"]},{"t":"萧医士挽词","f":"五言律诗","c":["术妙轩岐上，年垂耋耄间。","烟霞成癖性，松柏是容颜。","济物心常在，游仙梦不还。","钱塘江口月，长照玉泉山。"]},{"t":"挽王宪副父母二首 其一","f":"五言律诗","c":["露白秋郊迥，风高宰木凄。","深嗟墓门道，犹有聘君题。","隐迹庞公并，诗名魏野齐。","孝魂招不返，应只在辽西。"]},{"t":"挽王宪副父母二首 其二","f":"五言律诗","c":["白首来官舍，丹旌返旧山。","有怀空色养，无日见生还。","暮草春回碧，机堂昼掩关。","天涯有游子，肠断舞衣斑。"]},{"t":"题王臣指挥母挽册","f":"五言律诗","c":["将军怀母处，堂屋对南山。","香断氍毹冷，机空络纬閒。","暮花愁里色，春酒梦中颜。","一掬长淮泪，随波去不还。"]},{"t":"挽同年程御史良用次见素韵二首 其一","f":"五言律诗","c":["有志经邦国，无忧及子孙。","凄凉柱下史，慷慨殿中言。","发已生离白，声还死别吞。","空山一杯酒，何日奠忠魂。"]},{"t":"挽同年程御史良用次见素韵二首 其二","f":"五言律诗","c":["新安新庙起，闻子入乡贤。","古墓青山外，秋风老泪前。","乾坤英爽聚，日月大名悬。","谁续少陵语，载歌骢马篇。"]},{"t":"哭儿羽","f":"五言律诗","c":["阿羽生存日，人呼圣小儿。","虚疑渥洼种，实有凤麟姿。","学步先遵礼，能言即赋诗。","悼渠怜子夏，休讶入官迟。"]},{"t":"湖上忆亡儿羽","f":"五言律诗","c":["往岁春湖曲，尝携稚子游。","花迎玉肤笑，云傍綵衣流。","隔水时穿竹，看鱼数探舟。","伤心独来日，烟月暮含愁。"]},{"t":"登王丈墓","f":"五言律诗","c":["磊落王夫子，消沉岁月深。","墓田馀数柳，书屋有孤琴。","挂剑千秋恨，通家百世心。","暮山荒草际，登拜一沾襟。"]},{"t":"亡弟赋改葬述哀","f":"五言律诗","c":["葬汝已六载，那期重抚棺。","壮心原不死，遗骨久应寒。","石室灵仪在，铭旌粉字残。","一为同气感，双涕夕汍澜。"]},{"t":"上王氏妹墓","f":"五言律诗","c":["王郎呼不起，吾妹亦泉台。","白日山头下，悲风树里来。","有亲差可慰，无子更堪哀。","岁岁荒坟土，何人奠一杯。"]},{"t":"仲冬望日先陇述哀","f":"五言律诗","c":["矻矻衔石鸟，愔愔栖月乌。","云霄双翼倦，天地此身孤。","雪野兼愁远，风杨著泪枯。","一杯残腊酒，知到九原无。"]},{"t":"东村暮归经罗侍御墓缅怀知旧恻然兴哀兼呈同志二首 其一","f":"五言律诗","c":["云日苍茫合，东郊暮雪时。","古台斜落影，青嶂迥含姿。","泽静龙蛇远，山寒雁鹜饥。","亲交半丘墓，愁诵七哀诗。"]},{"t":"东村暮归经罗侍御墓缅怀知旧恻然兴哀兼呈同志二首 其二","f":"五言律诗","c":["野色拥归轩，遥遥登古原。","田乌啄素雪，山鸟下黄昏。","近郭寒收市，荒祠静掩门。","吾行有佳赏，思与故人论。"]},{"t":"过王履轩墓","f":"五言律诗","c":["郁郁将军墓，苍苍松桧林。","断猿千古梦，归鹤九原心。","地胜河流抱，门閒草色侵。","承家有儿子，文史富缨簪。"]},{"t":"幽寂","f":"五言律诗","c":["幽寂卧蓬户，凄凉怀旧吟。","莺啼非故国，草色乱春心。","落日黄云暮，阴风碧海深。","嗷嗷北来雁，二月有归音。"]},{"t":"对月感怀","f":"五言律诗","c":["惆怅东篱下，西风酒一壶。","物随秋渐老，人与月同孤。","幻梦疑蕉鹿，尘踪笑网蛛。","寒蛩不解意，唧唧向青芜。"]},{"t":"送王廷珍分教东明","f":"五言律诗","c":["春日东明去，西斋教铎分。","毡随郑老座，经授伏生文。","水暖鱼腾藻，泥融燕啄芹。","有怀如我及，看雨赋停云。"]},{"t":"方献夫读书山寺","f":"五言律诗","c":["闻君读书处，孤榻寄禅林。","日抱左氏癖，时为梁甫吟。","开窗千嶂出，隔巷一灯深。","独有花龛月，盈盈鉴苦心。"]},{"t":"雨宿姚村二首 其一","f":"五言律诗","c":["旧陇东城外，新坟更在东。","川原相近接，灵爽合潜通。","碧草生秋石，青杨袅夜风。","茂陵山下路，来往恨无穷。"]},{"t":"雨宿姚村二首 其二","f":"五言律诗","c":["野径来人绝，村居夜寂寥。","牖灯方闪闪，庭雨更潇潇。","墓土空亲筑，精魂不可招。","百年孤子恨，天地与同销。"]},{"t":"闻三平菊酒初熟诗以调之","f":"五言律诗","c":["爱酒苦无酒，避狂翻蹈狂。","闻君新酿熟，色胜菊花黄。","月夜楼阴静，霜天海气凉。","何当骑马去，饱挹瓮头香。"]},{"t":"故山道中二首 其一","f":"五言律诗","c":["此山青可爱，岩嶂绕云松。","暂息野中驾，弥耽尘外踪。","石桥今古在，香客往来逢。","落日谷风起，依稀闻瞑钟。"]},{"t":"故山道中二首 其二","f":"五言律诗","c":["素盖凌风转，飘飘度石梁。","田家始晡食，村店已斜阳。","红忆山椒熟，青怜陇麦长。","郊行亦何事，能遣世情忘。"]},{"t":"辛巳元日止酒","f":"五言律诗","c":["草阁逢元日，悠悠一病身。","碧山虚对雪，青柳自含春。","罢接屠苏盏，长抛漉酒巾。","相过见渔父，应笑独醒人。"]},{"t":"望雨","f":"五言律诗","c":["倚杖柴门底，云峰引兴长。","验霞从曙色，瞻雨过昏黄。","柱础虚含润，盆荷实抱香。","空檐百尺溜，何日听浪浪。"]},{"t":"忧旱二首 其一","f":"五言律诗","c":["欲叩苍天意，悠悠默且玄。","树焦真可爨，井渴故须穿。","碧汉空秋水，钟山静晓烟。","九重宽恤诏，何日下荒田。"]},{"t":"忧旱二首 其二","f":"五言律诗","c":["亢阳厚土裂，兹事莫言无。","旱貉久为怪，惰龙真恼吾。","未沾三伏雨，敢说九秋租。","珍重云霓望，苍生待一苏。"]},{"t":"坐雨","f":"五言律诗","c":["密云蒸短夜，繁雨下清朝。","不救中田麦，犹沾晚岁苗。","度窗才浙浙，浮槛更萧萧。","咫尺苏端舍，冲泥未可招。"]},{"t":"八日喜晴","f":"五言律诗","c":["海门晴日吐，春水坐来添。","喜入三农望，丰归五谷占。","野莺啼秀木，江草映虚帘。","我病生嫌酒，深杯且一拈。"]},{"t":"过北川周子庄","f":"五言律诗","c":["借问平阳守，泉庄今若何。","树稀鸣鸟散，花乱早蜂多。","酒坫封苔藓，渔罾罥薜萝。","凄凉世交子，忍泪一相过。"]},{"t":"正月十七日先大人寿辰","f":"五言律诗","c":["此日吾亲寿，常年乐事多。","夜堂歌窈窕，春綵戏婆娑。","永恨重泉隔，深惊六载过。","风前酹卮酒，肠断楚川波。"]},{"t":"过王生庐墓","f":"五言律诗","c":["赤日东郊午，言过孝子庐。","草衣惟短杖，土屋有藏书。","蛛网苔侵户，蜗墙雨溜渠。","闵祠看咫尺，比德定何如。"]},{"t":"问信","f":"五言律诗","c":["问信陈州盗，将军有捷书。","真成机上肉，岂虑釜中鱼。","杀气东连颍，烽烟北近徐。","招招淮口楫，将发故踌躇。"]},{"t":"盗贼","f":"五言律诗","c":["盗贼还奔突，传闻过白洋。","关河苦迢递，云月复苍茫。","贾客回江舸，居人竞野航。","鸡鸣戒同伴，或恐犯垂堂。"]},{"t":"过姚村旧业村有先君子遗陇","f":"五言律诗","c":["里巷纷仍在，邻翁半不存。","午鸡喧井落，寒犬卧衡门。","侧宇天光入，巍阡雾色昏。","百年桑梓地，回首一伤魂。"]},{"t":"忽报二首 其一","f":"五言律诗","c":["忽报杨开府，新传羽檄过。","未须忧赤县，且复守黄河。","去马定看疾，来舟遂不多。","飘蓬愧生理，终日傍干戈。"]},{"t":"忽报二首 其二","f":"五言律诗","c":["岂料朝天使，翻为避地人。","去留难与决，传报恐非真。","碧树花争蕊，清江水自春。","庙堂嘉靖日，州郡转风尘。"]},{"t":"龙洞山杂咏二首 其一","f":"五言律诗","c":["寺绕层峰入，溪通曲涧开。","八年千里梦，七日两回来。","古壁流烟色，荒蹊叠草莱。","登高赋摇落，惭愧宋生才。"]},{"t":"龙洞山杂咏二首 其二","f":"五言律诗","c":["出郭始朝饭，入山闻瞑钟。","自怜衰病久，敢恨仆夫慵。","立马看群岫，开尊对两松。","谁能回白日，眼眺且从容。"]},{"t":"丁字口北","f":"五言律诗","c":["海口潮初落，片帆秋正堪。","斜阳飞鸟度，微雨断云含。","恋阙心驰北，留人风自南。","一声渔篴响，凫雁起江潭。"]},{"t":"鄂渚","f":"五言律诗","c":["鄂渚维舟楫，登高览洞庭。","地连秋水白，天入暮山青。","望阙瞻星斗，怀人感鹡鸰。","渔箫向夕起，呜咽不堪听。"]},{"t":"暮行","f":"五言律诗","c":["野色苍茫合，宵征问路频。","马蹄经藓滑，萤火度溪新。","乡国今何许，家书动隔春。","远村灯烛处，箫鼓赛田神。"]},{"t":"逐客","f":"五言律诗","c":["逐客去已远，相思空尔哀。","不闻宣室召，徒抱贾生才。","野竹侵书幔，山莺进酒杯。","梁园亲识满，今雨几人来。"]},{"t":"野风","f":"五言律诗","c":["野风吹荻苇，寂寂楚江秋。","水气寒侵幌，涛声夜撼舟。","古今双社鸟，天地一沙鸥。","欲作怀湘赋，官程不可留。"]},{"t":"泛江","f":"五言律诗","c":["汎舟成小酌，半醉倚篷看。","烽火偏西接，关山直北寒。","渚花春漠漠，江日暮团团。","谁识荆南守，思乡欲挂冠。"]},{"t":"归自北村","f":"五言律诗","c":["款款野中话，依依川上情。","雨昏沙径色，风起暮林声。","临水仆夫望，呼予童子名。","柴门露远火，回策兴弥清。"]},{"t":"过北渚庄二首 其一","f":"五言律诗","c":["野店长渠绕，郊扉昼不开。","茅堂荫榆柳，沙路上莓苔。","白鸟晴飞疾，玄禅夕奏哀。","主人城市里，经岁几曾来。"]},{"t":"过北渚庄二首 其二","f":"五言律诗","c":["渚老有高趣，未衰先弃官。","心犹壮夫勇，身且布衣寒。","雪里中宵坐，灯前细字看。","不知东海上，何日起垂竿。"]},{"t":"再过北川别业","f":"五言律诗","c":["负郭稻千顷，青青遥入云。","儿孙不解守，宾客自争分。","剡曲舟慵泛，山阳笛忍闻。","伤心碧堤柳，犹映白鸥群。"]},{"t":"题白泉王子壁","f":"五言律诗","c":["吟兴复不浅，村中无酒家。","圃云深映竹，墟日半笼花。","石栅啼黄鸟，溪泉拥白沙。","昼眠兼夕坐，非为惜年华。"]},{"t":"卜山居成有作","f":"五言律诗","c":["久定华山约，今来始卜居。","梦游曾屡到，心赏复何如。","圃巷环高柳，渊泉抱古墟。","从兹簪与绂，当有绝交书。"]},{"t":"过湘王故宫","f":"五言律诗","c":["旧日湘王府，凄凉百岁多。","堞荒秋荠上，楼厂夕云过。","废囿穿狐兔，深宫散绮罗。","同行有词客，閒咏黍离歌。"]},{"t":"过故山人园","f":"五言律诗","c":["园囿碧山隅，山人此旧居。","豪华非往昔，冥漠意何如。","古木巢寒鸟，残阳隐废墟。","伤心醉游处，犹有壁间书。"]},{"t":"家豢鹦鹉为狸奴所毙予伤之赋短律二篇书呈同志期有以慰我也 其一","f":"五言律诗","c":["尔本能言鸟，羁栖误此生。","众方怜彩翠，天苦忌聪明。","月下离群思，花间唤婢声。","居然成往迹，留架在前楹。"]},{"t":"家豢鹦鹉为狸奴所毙予伤之赋短律二篇书呈同志期有以慰我也 其二","f":"五言律诗","c":["转架藏身捷，临窗命食娇。","愁来真可掬，魂去竟难招。","露井流音寂，风阶落羽飘。","醉翁元好寝，为尔立清宵。"]},{"t":"石桥驿南观涨","f":"五言律诗","c":["夜雨山水发，奔涛盈涧流。","石梁嗟已断，何处觅方舟。","永路缘朱坂，馀晖映绿畴。","登高西北望，隐隐见昭丘。"]},{"t":"由鱼料驿登岸赴荆门","f":"五言律诗","c":["驱马丽阳界，荆门途不赊。","平田飞野雉，积水乱鸣蛙。","日下西山暝，江悬北斗斜。","荒村逢故老，停盖问桑麻。"]},{"t":"自汉江泛舟过宜城遇风雨大作","f":"五言律诗","c":["短棹骛洪河，川行忧畏多。","转怜时役苦，无奈旅程何。","雾黑江龙斗，云腥岸虎过。","黄昏投古驿，从此顺风波。"]},{"t":"自岘山趋赴襄城不及门遂宿汉江驿","f":"五言律诗","c":["黄昏岘山曲，征马倦跻攀。","雨过苍林外，虫鸣废井间。","断崖成聚落，深巷隔尘寰。","古驿悬灯候，重门未上关。"]},{"t":"登仲宣楼次韵陈矩庵中丞 其一","f":"五言律诗","c":["岧岧南郡楼，到郡此重游。","岛没云中树，天浮海上沤。","旌旗连戍色，鼓角动边愁。","万里看西北，苍茫见帝州。"]},{"t":"登仲宣楼次韵陈矩庵中丞 其二","f":"五言律诗","c":["江郡敞云楼，东南据上游。","日华浮野雪，霞彩散川沤。","俯仰悲千古，登临起四愁。","王师神且武，何日靖西州。"]},{"t":"荅西桥大复二君 其一","f":"五言律诗","c":["忆在中州日，曾传上苑歌。","暮云千里隔，春草四年过。","汉殿仍金马，秦关且玉珂。","报章惭独晚，才力谢羊何。"]},{"t":"荅西桥大复二君 其二","f":"五言律诗","c":["懒性真成癖，哀吟不当歌。","田园自开辟，城市少经过。","雨卧山回枕，春行柳拂珂。","马周头渐白，无日见常何。"]},{"t":"赠刘介夫举人归金乡限韵作","f":"五言律诗","c":["云日昼冥冥，幽人过草亭。","客衣寒映水，归骑晚侵星。","雨外山逾秀，霜前柳正青。","醉翁多晏起，行李暂须停。"]},{"t":"叠羹字韵再别承庵","f":"五言律诗","c":["钓鱼特作羹，载酒出山城。","晓雨阳关恨，春风故国情。","登台怅予独，戏彩羡君行。","忍听碧林外，萧萧归马鸣。"]},{"t":"送客","f":"五言律诗","c":["知君意不浅，近送独绸缪。","文字真吾契，河山且故州。","水云虚映日，风树碧含秋。","岳顶传诗在，谁将片石流。"]},{"t":"送章太守朝觐","f":"七言律诗","c":["十载乡山路不平，年来吾亦羡吾生。","春回麦陇见鹰化，月出花田无犬惊。","湖上野夫真浪迹，济南良守合垂名。","古亭相别恋携手，日暮风烟含远情。"]},{"t":"送王滦江","f":"七言律诗","c":["灯火虚堂绾梦思，月明乌鹊绕栖枝。","真愁远道无书札，不信残冬有别离。","江甸綵舟迎早燕，关山骢马恋芳岐。","情多未有琼瑶赠，醉折风梅傍雪篱。"]},{"t":"登天津拱北楼","f":"七言律诗","c":["古今形胜天津地，晚暮登临春事幽。","冠冕八方通禹贡，河山千里控神州。","风连碣石烟沙黯，日倒扶桑海色流。","老病独悬戎马涕，俯身疑在岳阳楼。"]},{"t":"寄亭溪","f":"七言律诗","c":["梧桐覆井阴阴叶，蟋蟀鸣阶细细音。","中夜有怀孤月迥，九天无梦五云深。","真惭弃置逢时幸，敢负平生许国心。","立马送君还忆远，似闻巫峡气萧森。"]},{"t":"昭君出塞图","f":"七言律诗","c":["帝遣才人出汉宫，远投殊域为和戎。","琵琶晚映娥眉月，觱篥寒吹粉面风。","终夜苦心悬北斗，隔年归信托南鸿。","征鞍倦倚聊成寐，犹在长门女伴中。"]},{"t":"雪中次钱江楼宪副 其一","f":"七言律诗","c":["两岁高堂辍问安，每逢新腊恨漫漫。","身如野鹤真无倚，心似江梅苦抱酸。","衣线细留春草怨，穗灯深掩雪风寒。","他年奉檄堪垂涕，毛义从来不为官。"]},{"t":"雪中次钱江楼宪副 其二","f":"七言律诗","c":["起居深借鹊巢安，著作从教酱瓿漫。","迟暮岁华多客感，清修家世本儒酸。","春潜水市晴烟碧，雪抱山城午日寒。","且欲醉眠歌习隐，不须章表乞辞官。"]},{"t":"再次钱江楼","f":"七言律诗","c":["布被藜床雪卧安，草堂幽迥夜漫漫。","有怀真爱故山好，多兴不辞村酒酸。","冲晓觑林梅恰放，趁暄行径石犹寒。","长镵短褐无人识，白发明时老谏官。"]},{"t":"久雨喜晴","f":"七言律诗","c":["已判冥冥过此年，忽从中夜睹青天。","云移北牗星河近，月上东林树影圆。","游兴不愁村径滑，赏心多为渚花牵。","朝来拟蜡登山屐，见说西峰有谪仙。"]},{"t":"雪中","f":"七言律诗","c":["醉眼看馀密复疏，晓风吹散乱如初。","一尊相对兴不浅，孤鹤伴吟行且馀。","桥滑可须羸蹇度，泥深同感落鸿书。","江梅岸柳俱含冻，六管凭谁借一嘘。"]},{"t":"祷雨","f":"七言律诗","c":["久祈甘雨集灵官，赫赫骄阳势转难。","月驭漫曾离毕宿，雷车空自绕仙坛。","巡檐卜润时看础，望极占云夜倚阑。","迂腐似闻天鉴迩，古来王者必求端。"]},{"t":"除日次蒲汀李少宰韵","f":"七言律诗","c":["建业新春入故年，异乡怀抱各凄然。","三千道路沧江外，五十光阴素发前。","名重正须推北斗，藁成应更续南铨。","邻西咫尺莺迁地，守岁同歌伐木篇。"]},{"t":"元日次蒲汀二首 其一","f":"七言律诗","c":["星纪初回日再元，海风吹雾起晴暾。","五辛遥阻荒坟荐，万里空伤久客魂。","临水稚芳争袅袅，出林幽羽故喧喧。","归田喜卜中宵梦，拟办囊封乞主恩。"]},{"t":"元日次蒲汀二首 其二","f":"七言律诗","c":["柏烟松火万家同，柳径杨堤入暖风。","九陌管弦存旧俗，六朝山水见遗宫。","交亲隔舍追随里，岁序惊心感慨中。","且喜瓮头浮绿蚁，不须囊底觅青铜。"]},{"t":"人日喜晴次蒲汀韵","f":"七言律诗","c":["人日旧京云日丽，钟山龙气郁开祥。","腐儒推枕病忽去，野老占年喜欲狂。","即起户帘通紫燕，早闻宫树啭黄鸯。","多情杜甫缘何事，解道他乡胜故乡。"]},{"t":"次蒲汀二首 其一","f":"七言律诗","c":["春朝飞雪舞风回，谷日中宵起迅雷。","腊后不教滕六出，蛰前那遣阿香来。","深江满浸遗蝗种，厚地潜惊律管灰。","借问化机谁转斡，只应天府近三台。"]},{"t":"次蒲汀二首 其二","f":"七言律诗","c":["石城虎踞九关开，钟阜龙盘亦壮哉。","地保金汤分表里，气通云汉切昭回。","镐京本是文王土，太乙休誇武帝台。","头白词臣窃供奉，两京清秩去还来。"]},{"t":"端午","f":"七言律诗","c":["楼船不近打鱼矶，箫鼓中流听者稀。","遥想紫宸颁制扇，真惭清禁赐宫衣。","池亭映日榴开锦，城郭笼烟柳荡旂。","传有湘江年少过，兰桡应吊屈平归。"]},{"t":"人日有怀白岩侍郎","f":"七言律诗","c":["去年人日题诗处，郑氏茅堂春可怜。","出谷早莺啼恰恰，映风寒竹倚娟娟。","随銮并入青云上，解佩同归素月前。","此日寂寥惊旅食，坐看庭雪抚流年。"]},{"t":"正月十五","f":"七言律诗","c":["城上旌旗闪夕光，城边戈甲俨龙骧。","郊门月上游尘静，辇路春回细草长。","千古再逢周礼乐，十年曾奉舜衣裳。","行宫咫尺天俱远，愁见林鸦接翅翔。"]},{"t":"中秋值雨","f":"七言律诗","c":["冉冉游云护琐闱，胧胧团月映江扉。","停杯已负经年约，倚槛空思万里辉。","花雨广寒真亦假，梦登天柱是邪非。","临风谩有乘槎兴，欲访银河旧织机。"]},{"t":"东村冬日同刘王诸子步归","f":"七言律诗","c":["泱漭空原返照开，杖藜村径暮徘徊。","霜苗迸土纤纤出，风叶辞林宛宛回。","扶病可须重载酒，住家何必更登台。","青鞋布袜沧波岸，白石歌残意转哀。"]},{"t":"至日恭闻车驾入都志喜二首 其一","f":"七言律诗","c":["八骏长驱万里翱，四方周览一心劳。","星杓夜夜随黄幄，云盖时时护赭袍。","朔野旧闻歼冒顿，洪都今见破宸濠。","何人议赏功居首，玉殿承恩醉碧桃。"]},{"t":"至日恭闻车驾入都志喜二首 其二","f":"七言律诗","c":["至日连年帝远征，今年至日喜还京。","登歌想像聆周雅，振旅传呼列汉旌。","皇祚永占千岁历，圣聪明照万方情。","灵台旧职今谁掌，不用书云纪太平。"]},{"t":"立春日","f":"七言律诗","c":["多病逢春笔懒拈，草堂高枕病垂帘。","故人恰送鱼酒至，野老不愁年岁添。","冉冉雪云虚照水，晖晖晴日乍经檐。","衔杯自笑还成醉，吏隐谁能得两兼。"]},{"t":"元日次滦江中丞","f":"七言律诗","c":["伏枕惊看岁又新，卧听街市响蹄轮。","樽无白酒元因病，屋有青山不当贫。","向晚云霞偏弄色，得时梅柳故争春。","闭门可是甘肥遁，懒效东西南北人。"]},{"t":"再次滦江","f":"七言律诗","c":["玉座香烟护衮衣，綵云飞处是皇畿。","中朝地接千官拥，北斗星悬万国依。","波煖御沟春浩荡，日临宫树晓云微。","自怜朱绂淹乡土，不拜青阳入禁扉。"]},{"t":"春日王监察天宇过访留酌二首 其一","f":"七言律诗","c":["豸冠春访薜萝衣，晴日池台燕子飞。","心为感时偏耿耿，话因谈旧转依依。","閒过别院题青竹，却望南山指翠微。","欲问野夫栖隐处，九槐溪上一柴扉。"]},{"t":"春日王监察天宇过访留酌二首 其二","f":"七言律诗","c":["笑我贪书日苦辛，爱君风采是埋轮。","青骢独系垂杨晚，白屋长甘旧业贫。","千里海邦开雨雪，万家山郭转阳春。","回骖却傍黄昏路，萝月纤纤喜近人。"]},{"t":"寒食郊行","f":"七言律诗","c":["来家疃前春可怜，芳郊迟日起晴烟。","柳枝袅袅翠犹弱，花蕊菲菲红且妍。","荒陇岁时还俎豆，短墙儿女正鞦韆。","青年竹马欢游地，华发经过思惘然。"]},{"t":"午日","f":"七言律诗","c":["五月五日正阳辰，四十六年衰病身。","天上风云同际会，水边鱼鸟自相亲。","啸歌独得酒朋喜，疏散屡遭官长嗔。","睡起竹林温雅颂，绿蒲青艾晚撩人。"]},{"t":"中秋述怀","f":"七言律诗","c":["银汉星稀玉宇秋，夜深乘醉倚东楼。","天香不见云中下，槎影空传海上浮。","狂有篇章酬岁月，懒无书信荅交游。","羽衣歌罢蟾光冷，独送西南万里眸。"]},{"t":"九月八日漫成","f":"七言律诗","c":["萧萧秋径晚霜馀，寂寂风帘向月疏。","浊酒旋沽还对客，小楼翻盖且藏书。","云边露白鸿犹去，栋里巢空燕不居。","欲向寒花问生事，为谁收卷为谁舒。"]},{"t":"清明日刘黎二子携酒过访 其一","f":"七言律诗","c":["美人常苦费招寻，咫尺门庭万里心。","手简忽随双鲤至，肩舆先造百花深。","霞通苑榭明春柳，雨过桥山出暮岑。","对酒似闻清庙瑟，一歌三叹有遗音。"]},{"t":"清明日刘黎二子携酒过访 其二","f":"七言律诗","c":["官舍劳君载酒寻，病多无柰踏芳心。","孤亭岁久青松老，曲径春残碧草深。","友义昔曾称管鲍，诗名今岂下高岑。","黄鹂紫燕如知喜，并舞双飞接好音。"]},{"t":"岁除祫祭以病不与奉荅同寅白岩见怀之作","f":"七言律诗","c":["木榻香寒篝火融，晖晖残日隐房栊。","天涯风俗追随里，岁暮阴阳感慨中。","井干不消经夜雪，阶萱犹发故年丛。","端居最忆东朝士，俎豆从容未可同。"]},{"t":"冬至长陵即事","f":"七言律诗","c":["千峰隐隐下朝阳，复嶂层厓启曙光。","观阙昭回森象魏，河山表里奠金汤。","陵门月映千年树，寝殿风飘五夜香。","长至祠臣窃供奉，拟书云物纪灵祥。"]},{"t":"九日雨中登楼","f":"七言律诗","c":["八月黄河拟泛槎，为怜重九一停车。","登楼恰对冥冥雨，行径稀逢采采花。","苍树破云秋寺迥，碧山当槛暮城斜。","乡园客路俱愁寂，传语游人漫忆家。"]},{"t":"元旦","f":"七言律诗","c":["岁首江南久客身，宦情寥落道情深。","极知佳丽非吾土，且喜逢迎有故人。","城上雪痕经腊在，水边梅蕊觑年新。","呼童早蜡登山屐，莫负陶家漉酒巾。"]},{"t":"癸未元日泊龙江关","f":"七言律诗","c":["海日苍茫隐石城，正朝云物半阴晴。","暮年岁到无亲故，旧国书来有甲兵。","青柳白梅俱在眼，渚鸥沙燕亦含情。","同舟楚客醒相对，坐待春朝百感生。"]},{"t":"二月一日候朝是日予祖母寿辰","f":"七言律诗","c":["灯火春城漏下迟，薄罗寒透五更时。","莺迁上谷声初转，花隔东风信未知。","仕汉恩深惭壮业，报刘心远滞还期。","天街望处无端喜，南极光连北斗垂。"]},{"t":"万寿节","f":"七言律诗","c":["綵仗凌云启曙烟，翠华含日俯晴川。","遥怜外阃称觞地，恰是西江献捷年。","鞶锡共欢恩似海，凯歌齐祝寿同天。","微臣亦有迎銮曲，愿奏君王玉几前。"]},{"t":"郊祀斋居 其一","f":"七言律诗","c":["春树扶疏夜色轻，坐深斋沐轸遥情。","上清真气通三界，太乙祥烟接两京。","云里佩环鸣閤道，水边星斗照台城。","江湖魏阙瞻依切，欲草甘泉赋未成。"]},{"t":"郊祀斋居 其二","f":"七言律诗","c":["独火琴张伴独居，月华遥上閤帘初。","怀人忽梦春塘草，侑食聊烹雪苑蔬。","南牧烽烟时有报，北来鸿雁久无书。","玉笙声袅炉烟细，懒听仙官说步虚。"]},{"t":"少宗伯赵类庵 其一","f":"七言律诗","c":["省署行云接禁庐，戒严斋沐共端居。","箫韶恍惚闻仙乐，梦寐依稀奉属车。","台斗上公苍玉佩，阆风仙子碧霞裾。","六年嘉靖明禋礼，合有淮阴太史书。"]},{"t":"少宗伯赵类庵 其二","f":"七言律诗","c":["坐深斋閤五更天，起立梅花细雨边。","自保一心惟对越，敢云三礼是精专。","形骸已觉非前度，风景犹疑似去年。","啼彻晓鸡清不寐，更呼童子爇炉烟。"]},{"t":"斋居","f":"七言律诗","c":["琳宫仙梵柏森森，祝圣欣同海内心。","万里庙堂悬念切，十年侍从感恩深。","閒愁似雨疏还密，世事无端古又今。","却忆讲筵供奉日，已知迂拙负纶音。"]},{"t":"郊兴","f":"七言律诗","c":["礼台玄默戒宵眠，职在寅清典训传。","深院鸟惊风起树，九衢尘静月当天。","箭沉宫漏泠泠水，屏映炉香细细烟。","孤坐拥衾聊假寐，梦魂依约翠华边。"]},{"t":"中元陪祀孝陵","f":"七言律诗","c":["千溪环合万虫吟，陵邑秋回碧草深。","香度石坛云晻霭，钟流山殿气阴森。","乾坤圣祖经营力，霜露文孙感怆心。","惆怅礼台供奉客，黑头今已二毛侵。"]},{"t":"入坛马上","f":"七言律诗","c":["楼头钟散曙烟微，城上旗翻晓日晖。","双马共依南陌度，群鸦争入上阳飞。","离郊荐岁先农事，甲帐屯云护帝畿。","三载太常无寸补，敢言身迹与心违。"]},{"t":"斋居候驾","f":"七言律诗","c":["圜丘围绕万松青，石磴萦纡忆旧经。","乘月试观仙陛乐，倚风遥听属车铃。","力堪供奉丁年健，心到斋明午夜醒。","欲效杜陵歌大礼，书成谁为达皇扃。"]},{"t":"寄秦凤山少司徒","f":"七言律诗","c":["静依高閤抚年芳，万里霜云接塞长。","南郭雨晴山自碧，北风时到菊犹黄。","羞将老病干明主，几对琴樽忆侍郎。","莫枉高情赋招隐，水东篱落未全荒。"]},{"t":"奉寄白岩太宰","f":"七言律诗","c":["一抛簪组别朝行，四见青春日载阳。","敌少更无临局苦，心开惟有看山忙。","阶兰过雨娟娟秀，庭柏凌云矫矫长。","龙气夜来西贯斗，冶人遥识是干将。"]},{"t":"春日有怀空同李子","f":"七言律诗","c":["南中数枉故人书，北上蹉跎信转疏。","四海酒杯形影外，十年诗草梦魂馀。","藏身笑我同方朔，作赋怜君过子虚。","春入吹台芳草遍，塔云楼月近何如。"]},{"t":"寇中丞北抚宣府奉同南渠韵 其一","f":"七言律诗","c":["云州烽火入云中，忾敌知君久在戎。","追北远劳燕将出，防秋行与汉时同。","天从上谷分边界，人自东山识谢公。","珍重庙堂柔远意，禦戎元不重奇功。"]},{"t":"荅函山希尹","f":"七言律诗","c":["吏曹清雅复谁如，三载淮阴远谪居。","岂谓风蓬叹流转，久从霄汉拟迁除。","子平实有归田赋，公干虚传卧病书。","乘月共怜霜燕起，悲鸣犹是落弦馀。"]},{"t":"荅蒲汀问病","f":"七言律诗","c":["曲寝真应蛰蠖如，傍人虚拟好端居。","走庭风叶从摇落，绕榻霜英倦扫除。","日下紫云徒有梦，海东黄鹤久无书。","玉堂知旧劳相问，五十三年老病馀。"]},{"t":"春日寄南曹故人","f":"七言律诗","c":["白门杨柳石桥边，尚忆金陵吏隐年。","独夜有怀通梦寐，五云回首隔风烟。","凤凰台古江应绕，鳷鹊楼高月自悬。","省寺故人元不少，南音谁附北鸿传。"]},{"t":"寄岳丈胡公","f":"七言律诗","c":["云卧东山榻已牢，梦魂稀入紫宸朝。","谁言驷马如高枕，未许黄封胜浊醪。","移艇日陪渔父坐，杖藜时赴野人招。","沧浪歌罢康衢舞，白眼青天兴转豪。"]},{"t":"石桥驿逢詹进士赴京","f":"七言律诗","c":["六年云卧别京畿，万里重来旧侣稀。","紫陌已无尘可拂，玄都惟有燕交飞。","寻芳上苑花迎佩，待漏东朝月满衣。","乡土尚留司马迹，驷车他日看荣归。"]},{"t":"赠毛东塘","f":"七言律诗","c":["豪雄气盖三千界，按部春回几万家。","风采独教天下想，文章偏得士林誇。","耶溪饮兴芙蓉棹，闽峤诗情荔子花。","应忆旧游惊物换，梁台新柳欲藏雅。"]},{"t":"八月八日太常例不习仪五鼓起坐有怀成均诸公","f":"七言律诗","c":["爽气侵帘夜转森，怀人空抱雨中心。","漏沉壶水彤楼迥，烛映轩阶碧草深。","自分巢由须属我，共传尧舜是当今。","凤凰池上明良曲，林下应闻大雅音。"]},{"t":"病中赠东塘先生归","f":"七言律诗","c":["驿亭春柳曙阴阴，送客聊为黄鹄吟。","岁月秪堪惊聚散，路岐何必问升沉。","风行西下论兵地，日鉴东周品士心。","醒眼未开涓滴酒，病怀离绪海同深。"]},{"t":"秋官刘美之使还居接待院出访","f":"七言律诗","c":["行尽梁河与汴山，杪秋南出暮春还。","极知风采元无比，莫怪驰驱不暂閒。","城绕乱蛙青草路，寺临流水夕阳湾。","诗坛旧驾高千尺，一榻清风喜重攀。"]},{"t":"王舍人招予不至坐客联句见促马上","f":"七言律诗","c":["晚来扶醉过城西，路出回塘复渡溪。","座上多情重折简，社中诗好预分题。","青穿石径苔新破，绿转沙堤柳欲迷。","瘦马未前心已到，却从何处觅霜蹄。"]},{"t":"奉荅白岩诸公见怀联句","f":"古风","c":["瞑鸟催归出寺门，长安风色已黄昏。","林塘只隔水西渡，溪径故妨花外尊。","星列?垣占聚榻，月斜银浦怯回辕。","清宵咫尺怀人地，海北天南未可论。"]},{"t":"奉赠储柴墟太仆阅马山东二首 其一","f":"七言律诗","c":["龙陛香烟晓曳绅，鸡声催发使车频。","维扬城郭乡心远，鲁卫山川客路新。","天下可应无骏骨，鞭头犹见说烽尘。","风霜处处逢摇落，谁识行䄡别有春。"]},{"t":"奉赠储柴墟太仆阅马山东二首 其二","f":"七言律诗","c":["简命争誇出使荣，离筵深坐梵堂清。","同怜宦客翻为主，却喜山僧亦与盟。","荒甸晓钟淮海梦，杪秋烟树蓟门行。","何时相忆不相见，腊月梅花二月莺。"]},{"t":"坐上奉赠白岩少卿","f":"七言律诗","c":["淮阴庙前沙路微，井陉口下行人归。","丘园别后青松老，关塞经过旧垒稀。","骎骎羽骑联春甸，隐隐山城启夕扉。","却顾太行应叹息，十年空望白云飞。"]},{"t":"赠殷文济","f":"七言律诗","c":["几日逢君即送君，客堂卮酒不成醺。","途遥共说须加饭，病起谁教却避荤。","惊月啼乌还绕树，向风离马亦嘶群。","同心落落京华少，寄我音书莫厌勤。"]},{"t":"九月十四日夜访马尚宝文明不值","f":"七言律诗","c":["门巷阴阴暮雀飞，北城灯火望熹微。","可怜明月映疏柳，更喜秋风吹客衣。","寒露始零鸿渐少，重阳却过菊犹稀。","子长素有登临兴，何处淹留乐未归。"]},{"t":"寄刘铜仁","f":"七言律诗","c":["地阔天长柰尔何，春风门巷少经过。","遥怜白发星星短，无那风尘日日多。","怀旧独吟平子赋，感时偏忆少陵歌。","江村细雨蘼芜长，是处扁舟有钓蓑。"]},{"t":"月下赠孙生","f":"七言律诗","c":["月出东城光皎然，踏歌归去马翩翩。","风尘醉别三秋暮，乡土交情十载前。","侠气早闻探虎穴，壮心时为舞龙泉。","长安九陌烟花地，无事飘零又一年。"]},{"t":"书怀荅吴东昌元亨","f":"七言律诗","c":["兴如张翰在莼鲈，愁似三闾屈大夫。","桑梓旋开樵父径，梦魂稀到帝王都。","病登山閤思黄鹄，泪洒丘园扫绿芜。","群盗不休戎马乱，厌听州郡说飞刍。"]},{"t":"十月十三日高唐会石峰陈提学同赋","f":"七言律诗","c":["北海南云递渺茫，宦情乡思共悠长。","连床喜见风流在，同榜犹传姓字香。","柏署高秋惊燕雀，山城薄暮下牛羊。","如何不醉还成别，孤负霜天月满墙。"]},{"t":"别后有怀石峰","f":"七言律诗","c":["忆昨相逢赋梦鱼，古槐凉月小堂虚。","通家更许诸郎见，得句先教子弟书。","却计此行千里外，定知重会几年馀。","同官我亦司文教，事事深惭迥不如。"]},{"t":"除夕卧病柬空同李子","f":"七言律诗","c":["天涯卧病惊除夕，河上逢人感昔游。","岁月浮生双鸟翼，风尘远道一狐裘。","君还岂为鲈鱼脍，我出真同雪夜舟。","梅蕊柳条俱动色，几时携杖并登楼。"]},{"t":"赠春山李侍御","f":"七言律诗","c":["往岁麻衣出宋中，黄巾流乱太行东。","天王诏下军符急，御史兵来贼垒空。","筹策自同诸葛亮，谏书人比息夫躬。","可怜回首过逢地，万井春烟袅暮风。"]},{"t":"丁丑元夕宴一斋殿下所先以事归五华杨先生赋诗见忆仰荅并酬谢一斋","f":"七言律诗","c":["楼外栖禽夜不惊，楼中月上霁多情。","庭花欲放先春色，几瑟虚含太古声。","兴是剡溪催返棹，句飞东野故逃盟。","灯衢醉拂流尘转，转忆王孙殿閤清。"]},{"t":"赠王汝立推府之安庆","f":"七言律诗","c":["奕世簪袍袭主荣，两朝科第接家声。","皋陶独守虞廷典，贾谊同归汉史评。","藩閤暮云回望地，郡堂秋月坐吟情。","褒名喜入观风草，不待三年政已成。"]},{"t":"商水得许廷纶诗奉报二首 其一","f":"七言律诗","c":["涉尽蛮溪与瘴湾，转因家难得身閒。","应怜白发恩难报，颇怪青云兴独悭。","在野有时看射虎，杖藜随处约登山。","泥蟠雾隐真虚拟，西北王师尚未班。"]},{"t":"商水得许廷纶诗奉报二首 其二","f":"七言律诗","c":["日射蒸途潦接湾，客车何处可投閒。","愁中鬓发年年别，病里篇章字字悭。","长忆许公兼许子，却逢商水慕商山。","同朝故地分明记，白玉墀东第二班。"]},{"t":"赠临漳陈教谕","f":"七言律诗","c":["白首谈经独可嘉，学宫桃李灿春花。","十年镇日甘藜藿，万里何曾问室家。","河甸客装冲雪冷，国门贤路入云赊。","临分未有琼琚报，愧尔殷勤赠木瓜。"]},{"t":"人日荅何李二子见怀之作","f":"七言律诗","c":["夹道烟花十二楼，大梁歌吹古名州。","当年尚忆愁中过，此日那教病里游。","司马调高真寡和，谪仙情重若为酬。","青灯白发春堂晚，卧叹年华似水流。"]},{"t":"何子元参政迁秩太仆走贺二首 其一","f":"七言律诗","c":["京洛煌煌尺五天，姓名今喜万人传。","中州节钺分藩地，西极风尘出塞年。","新职似同还典午，旧游争说是登仙。","河梁别意真堪画，谁起江门沈石田。"]},{"t":"何子元参政迁秩太仆走贺二首 其二","f":"七言律诗","c":["东风环佩促朝天，苦恨离杯阻共传。","一卧即今看累月，并游真复是何年。","閒情谩忆朝中旧，多病难逢海上仙。","芳草碧山俱不恶，拟从春日赋归田。"]},{"t":"柬李朝信同年","f":"七言律诗","c":["古驿炎荒远谪丞，晚从台省见飞腾。","开渠实并西门豹，击水虚疑北海鹏。","二月寿筵双翠柏，十年官舍一清冰。","昨来詹尹传消息，闻说先生自此升。"]},{"t":"临颍与贾学士夜坐","f":"七言律诗","c":["霁雨帘栊暮色澄，病来肢体坐难胜。","十年尘土馀双鬓，万事悲欢付一灯。","却对渚云瞻紫极，转怀江水说金陵。","玉堂本是清寒地，可道官衔只似冰。"]}]};